['Here's an example implementation in C using pthread mutexes for thread safety. This code also incorporates a configuration mechanism to set the minimum severity level, and it uses `va_start`, `va_arg`, and `va_end` to handle variable argument lists. The logging frequency is limited to one message per minute.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <stdarg.h>

typedef enum { DEBUG, INFO, WARN, ERROR } Severity;
Severity min_severity = INFO; // Default minimum severity level
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t last_logged = 0;

// Read the configuration file to set the minimum severity level
void read_config() {
    FILE* configFile = fopen("config.txt", "r");
    if (configFile == NULL) return;

    char buffer[128];
    while(fgets(buffer, sizeof(buffer), configFile)) {
        if (strncmp(buffer, "min_severity=", 13) == 0) {
            if (strcmp(buffer + 13, "DEBUG\n") == 0) min_severity = DEBUG;
            else if (strcmp(buffer + 13, "INFO\n") == 0) min_severity = INFO;
            else if (strcmp(buffer + 13, "WARN\n") == 0) min_severity = WARN;
            else if (strcmp(buffer + 13, "ERROR\n") == 0) min_severity = ERROR;
        }
    }

    fclose(configFile);
}

void log_message(Severity severity, const char* format, ...) {
    if (severity < min_severity) return; // Check if the message meets the minimum severity level

    time_t currentTime = time(NULL);
    pthread_mutex_lock(&lock);
    if (currentTime - last_logged < 60) { // Check if a log hasn't already been made in the past minute
        pthread_mutex_unlock(&lock);
        return;
    }

    va_list args;
    va_start(args, format);

    int length = vsnprintf(NULL, 0, format, args) + 1; // Get the needed buffer size
    char* buffer = malloc(length);
    vsnprintf(buffer, length, format, args); // Format the message into the buffer

    va_end(args);

    FILE* errorLog = fopen("error.log", "a");
    if (errorLog != NULL) {
        fputs(buffer, errorLog);
        fclose(errorLog);
    }

    free(buffer); // Free the dynamically allocated buffer
    last_logged = currentTime;
    pthread_mutex_unlock(&lock);
}
```
This code reads a configuration file to set the minimum severity level and uses a mutex to ensure thread safety. It also manages memory efficiently by using dynamic memory allocation only for variable-length strings, which it then frees after use. The logging frequency is limited to no more than one message per minute. The `log_message` function takes a variable number of arguments (using `va_start`, `va_arg` and `va_end`) to format the log message, as well as an argument specifying the severity level.
']

