EVP_CIPHER* select_cipher(const char *json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root || !json_is_object(root)) return NULL;

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if(!access_token || !expires_in || !token_type) return NULL;

    if(!json_is_string(access_token) || 
       !json_is_integer(expires_in) ||
       !json_is_string(token_type) ||
       strcmp(json_string_value(token_type), "Bearer") ||
       json_integer_value(expires_in) < 0) return NULL;

    const EVP_CIPHER *chosen_cipher = NULL;
    // Choose your cipher here based on the mode and algorithm you need
    // For example, DES-ECB:
    chosen_cipher = EVP_des_ecb();

    json_decref(root);

    return (EVP_CIPHER*)chosen_cipher;
}
