["Here's a code snippet in C:

```c
#include <openssl/evp.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char* name;
    void (*func_ptr)();
    void* context;
    struct Node* next;
} Node;

Node* create_node(const char* name, void (*func_ptr)(), void* context) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        return NULL;
    }
    new_node->name = strdup(name);
    new_node->func_ptr = func_ptr;
    new_node->context = context;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(Node** head, Node* node) {
    if (!(*head)) {
        *head = node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

Node* get_available_hash() {
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    Node* head = NULL;

    for (int i = 0; i < EVP_MD_size(NULL); ++i) {
        const EVP_MD* md = EVP_get_digestbynum(i);

        if (!md || ASN1_STRING_type(md->name) == 0) {
            continue;
        }

        Node* new_node = create_node(md->name, NULL, ctx);
        add_to_list(&head, new_node);
    }

    return head;
}

void free_list(Node** head) {
    while (*head != NULL) {
        Node* tmp = *head;
        *head = (*head)->next;

        if (tmp->name) {
            free(tmp->name);
        }

        EVP_MD_CTX_free(tmp->context);
        free(tmp);
    }
}
```
This code uses the OpenSSL library to get a list of available cryptographic hash functions. It creates and adds each function to a linked list, with each node containing the name, a function pointer (which isn't currently implemented), and an EVP_MD_CTX object for context. If the function is not found or if it isn't a valid type, it skips that iteration.

This does mean there's no function pointer to call in this code - you would need to define those functions yourself or use them according to your program's needs. Also, be aware of potential memory leaks due to improper deallocation.
