['Sure, here is your C++ program that implements a high-performance thread-safe random number generator service:

```cpp
#include <random>
#include <chrono>
#include <vector>
#include <mutex>
#include <thread>

namespace RandomService {
    class GeneratorPool {
        std::vector<std::mt19937> generators;
        std::mutex mtx;

        void resize(size_t newSize) {
            std::lock_guard<std::mutex> lock(mtx);
            for (size_t i = generators.size(); i < newSize; ++i) {
                auto seed = std::chrono::high_resolution_clock::now().time_since_epoch().count() + std::hash<std::thread::id>{}(std::this_thread::get_id()) + i;
                generators.push_back(std::mt19937(seed));
            }
        }
    public:
        GeneratorPool(size_t initialSize = 0) {
            resize(initialSize);
        }

        int nextInt() {
            std::lock_guard<std::mutex> lock(mtx);
            if (generators.empty()) throw std::runtime_error("No generators available");
            auto& gen = generators[0];
            generators.erase(generators.begin());
            int result;
            try {
                result = static_cast<int>(gen() - gen.min());
            } catch (...) {
                generators.insert(generators.begin(), std::move(gen));
                throw;
            }
            generators.push_back(std::move(gen));
            return result;
        }

        double nextDouble() {
            std::lock_guard<std::mutex> lock(mtx);
            if (generators.empty()) throw std::runtime_error("No generators available");
            auto& gen = generators[0];
            generators.erase(generators.begin());
            double result;
            try {
                result = static_cast<double>(gen() - gen.min()) / (gen.max() - gen.min());
            } catch (...) {
                generators.insert(generators.begin(), std::move(gen));
                throw;
            }
            generators.push_back(std::move(gen));
            return result;
        }
    };
}  // namespace RandomService
```
']

['Here is an example implementation for your requirement using `System.Data` namespace from .NET framework:

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class SQLQueryHelper
{
    public static List<Dictionary<string, object>> ExecuteDynamicQuery(SqlConnection connection, string schemaName, IEnumerable<string> fieldsToSelect)
    {
        var result = new List<Dictionary<string, object>>();

        // Safely escape user input and construct SQL query
        var escapedFields = fieldsToSelect.Select(f => $"[{f.Replace("]", "``]}").Replace("'", "''")}]"); 
        var query = $"SELECT {string.Join(", ", escapedFields)} FROM [{schemaName}]";

        using (var command = new SqlCommand(query, connection))
        using (var reader = command.ExecuteReader())
            while (reader.Read())
                result.Add(GetRowAsDictionary(reader));

        return result;
    }

    private static Dictionary<string, object> GetRowAsDictionary(IDataRecord record)
    {
        var dict = new Dictionary<string, object>();

        for (var i = 0; i < record.FieldCount; i++)
            dict[record.GetName(i)] = record.IsDBNull(i) ? null : record.GetValue(i);

        return dict;
    }
}
```

This code does not handle schema changes gracefully, because handling potential schema changes would require a more sophisticated approach that checks for the existence of specific columns in the result set and handles errors accordingly. This can make the code much more complex and less efficient. For example, you could use SqlDataReader.GetSchemaTable() to get the schema of the returned data and compare it with your expected fields.

Please remember this is just an example, adjust according to your actual requirements. It's always a good practice to sanitize your inputs before using them in a query to avoid SQL injection attacks. 

Also, error handling needs to be added for the cases like connection failure or schema doesn't exist etc. For performance optimizations, you may consider things like: caching prepared statements, reducing network calls, etc based on your specific use case.
