using System;
using System.Net;
using System.Threading;
using Microsoft.AspNetCore.Mvc;

public class MyController : ControllerBase
{
    private readonly ISessionService _sessionService;
    private readonly IElementService _elementService;

    public MyController(ISessionService sessionService, IElementService elementService)
    {
        _sessionService = sessionService;
        _elementService = elementService;
    }

    [HttpPost]
    public ActionResult<string> UpdateHtmlContent([FromBody] UpdateRequest request)
    {
        if (!_sessionService.ValidateSession(request.Token))
            return Unauthorized();

        var lockObj = new object();
        Monitor.Enter(lockObj); // Ensure atomicity of the operation to prevent race conditions.

        try
        {
            _elementService.UpdateElementHtmlContent(request.SectionId, request.ElementId, request.HtmlContent);
        }
        finally
        {
            Monitor.Exit(lockObj);
        }

        return Ok("Page should be refreshed.");
    }
}

public class UpdateRequest
{
    public string Token { get; set; }
    public int SectionId { get; set; }
    public int ElementId { get; set; }
    public string HtmlContent { get; set; }
}
```
