['Sure, here's a skeleton of the Java class with your requirements included:

```java
import java.io.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import java.security.MessageDigest;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.apache.commons.codec.binary.Hex;

public class MoSTStateLoader {
    private final Object lock = new Object();

    public MoSTState load(String fileName, String metadataFileName) throws IOException {
        MessageDigest md = null;
        FileInputStream fis = null;
        BufferedReader br = null;
        CRC32 crc = new CRC32();
        ObjectInputStream ois = null;

        try {
            md = MessageDigest.getInstance("MD5");

            synchronized (lock) {
                fis = new FileInputStream(fileName);

                byte[] dataBytes = Files.readAllBytes(Paths.get(metadataFileName));
                String storedChecksum = new String(dataBytes, "UTF-8");

                crc.update(fis.readAllBytes());
                String currentChecksum = Hex.encodeHexString(md.digest()).toUpperCase();

                if (!storedChecksum.equals(currentChecksum)) {
                    System.out.println("Warning: file checksums do not match!");
                    return null;
                }

                fis = new FileInputStream(fileName); // Reopen the stream after reading metadata
                ois = new ObjectInputStream(fis);

                MoSTState stateObj = (MoSTState) ois.readObject();

                if (!(stateObj instanceof MoSTState)) {
                    throw new IOException("Invalid instance of MoSTState class");
                }

                return stateObj;
            }
        } catch (IOException | ClassNotFoundException e) {
            throw new IOException("Failed to load state object", e);
        } finally {
            if (ois != null) ois.close();
            if (fis != null) fis.close();
            if (br != null) br.close();
        }
    }
}
```
This code uses the CRC32 class from java.util.zip for computing a checksum of the file contents and Apache Commons Codec for encoding the byte array to hexadecimal string. It uses synchronized block for concurrent access handling, but it may not be suitable in some high-concurrency scenarios due to performance overheads.
']

