Here is a simple implementation of this:

```javascript
// Import the necessary modules
const neo4j = require('neo4j-driver');

// Define a driver and session for Neo4j Database
let driver;
if (!driver) {
    // Connect to database and establish session
    driver = neo4j.driver("bolt://localhost:7687", neo4j.auth.basic("neo4j", "password"));
}
const session = driver.session();

// Function to add a vertex with random properties in the graph database
function addVertex(properties) {
    const query = `CREATE (a:Node ${formatProperties(properties)}) RETURN a`;
    return session.run(query);
}

// Function to add an edge between two vertices with random properties in the graph database
function addEdge(node1, node2, properties) {
    const query = `MATCH (a:Node),(b:Node) WHERE id(a)=${node1} AND id(b)=${node2} CREATE (a)-[:RELATION ${formatProperties(properties)}]->(b) RETURN a, b`;
    return session.run(query);
}

// Function to format the properties for query 
function formatProperties(properties) {
    let propsString = '';
    Object.keys(properties).forEach((key, i) => {
        if (i === 0) {
            propsString += `{${key}: '${properties[key]}'`;
        } else {
            propsString += `, ${key}: '${properties[key]}'`;
        }
        if (i === Object.keys(properties).length - 1) {
            propsString += '}';
        }
    });
    return propsString;
}

// Sample usage:
addVertex({name: "Node1", value: Math.random()}).then(result => console.log("Added node with id: " + result.records[0].get('a').identity));
```

