["```javascript
const { BufferList } = require('bl');
let lastBufferCopyStartTime;
let lastBufferCopyEndTime;

function copyDataToNewBuffer(dataChunks, size) {
    const blStream = new BufferList();
    let bytesCopied = 0;

    // Log the start time of the buffer copy operation
    lastBufferCopyStartTime = Date.now();

    for (let i = 0; i < dataChunks.length && bytesCopied < size; i++) {
        const chunkSize = Buffer.byteLength(dataChunks[i]);
        if (chunkSize <= size - bytesCopied) {
            blStream.append(dataChunks[i]);
            bytesCopied += chunkSize;
        } else {
            const chunkSlice = dataChunks[i].slice(0, size - bytesCopied);
            blStream.append(chunkSlice);
            bytesCopied += Buffer.byteLength(chunkSlice);
        }
    }

    // Log the end time of the buffer copy operation and the total data copied
    lastBufferCopyEndTime = Date.now();
    console.log('Buffer copy completed in', 
               (lastBufferCopyEndTime - lastBufferCopyStartTime), 'ms, copied', bytesCopied, 'bytes');

    return blStream;
}
```
