    private static final int MAX_DELAY = 5000; // in ms

    public void manageServiceAndModifyConfig(Map<String, String> dict, Pokemon pokemon) throws Exception {
        startStopService();

        if (!dict.containsKey("placeholder1") || !dict.containsKey("placeholder2")) {
            throw new IllegalArgumentException("Dictionary is missing necessary placeholder values.");
        }

        String pokemonName = pokemon.getName();
        String weaknesses = determineWeaknesses(pokemon);

        if (weaknesses == null) {
            throw new Exception("Failed to retrieve Pokemon's weaknesses.");
        }

        dict.put("placeholder1", pokemonName);
        dict.put("placeholder2", weaknesses);
        modifyConfigFile(dict, CONFIG_FILE);
    }

