        for ($i = 0; $i < $this->length; $i++) {
            $index = rand(0, strlen($this->charset) - 1);
            $string .= $this->charset[$index];
        }

        $startTime = microtime(true);
        $isUnique = $this->checkStringUniqueness($string);
        $endTime = microtime(true);

        echo 'Execution time: ', ($endTime - $startTime), PHP_EOL;
        if (!$isUnique) {
            return $this->generateString();
        }

        return $string;
    }

    public function hashPassword($password) {
        return password_hash($password, PASSWORD_DEFAULT);
    }

    private function checkStringUniqueness($string) {
        $response = @file_get_contents($this->apiUrl . '/' . $string);

        if ($response === false || !is_array(json_decode($response, true))) {
            sleep(10); // Retry after 10 seconds in case of timeout or unavailability.
            $this->checkStringUniqueness($string);
        }

        $data = json_decode($response, true);
        if (isset($data['is_unique']) && $data['is_unique'] === false) {
            return false;
        }

        return true;
    }
}
``` 

