<?php
function updateUserPassword($userId, $newPassword) {
    $minLength = 8;
    $maxLength = 16;

    // Validate password strength.
    if (strlen($newPassword) < $minLength || strlen($newPassword) > $maxLength) {
        throw new Exception("Invalid password length.");
    }

    // Assuming you have an array of databases and caches.
    $databasesAndCaches = [$db1, $db2, $cache1, $cache2];

    try {
        $backoff = 0;
        for ($i = 0; $i < getenv('RETRY_LIMIT'); $i++) {
            try {
                // Start a transaction.
                $transactionSuccess = true;

                foreach ($databasesAndCaches as $dbOrCache) {
                    if (!$dbOrCache->beginTransaction()) {
                        throw new Exception("Failed to start transaction.");
                    }
                }

                // Update the password in each database.
                foreach ($databasesAndCaches as $dbOrCache) {
                    $result = $dbOrCache->query('UPDATE Users SET Password = ? WHERE UserId = ?', [$newPassword, $userId]);
                    if (!$result) {
                        $transactionSuccess = false;
                        break;
                    }
                }

                // If everything was successful, commit the transaction.
                if ($transactionSuccess) {
                    foreach ($databasesAndCaches as $dbOrCache) {
                        $dbOrCache->commit();
                        $backoff = 0;  // Reset backoff on success.
                    }

                    // Invalidate caches.
                    $this->invalidateUserPasswordCaches($userId);
                } else {
                    foreach ($databasesAndCaches as $dbOrCache) {
                        $dbOrCache->rollBack();
                    }
                }
            } catch (Exception $e) {
                // Log the exception.
                error_log($e->getMessage());

                if ($i < getenv('RETRY_LIMIT') - 1) {
                    // Exponential backoff strategy.
                    $backoff = pow(2, $i);
                    sleep(getenv('BACKOFF_INTERVAL') * $backoff + rand(0, 1000) / 1000);
                } else {
                    throw new Exception("Failed to update user password after multiple attempts.");
                }
            }
        }
    } catch (Exception $e) {
        // Handle exception and log it.
        error_log($e->getMessage());
        return false;
    }

    return true;
}
?>
``` 
