```cpp
#include <iostream>
#include <chrono>
#include <vector>
#include <unordered_map>

struct Attack {
    int id;
    std::string name;
    double cooldown;
    long long lastUsedTimeStamp;  // Time when attack was used (in milliseconds)
};

class MMOGame {
public:
    MMOGame() : attacks{
        {1, "Attack A", 6.0, 0},
        {2, "Attack B", 9.0, 0},
        {3, "Attack C", 12.0, 0}
    } {}

    void performAttack() {
        Attack* selectedAttack = nullptr;
        double currentTimeStamp = getCurrentTimestamp();
        double smallestCooldown = std::numeric_limits<double>::max();

        for (auto& attack : attacks) {
            if (currentTimeStamp - attack.lastUsedTimeStamp > attack.cooldown && 
                currentTimeStamp - attack.lastUsedTimeStamp < smallestCooldown) {

                selectedAttack = &attack;
                smallestCooldown = currentTimeStamp - attack.lastUsedTimeStamp;
            }
        }

        if (selectedAttack != nullptr) {
            std::cout << "Performing Attack: " << selectedAttack->id << " Name: " << selectedAttack->name << "\n";
            selectedAttack->lastUsedTimeStamp = currentTimeStamp;
        } else {
            std::cout << "All attacks are on cooldown. Please wait.\n";
        }
    }

private:
    double getCurrentTimestamp() {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
                   std::chrono::system_clock::now().time_since_epoch())
            .count();
    }

    std::vector<Attack> attacks;  // Store all the attacks and their cooldown info
};
```
The `performAttack` function selects an attack with smallest cooldown. This means that the system tries to evenly distribute attacks across all available attacks based on their cooldown times. However, it doesn't take into account network latency or packet loss as they are considered out of scope for this problem. 

