['```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public abstract class ValueGenerator<T> where T : IComparable<T>
{
    private Random _random = new Random();
    protected List<T> _history = new List<T>();

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }

    public abstract T GenerateRandomValueInclusive(T min, T max);

    public abstract T GenerateRandomValueExclusive(T min, T max);

    protected bool IsValidRange(T min, T max)
    {
        return min.CompareTo(max) <= 0;
    }

    public List<T> GenerateSequence(int count, T min, T max, bool isInclusive = true)
    {
        if (!IsValidRange(min, max))
            throw new ArgumentException("Invalid range.");

        var sequence = new List<T>();

        while (sequence.Count < count)
        {
            T value;
            do
            {
                value = isInclusive 
                    ? GenerateRandomValueInclusive(min, max) 
                    : GenerateRandomValueExclusive(min, max);
            } while (_history.Contains(value));

            sequence.Add(value);
        }

        _history.AddRange(sequence);

        return sequence;
    }

    public override string ToString()
    {
        var uniqueValues = _history.Distinct().Count();

        return $"Current Range: [{_history.Min()}, {_history.Max()}], " +
               $"Seed Used: {_random.GetHashCode()}, " +
               $"Unique Values Generated So Far: {uniqueValues}";
    }
}

public class RandomValueGenerator : ValueGenerator<double>
{
    public override double GenerateRandomValueInclusive(double min, double max)
    {
        return _random.NextDouble() * (max - min) + min;
    }

    public override double GenerateRandomValueExclusive(double min, double max)
    {
        return GenerateRandomValueInclusive(min + 1e-6, max - 1e-6);
    }
}
```
Please note that due to the nature of randomness and floating point arithmetic precision issues, `GenerateSequence` method with isInclusive=false might not be able to generate enough distinct values for some ranges. In such cases, consider using a different approach or increasing the range. 
Also, please note that there's no perfect solution for generating unique random numbers in a given range for large sequences and ranges due to the pigeonhole principle. If you need truly unique values, you might have to limit your sequence count accordingly.
']

["Here is a code block implementing an asynchronous reduction function in JavaScript:

```javascript
async function asyncReduce(array, reducer, initialValue) {
  let accumulator = initialValue;

  for (const element of array) {
    try {
      const resultPromise = await Promise.resolve(reducer(accumulator, element));

      if (resultPromise instanceof Promise) {
        throw new Error('Reducer returned a promise');
      }

      accumulator = resultPromise;
    } catch (error) {
      console.log('Error during reduction:', error);
      return 'Failed to reduce array';
    }
  }

  return accumulator;
}
```

The `asyncReduce` function takes three arguments: the input array, a reducer function that takes an accumulated value and an element from the array and returns the new accumulated value, and an initial accumulator value. The function iterates over each item in the input array asynchronously, applying the callback to the current accumulated value and the current array element.

The reducer result is awaited ensuring that we handle promises correctly and don't deadlock or hang due to synchronous operations blocking the asynchronous flow. The `Promise.resolve` function ensures the resolver value isn't a promise itself, throwing an error if it is.

The accumulated value is updated with the result of the reducer function after awaiting it. If an error occurs during this process, the function logs the error and returns a failure message. If no errors occur, the final accumulated value is returned.

You can test this function as follows:

```javascript
const sum = (total, num) => total + num; // reducer that sums numbers

// Test with normal input
console.log(asyncReduce([1, 2, 3, 4], sum, 0)); // Expected output: 10

// Test with partially resolved promise within the callback
const sleepThenReturn = num => new Promise(resolve => setTimeout(() => resolve(num), 50));
console.log(asyncReduce([1, 2, 3, 4], sleepThenReturn, 0)); // Expected output: 10 after delay
```
"]

