```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char **names;
    int *types;
    size_t *sizes;
    int count;
} ResourceReport;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

ResourceReport* loadResourcesFromFile(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL; // return appropriate error code
    }

    ResourceReport *report = malloc(sizeof(ResourceReport));
    report->names = malloc(0);
    report->types = malloc(0);
    report->sizes = malloc(0);
    report->count = 0;

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        pthread_mutex_lock(&lock);

        report->names = realloc(report->names, (report->count + 1) * sizeof(char*));
        report->types = realloc(report->types, (report->count + 1) * sizeof(int));
        report->sizes = realloc(report->sizes, (report->count + 1) * sizeof(size_t));

        // Assuming each line in the file represents a resource, 
        // and we extract name, type, and size from it.
        char *name;
        int type;
        size_t size;
        sscanf(buffer, "%ms %d %zu", &name, &type, &size);

        report->names[report->count] = name;
        report->types[report->count] = type;
        report->sizes[report->count] = size;

        report->count++;

        pthread_mutex_unlock(&lock);
    }

    fclose(file);

    return report;
}

void freeResourceReport(ResourceReport *report) {
    for (int i = 0; i < report->count; i++) {
        free(report->names[i]);
    }
    free(report->names);
    free(report->types);
    free(report->sizes);
    free(report);
}
```
