#define MAX_SIZE 1024

typedef struct {
    char buffer[MAX_SIZE];
    pthread_mutex_t lock;
} Logger;

Logger logger = {{0}, PTHREAD_MUTEX_INITIALIZER};

char* appendSlash(const char* input, size_t limit, char* outputBuffer) {
    if (!input || !outputBuffer) return NULL;  // Error handling for null buffer

    pthread_mutex_lock(&logger.lock);

    const size_t length = strlen(input);

    LoggerMessage("Received input string of length %zu and limit is %zu.", length, limit);

    if (length > limit) {
        LoggerMessage("String exceeds limit. Returning NULL.");
        pthread_mutex_unlock(&logger.lock);
        return NULL;  // Error handling for input size exceeding limit
    }

    snprintf(outputBuffer, MAX_SIZE, "%s/", input);  // Append slash to output buffer directly

    LoggerMessage("String within limit. Returned modified buffer: %s.", outputBuffer);
    pthread_mutex_unlock(&logger.lock);

    return outputBuffer;
}

void LoggerMessage(const char* format, ...) {
    va_list args;
    va_start(args, format);

    vsprintf(logger.buffer, format, args);

    printf("%s\n", logger.buffer);  // Or write to log file or any other logging mechanism

    va_end(args);
}
