```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "external_library.h" // replace this with the actual path to your library's header file

// Assume that external library defines these types and functions
typedef struct File File;
File* open_file(const char *path, const char *mode);
char* read_line(File *f);
void close_file(File *f);

int compare(const void *a, const void *b) {
    return strcmp(*(char **)a, *(char **)b);
}

int main() {
    File* file = open_file("path/to/your/file.txt", "r");

    if (file == NULL) {
        printf("Failed to open the file.\n");
        return 1;
    }

    char *line;
    double sum = 0, avg;
    while ((line = read_line(file)) != NULL) {
        int numFields = 0, textSize = 256, i, j;
        char **fields = malloc(textSize * sizeof(char*));
        fields[numFields] = strtok(line, " ");

        while (fields[numFields] != NULL) {
            numFields++;
            if (numFields >= textSize) {
                textSize += 256;
                fields = realloc(fields, textSize * sizeof(char*));
            }

            fields[numFields] = strtok(NULL, " ");
        }

        // Sort the fields.
        qsort(fields, numFields - 1, sizeof(char*), compare);

        double total = 0;
        for (i = numFields - 3; i < numFields - 1; i++) {
            char *ptr;
            double value = strtod(fields[i], &ptr);
            if (*ptr == '\0') {
                // This is a number field.
                total += value;
            } else {
                printf("Error: Field %d is not a number.\n", i + 1);
            }
        }

        avg = total / 2;
        sum += avg;
        fields[numFields - 1] = malloc(20 * sizeof(char));
        sprintf(fields[numFields - 1], "%.2f", avg);

        // Print the fields.
        for (j = 0; j < numFields; j++) {
            printf("%s ", fields[j]);
            free(fields[j]); // Don't forget to free the memory we allocated dynamically.
        }
        printf("\n");

        free(fields);
    }

    close_file(file);

    printf("Sum of averages: %.2f\n", sum);

    return 0;
}
```

This program will read a file line by line, split each line into fields, calculate the average of the last two numerical fields and sort them alphabetically. The running total of these averages is kept and printed at the end. If there's an error in converting a field to a number, it's handled and an appropriate message is shown. Note that this program assumes you have a file reading library available which provides functions to open a file, read lines from a file and close a file.
