    int uniqueIdSize = baseFileNameLen < maxLength ? baseFileNameLen : maxLength;

    char* extensionStart = strrchr(originalFilename, '.');  // Find the last '.' character in filename. If it exists, this marks the start of the extension.

    if (!extensionStart || (strlen(extensionStart) > maxLength - uniqueIdSize)) {  // If there is no extension or new length will exceed maxLength...
        char* newFilename = malloc(sizeof(char) * (uniqueIdSize + 1));  // Allocate memory for the modified filename.

        sprintf(newFilename, "%.*s", uniqueIdSize, originalFilename);  // Copy base name to new file.
        return newFilename;
    } else {
        int extensionLen = strlen(extensionStart) - 1;  // Length of the extension (excluding '.')

        char* newFilename = malloc(sizeof(char) * (uniqueIdSize + 1 + extensionLen + 2));  // Allocate memory for the modified filename.

        sprintf(newFilename, "%.*s-", uniqueIdSize, originalFilename);  // Copy base name and '-' to new file.

        int i;
        for (i = 0; i < uniqueIdSize - extensionLen; ++i) {  // Add an alphanumeric sequence as unique identifier
            if (isalnum(originalFilename[i])) {
                sprintf(newFilename, "%s%c", newFilename, originalFilename[i]);
            } else {
                sprintf(newFilename, "%s_", newFilename);  // If the character is not alphanumeric, replace it with '_'.
            }
        }

        strcat(newFilename, extensionStart + 1);  // Add extension to new filename.

        return newFilename;
    }
}
```
This function assumes that filenames can have extensions and the base of the filename is unique for each file. If this assumption doesn't hold true, additional measures should be taken. For example, the function could add a timestamp or an incrementing counter to ensure uniqueness across multiple calls with the same input. Also, it does not handle filenames without extension gracefully. In these cases, simply append unique identifier at end of filename and no need for extension handling part.
