["```c
#include <openssl/evp.h>
#include <openssl/rand.h>

// Structure to hold all data related to an AES-256-CBC cipher
typedef struct {
    EVP_CIPHER_CTX* ctx; // Encryption/Decryption context
} Aes256cbcContext;

// Function to initialize AES-256-CBC cipher and derive key using PBKDF2 KDF
Aes256cbcContext* aes256cbc_init(const char* password, const unsigned char* salt) {
    // Create new context
    Aes256cbcContext* ctx = malloc(sizeof(Aes256cbcContext));
    if (!ctx) return NULL;

    // Initialize EVP_CIPHER_CTX
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL;
    }

    // Generate a 256-bit random IV
    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(iv, sizeof(iv));

    // Derive encryption key using PBKDF2 KDF
    unsigned char* key = malloc(EVP_CIPHER_key_length(EVP_aes_256_cbc()));
    if (!key) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    // PBKDF2_HMAC_SHA_256 is a good choice for KDF, but it's not available in older versions of OpenSSL. 
    // It can be replaced by EVP_BytesToKey if you use OpenSSL 1.1.0 or newer.
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 10000, EVP_aes_256_cbc(), EVP_MAX_IV_LENGTH, key)) {
        free(key);
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    // Initialize cipher context with AES-256-CBC and the derived key and IV
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        free(key);
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    // Cleanup the key now that it's no longer needed
    free(key);

    // Return the initialized context
    return ctx;
}

// Function to encrypt data using AES-256-CBC cipher
int aes256cbc_encrypt(Aes256cbcContext* ctx, const unsigned char* plaintext, int len, unsigned char* ciphertext) {
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &len)) return 0;

    EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len);
    return len;
}

// Function to decrypt data using AES-256-CBC cipher
int aes256cbc_decrypt(Aes256cbcContext* ctx, const unsigned char* ciphertext, int len, unsigned char* plaintext) {
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &len)) return 0;

    EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len);
    return len;
}

// Function to cleanup AES-256-CBC cipher context
void aes256cbc_cleanup(Aes256cbcContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
```

Please note that the above code is for illustrative purposes only. It does not include error checking or handling of all possible edge cases, and it might need to be adapted depending on your specific requirements and environment.
