#include <stdbool.h> // To use bool data type
#include <pthread.h> // For thread safety

// Session structure definition
typedef struct {
    char* password;
    void* connectionObject;
    int (*callback)(void);
} Session;

// Error codes enumeration
enum ErrorCodes{
    PASSWORD_ERROR,
    CONNECTION_OBJECT_ERROR,
    CALLBACK_FUNCTION_ERROR,
    SUCCESS
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // For thread safety

int validateSession(Session* session) {
    if (session == NULL) return PASSWORD_ERROR; // Null pointer check

    pthread_mutex_lock(&lock); // Lock the mutex to prevent concurrent access

    int errorCode = SUCCESS;

    // Password validation check
    if(session->password == NULL || session->password[0] == '\0') {
        errorCode = PASSWORD_ERROR;
    } 
    // Connection object validation check
    else if(session->connectionObject == NULL) {
        errorCode = CONNECTION_OBJECT_ERROR;
    } 
    // Callback function validation check
    else if(session->callback == NULL) {
        errorCode = CALLBACK_FUNCTION_ERROR;
    } 

    pthread_mutex_unlock(&lock); // Unlock the mutex after checking

    return errorCode; // Returns SUCCESS code if all checks passed, else corresponding error code.
}
```
This function takes a pointer to a `Session` structure as input. It first checks for a NULL pointer and returns an appropriate error code if it is found. Then it locks the mutex to ensure thread safety while performing the validation checks. If any of the validation checks fail, the corresponding error code is returned. 

This design allows for potential null pointers by initializing the session structure with default values or NULL, and safely handles concurrent access from multiple threads through a pthreads mutex.
