#include <stdbool.h>
#include "cJSON.h"

bool validate_oauth2(const char *json) {
    const cJSON* root = cJSON_Parse(json);

    if (root == NULL) { 
        return false; // Malformed JSON
    }

    const cJSON* accessToken = cJSON_GetObjectItemCaseSensitive(root, "access_token");
    const cJSON* expiresIn = cJSON_GetObjectItemCaseSensitive(root, "expires_in");
    const cJSON* tokenType = cJSON_GetObjectItemCaseSensitive(root, "token_type");

    if (!cJSON_IsString(accessToken) || !cJSON_IsNumber(expiresIn) 
        || !cJSON_IsString(tokenType)) {
        return false; // Missing required fields or wrong type
    }

    const cJSON* refreshToken = cJSON_GetObjectItemCaseSensitive(root, "refresh_token");
    if (refreshToken && (!cJSON_IsString(refreshToken) || !strlen(refreshToken->valuestring))) {
        return false; // Refresh token is present but empty or not a string
    }

    if (strcmp(tokenType->valuestring, "Bearer") != 0) {
        return false; // Token type is not Bearer
    }

    double expiresInValue = cJSON_GetNumberValue(expiresIn);
    if (expiresInValue <= 0 || expiresInValue > INT_MAX) {
        return false; // Expires in is zero, negative or out of range for int
    }

    cJSON_Delete(root);  // free the memory used by the JSON object

    return true;
}
```
This function uses a case-sensitive parsing approach to check whether each required field exists and is of the correct type. If any checks fail, it returns `false`. Note that this function assumes that you have already linked against the cJSON library and included the appropriate headers.
