['Here is how you might implement this in C# using `async`/`await` pattern to achieve asynchronous file uploads:

```CSharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class FileUploader
{
    private readonly ICloudStorageService _cloudStorageService; // this would be your cloud storage service like AWS, Azure etc.

    public FileUploader(ICloudStorageService cloudStorageService)
    {
        _cloudStorageService = cloudStorageService;
    }

    public async Task<SummaryReport> UploadFilesAsync(List<string> filePaths)
    {
        var summaryReport = new SummaryReport();

        foreach (var filePath in filePaths)
        {
            try
            {
                if (!File.Exists(filePath))
                {
                    Console.WriteLine($"Validation error: File does not exist at path '{filePath}'");
                    summaryReport.FilesWithValidationErrors++;
                    continue;
                }

                using (var fileStream = new FileStream(filePath, FileMode.Open))
                {
                    var response = await _cloudStorageService.UploadFileAsync(fileStream);

                    if (!response.IsSuccess)
                    {
                        Console.WriteLine($"Upload error: Failed to upload file at path '{filePath}'. Error message: {response.ErrorMessage}");
                        summaryReport.FilesFailedToUpload++;
                        continue;
                    }

                    Console.WriteLine($"Successfully uploaded file at path '{filePath}'");
                    summaryReport.SuccessfulUploads++;
                }
            }
            catch (Exception ex)
            {
                // Log detailed exception information for troubleshooting 
                Console.WriteLine($"Unexpected error occurred when processing file at path '{filePath}'. Exception: {ex}");
            }
        }

        return summaryReport;
    }

    public class SummaryReport
    {
        public int SuccessfulUploads { get; set; }
        public int FilesWithValidationErrors { get; set; }
        public int FilesFailedToUpload { get; set; }
    }
}
``` 
