#define MAX_RECORDS 100
typedef struct {
    int value;
    char* buffer;
    int refCount;
} record;

typedef enum {false, true} bool;

record** records = NULL;
long* offsets = NULL;
int* keys = NULL;
bool* statuses = NULL;
char logFilePath[1024];
FILE* logFile = NULL;

void allocate_resources() {
    srand(time(NULL));  // Initialize random number generator.

    records = (record**)malloc(sizeof(record*) * MAX_RECORDS);
    offsets = (long*)calloc(MAX_RECORDS, sizeof(long));
    keys = (int*)malloc(sizeof(int) * MAX_RECORDS);
    statuses = (bool*)calloc(MAX_RECORDS, sizeof(bool));

    // Initialize each record with random values and buffers.
    for(int i = 0; i < MAX_RECORDS; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        offsets[i] = rand() % 100 + 1; // Random values between 1 and 100.
        keys[i] = rand();
        sprintf(records[i]->buffer, "Buffer_%d", records[i]->value);
    }

    strcpy(logFilePath, "/path/to/logfile");
    logFile = fopen(logFilePath, "w+");
}

void deallocate_resources() {
    for(int i = 0; i < MAX_RECORDS; ++i) {
        free(records[i]->buffer);
        free(records[i]);
    }

    fclose(logFile);

    free(offsets);
    free(keys);
    free(statuses);
}

int compare_record(const void* a, const void* b) {
    record** recordA = (record**)a;
    record** recordB = (record**)b;

    return (*recordA)->value - (*recordB)->value;  // For ascending order.
}

void sort_records(bool descendingOrder) {
    if(descendingOrder) {
        qsort(records, MAX_RECORDS, sizeof(record*), compare_record);
    } else {
        qsort(records, MAX_RECORDS, sizeof(record*), compare_record);  // This should be in descending order.
    }
}

