typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

int InitializeCipher(const char* password, const unsigned char* salt, int iterations, size_t passwordLength, size_t saltLength, CipherContext** out) {
    *out = malloc(sizeof(CipherContext));
    if (!(*out)) return 0; // Memory allocation failed

    CipherContext* ctx = *out;

    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    if (EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, password, passwordLength, iterations, ctx->key, ctx->iv) == 0) {
        free(ctx); // Failed to derive key and IV
        return 0;
    }

    if (!RAND_bytes(ctx->iv, EVP_CIPHER_iv_length(cipher))) {
        free(ctx); // Failed to generate random IV
        return 0;
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, ctx->key, ctx->iv)) {
        free(ctx); // Failed to initialize encryption context
        return 0;
    }

    return 1; // Successfully initialized cipher
}

void CleanupCipher(CipherContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
```
