import java.io.File;
import java.nio.file.*;
import java.util.*;
import static java.nio.file.Files.*;
import java.io.IOException;

public class FileSizeMapper {
    private final PathMatcher pathMatcher;
    private final long minSizeInBytes;

    public FileSizeMapper(String globPattern, long minSizeInBytes) {
        this.pathMatcher = getDefault().getPathMatcher("glob:" + globPattern);
        this.minSizeInBytes = minSizeInBytes;
    }

    public Map<String, Long> mapFileSizes(String directoryPath) throws IOException {
        File dir = new File(directoryPath);
        return getDirectorySizeMap(dir);
    }

    private Map<String, Long> getDirectorySizeMap(File folder) {
        Map<String,Long> fileMap = new HashMap<>();
        for (final File fileEntry : Objects.requireNonNull(folder.listFiles())) {
            if (fileEntry.isDirectory()) {
                fileMap.putAll(getDirectorySizeMap(fileEntry));
            } else {
                String path = fileEntry.getAbsolutePath();
                if(pathMatcher.matches(Paths.get(path))){
                    long sizeInBytes = fileEntry.length();
                    if (sizeInBytes >= minSizeInBytes) {
                        fileMap.put(path, sizeInBytes);
                    }
                }
            }
        }
        return fileMap;
    }
}
```
