#include <openssl/md5.h>  // Include OpenSSL library for MD5 hash generation

// Maximum length of URL and cache key
#define MAX_URL_LENGTH 1024
#define MAX_CACHE_KEY_LENGTH 128

char* generateUniqueCacheKey(const char* url) {
    if (url == NULL) {
        return NULL;
    }

    // Create a new string for cache key and URL copy
    char* cacheKey = malloc((MAX_CACHE_KEY_LENGTH + 1) * sizeof(char)); 
    char urlCopy[MAX_URL_LENGTH];
    strncpy(urlCopy, url, MAX_URL_LENGTH); // Make a copy of URL to preserve original URL

    // Parse the URL and extract host and path components
    char* host = strtok(urlCopy, "/"); 
    if (host == NULL) {
        free(cacheKey);
        return NULL;
    }
    char* path = strtok(NULL, ""); 

    // Check for invalid characters in URL components
    while (*host != '\0') {
        if (!isalnum((unsigned char)*host) && *host != '.' && *host != '-') {
            free(cacheKey);
            return NULL;
        }
        host++;
    }

    // Generate MD5 hash of the URL components 
    unsigned char md5[MD5_DIGEST_LENGTH];
    sprintf(cacheKey, "%s%s", host, path ? path : "");
    MD5((unsigned char*)cacheKey, strlen(cacheKey), md5);

    // Convert MD5 hash to hexadecimal string 
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&cacheKey[i*2], "%02x", md5[i]);
    }

    // Truncate cache key if it exceeds the maximum length
    cacheKey[MAX_CACHE_KEY_LENGTH] = '\0';

    return cacheKey;
}
```
