['Here is a simple and basic implementation of your requirements using a dynamic array for the semaphores and pthread mutex to ensure thread safety during resizing operations and accessing/logging operations. Please note that this code does not handle error checking or edge cases and it's intended to be a starting point, you would need to add appropriate checks according to your use case.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include "external_log.h" // replace with actual logging library

typedef struct {
    sem_t *array;
    int size;
    pthread_mutex_t lock;
} SemArray;

SemArray* createSemArray(int initialSize) {
    SemArray* array = malloc(sizeof(SemArray));
    if (!array) return NULL;

    array->array = calloc(initialSize, sizeof(sem_t));
    for (int i = 0; i < initialSize; ++i) 
        sem_init(&array->array[i], 0, 1);

    array->size = initialSize;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void resizeSemArray(SemArray* array, int newSize) {
    pthread_mutex_lock(&array->lock);
    if (newSize > array->size) { 
        // Resize the semaphore pool by allocating more memory.
        array->array = realloc(array->array, sizeof(sem_t)* newSize);

        for (int i = array->size; i < newSize; ++i) 
            sem_init(&array->array[i], 0, 1);
    } else if (newSize < array->size) {
        // Resize the semaphore pool by freeing unused memory.
        for (int i = newSize; i < array->size; ++i) 
            sem_destroy(&array->array[i]);
    }

    array->size = newSize;
    pthread_mutex_unlock(&array->lock);
}

void logSemaphoreOperation(sem_t* sem, const char* message) {
    // Use the external logging library to record the operation. 
    // You would need to add appropriate checks and error handling here.
    log_event(message);
}

void accessResource(SemArray* array, int index) {
    if (index >= array->size || index < 0) return;

    pthread_mutex_lock(&array->lock);

    sem_wait(&array->array[index]);
    logSemaphoreOperation(&array->array[index], "Accessed resource");

    sem_post(&array->array[index]);
    pthread_mutex_unlock(&array->lock);
}
