['```CSharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;

[Serializable]
public class RandomValueGenerator<T> where T : IComparable<T>
{
    private HashSet<T> history = new HashSet<T>();
    private Random rnd;
    private T min, max;
    private bool inclusive;

    public RandomValueGenerator(T min, T max, bool inclusive = true, int? seed = null) 
    {
        if (min.CompareTo(max) > 0) 
            throw new ArgumentException("Minimum value must be less than or equal to maximum value");

        this.inclusive = inclusive;
        this.rnd = seed == null ? new Random() : new Random((int)seed);
        this.min = min;
        this.max = max;
    }

    public T NextValue() 
    {
        var nextVal = GenerateRandomNumber();

        while (history.Contains(nextVal))
            nextVal = GenerateRandomNumber();

        history.Add(nextVal);
        return nextVal;
    }

    private T GenerateRandomNumber() 
    {
        dynamic minValue = Convert.ChangeType(min, typeof(double));
        dynamic maxValue = Convert.ChangeType(max, typeof(double));

        var randomDouble = rnd.NextDouble();
        return (T)Convert.ChangeType((randomDouble * (maxValue - minValue)) + minValue, typeof(T));
    }

    public IEnumerable<T> NextValues(int length) 
    {
        for (var i = 0; i < length; ++i)
            yield return NextValue();
    }

    private T GetRandomFromFile(string filePath) 
    {
        Stream stream = null;

        try 
        {
            IFormatter formatter = new BinaryFormatter();
            stream = new FileStream(filePath, FileMode.Open);

            var obj = (T)formatter.Deserialize(stream);
            if (obj is T)
                return (T)obj;
        } 
        catch (SerializationException e) 
        {
            Console.WriteLine("Failed to deserialize object from file: " + e.Message);
        } 
        finally 
        {
            if(stream != null) stream.Close();
        }

        return default(T);
    }

    public override string ToString() => 
        $"Current range: [{min}, {max}] | Seed used: {rnd.Next()} | Unique values generated so far: {history.Count}";
}
```
