['Here's a basic implementation in C that should satisfy your requirements. This code makes use of dynamic memory allocation using `malloc` for the array of transaction structs. Memory is freed using `free` after all transactions have been processed to avoid potential memory leaks. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TRANSACTIONS 1000
#define LINE_SIZE 500 // assuming max line size

typedef struct {
    int id;
    long timestamp;
    double amount;
    char status[9]; // "success" or "failure" plus null character
} Transaction;

Transaction* readTransactionsFromFile(const char *filename, int *transactionCount) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return NULL;
    }

    Transaction *transactions = malloc(MAX_TRANSACTIONS * sizeof(Transaction));
    char line[LINE_SIZE];
    *transactionCount = 0;

    while (fgets(line, LINE_SIZE, file)) {
        if (*transactionCount >= MAX_TRANSACTIONS) {
            printf("Warning: More than 1,000 transactions detected. Skipping remaining.\n");
            break;
        }

        Transaction *t = &transactions[*transactionCount];
        sscanf(line, "%d,%ld,%lf,%8s", &t->id, &t->timestamp, &t->amount, t->status);
        ++(*transactionCount);
    }

    fclose(file);
    return transactions;
}

double calculateTotalSuccessfulTransactionsAmount(Transaction *transactions, int transactionCount) {
    double total = 0.0;
    for (int i=0; i<transactionCount; ++i) {
        if (strcmp(transactions[i].status, "success") == 0) {
            total += transactions[i].amount;
        }
    }

    return total;
}

void freeTransactionMemory(Transaction *transactions) {
    free(transactions);
}

