#include "csv_parser.h" //Assuming this is the external library's header file.
using namespace std;

void processCSV(const string &filename, vector<string> &fields) {
    CSVParser parser(filename);
    map<vector<string>, bool> uniqueRecords;
    unsigned int numUniqueEmails = 0;

    for (unsigned int i = 0; i < parser.getNumLines(); ++i) {
        auto line = parser.readLine();

        if (!line) {
            continue; //skip empty lines
        }

        sort(line->begin(), line->end()); //sort all fields alphabetically

        vector<string> recordFields;
        for (const auto &field : fields) {
            string value = parser.getValue(*line, field);

            if (value.empty()) {
                continue; //skip empty fields
            }

            recordFields.push_back(move(value));
        }

        bool isUnique = uniqueRecords.emplace(move(recordFields), true).second;

        if (isUnique) {
            ++numUniqueEmails; //count unique emails
        }
    }

    cout << "Number of unique records: " << numUniqueEmails << endl;
}
```
