public void ModifyForwardList(string first, string second, List<string> forwardList)
{
    // Lock for thread safety
    lock (forwardList)
    {
        int index = forwardList.IndexOf(first);
        if (index != -1)
            forwardList.Insert(index + 1, second);
        else
            forwardList.Add(second);
    }
}
