                 const struct addrinfo *hints,
                 struct addrinfo **res);

void freeaddrinfo(struct addrinfo *ai);

char* generateUniqueCacheKeyWithDNSResolutionAndMD5Hash(char *url, FileInfo files[], int num_files) {
    char ip_address[INET6_ADDRSTRLEN];
    struct addrinfo hints, *res;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM; // TCP stream sockets

    char host[256];
    sprintf(host, "%.*s", strcspn(url, "/"), url);

    if (getaddrinfo(host, "http", &hints, &res) != 0) {
        perror("Error performing DNS resolution");
        return NULL; // Handle error gracefully
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    void *addr = &(ipv4->sin_addr);

    inet_ntop(res->ai_family, addr, ip_address, sizeof ip_address);
    freeaddrinfo(res); // Remember to free the memory allocated by getaddrinfo

    char *path = strstr(url, "/");
    if (path != NULL) path++;

    unsigned long total_len = 0;
    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(files[i].file_path, "rb");
        if (file == NULL) {
            perror("Error opening file");
            continue; // Handle error gracefully
        }

        MD5_CTX mdContext;
        unsigned char digest[MD5_DIGEST_LENGTH];

        int bytes;
        unsigned char data[1024];

        MD5_Init (&mdContext);
        while ((bytes = fread(data, 1, 1024, file)) != 0) {
            MD5_Update(&mdContext, data, bytes);
        }

        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_Final(digest, &mdContext);
        memcpy(files[i].md5_hash, digest, MD5_DIGEST_LENGTH);
    }

    size_t url_len = strlen(url);
    size_t host_len = strlen(ip_address);
    size_t path_len = (path == NULL) ? 0 : strlen(path);

    if (total_len > MD5_DIGEST_LENGTH + 128) {
        return NULL; // Handle error gracefully
    }

    char* cache_key = malloc(sizeof(char) * total_len + 1);

    sprintf(cache_key, "url=%s&ip=%s", url, ip_address);
    if (path != NULL) {
        strncat(cache_key, path, MD5_DIGEST_LENGTH - total_len);
    }

    for (int i = 0; i < num_files; i++) {
        char* file_name = basename(files[i].file_path);
        sprintf(cache_key, "%s&%s=", cache_key, file_name);

        for (int j = 0; j < MD5_DIGEST_LENGTH; j++) {
            sprintf(cache_key, "%s%02x", cache_key, files[i].md5_hash[j]);
        }
    }

    return cache_key;
}
