#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>
#include <unistd.h>

typedef struct node {
    char *key;
    time_t timestamp;
    struct node *prev;
    struct node *next;
} Node;

// LRU cache with linked list and hash table
Node *cacheHead = NULL, *cacheTail = NULL;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

#define MAX_CACHE_SIZE 1024*1024 // 1MB
size_t cacheSize = 0;
Node *cacheTable[MAX_FILES] = { NULL };

void moveToFront(char *key) {
    pthread_mutex_lock(&cacheMutex);
    Node *node = cacheTable[key];
    if (node == cacheHead) {
        // already at front, do nothing
    } else if (node == NULL) {
        // new node, add to front
        node = malloc(sizeof(Node));
        node->key = strdup(key);
        node->prev = NULL;
        node->next = cacheHead;
        cacheHead->prev = node;
        cacheHead = node;
    } else {
        // remove from current position
        if (node == cacheTail) {
            // last node, update tail
            cacheTail = node->prev;
            cacheTail->next = NULL;
        } else {
            node->next->prev = node->prev;
            node->prev->next = node->next;
        }
        // add to front
        node->prev = NULL;
        node->next = cacheHead;
        cacheHead->prev = node;
        cacheHead = node;
    }
    pthread_mutex_unlock(&cacheMutex);
}

void removeFromTail() {
    pthread_mutex_lock(&cacheMutex);
    if (cacheTail != NULL) {
        Node *node = cacheTail;
        cacheSize -= strlen(node->key) + 1; // including null terminator
        free(node->key);
        cacheTable[node->key] = NULL;
        if (cacheHead == node) {
            cacheHead = cacheTail = NULL; // list is empty now
        } else {
            cacheTail = node->prev;
            cacheTail->next = NULL;
        }
        free(node);
    }
    pthread_mutex_unlock(&cacheMutex);
}

void *getMD5Hash(char *filePath) {
    FILE *file = fopen(filePath, "rb");
    if (file == NULL) return NULL; // file not exists or permission denied

    MD5_CTX context;
    unsigned char digest[16];
    int bytes;
    unsigned char buffer[8192];

    MD5_Init(&context);
    while ((bytes = fread(buffer, 1, sizeof buffer, file)) != 0) {
        MD5_Update(&context, buffer, bytes);
    }
    MD5_Final(digest, &context);

    fclose(file);

    // convert digest to string
    char *md5String = malloc(MD5_DIGEST_LENGTH*2+1);
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&md5String[i*2], "%02x", (unsigned int)digest[i]);
    }
    return md5String;
}

void *resolveDNS(char *hostname, u_char *ipAddr) {
    struct hostent *he = gethostbyname(hostname);
    if (he == NULL) return NULL; // failed to resolve DNS

    memcpy(ipAddr, he->h_addr_list[0], he->h_length);
    return ipAddr;
}

char *generateUniqueCacheKeyWithDNSResolutionAndMD5Hash(char *urlString, char *filePaths[]) {
    // validate inputs
    if (strlen(urlString) > MAX_URL_LENGTH || strspn(urlString, ALLOWED_CHARS) != strlen(urlString)) return NULL;
    for (int i = 0; filePaths[i] != NULL; ++i) {
        if (strlen(filePaths[i]) > MAX_PATH || strspn(filePaths[i], ALLOWED_CHARS) != strlen(filePaths[i])) return NULL;
    }

    // parse URL
    struct url_fields {
        char hostname[256];
        char path[1024];
    };
    struct url_fields fields = {0};
    if (parseUrl(urlString, &fields) != 0) return NULL; // failed to parse URL

    // resolve DNS and get IP address
    u_char ipAddr[INET6_ADDRSTRLEN];
    if (resolveDNS(fields.hostname, ipAddr) == NULL) return NULL; // failed to resolve DNS

    // compute MD5 hash for each file path
    char *md5String = malloc(MD5_DIGEST_LENGTH*2+1);
    for (int i = 0; filePaths[i] != NULL; ++i) {
        if ((md5String = getMD5Hash(filePaths[i])) == NULL) return NULL; // failed to compute MD5 hash
    }

    // generate unique cache key
    char *cacheKey = malloc(MAX_CACHE_SIZE);
    sprintf(cacheKey, "%s%s", fields.hostname, md5String);

    while (strlen(cacheKey) > MAX_URL_LENGTH || cacheSize + strlen(md5String) + 1 > MAX_CACHE_SIZE) {
        removeFromTail(); // make room for new node if necessary
    }
    moveToFront(cacheKey); // add to front of LRU cache

    return cacheKey;
}
```
