#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <openssl/md5.h>
#include <time.h>
#include <ctype.h>
#include <unistd.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>
#include <stdlib.h>

#define MAX_CACHE_KEY_LEN 128
#define MAX_URL_PATHS 1024

typedef struct {
    pthread_mutex_t mutex;
    char* cacheKeys[MAX_URL_PATHS];
    time_t accessTimes[MAX_URL_PATHS];
} LRUCache;

LRUCache lruCache = {{PTHREAD_MUTEX_INITIALIZER}, {NULL}, {0}};

char* generateUniqueCacheKeyWithDNSResolutionAndMD5Hash(const char* url, const u_char* filePaths) {
    struct timespec startTime;
    clock_gettime(CLOCK_MONOTONIC, &startTime);

    size_t maxUrlLength = MAX_URL_PATHS * strlen("127.0.0.1"); // Approximate worst-case scenario 

    char* newUrl = malloc((maxUrlLength + 1) * sizeof(char));
    if (newUrl == NULL) {
        printf("Failed to allocate memory for URL.\n");
        return NULL;
    }
    strncpy(newUrl, url, maxUrlLength);

    struct hostent* hostInfo = gethostbyname(url); // Assuming 'url' is a valid host name. 

    if (hostInfo == NULL) {
        printf("Failed to resolve DNS: %s.\n", hstrerror(h_errno));
        free(newUrl);
        return NULL;
    }

    char* ip = inet_ntoa(*((struct in_addr*) hostInfo->h_addr_list[0])); 

    sprintf(newUrl, "%s", ip);

    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5(filePaths, strlen((char*) filePaths), md5Hash);

    for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&newUrl[strlen(newUrl)], "%02x", md5Hash[i]);
    }

    if (strlen(newUrl) > MAX_CACHE_KEY_LEN) {
        newUrl[MAX_CACHE_KEY_LEN] = '\0'; // Truncate to fit within maximum length 
    }

    struct timespec endTime;
    clock_gettime(CLOCK_MONOTONIC, &endTime);

    double elapsedTimeSecs = (endTime.tv_sec - startTime.tv_sec) + ((double)(endTime.tv_nsec - startTime.tv_nsec)) / 1e9;

    printf("Cache key generation took %lf seconds.\n", elapsedTimeSecs);

    // Insert into LRU cache if not already in it
    pthread_mutex_lock(&lruCache.mutex);
    for (size_t i = 0; i < MAX_URL_PATHS; ++i) {
        if (lruCache.cacheKeys[i] == NULL || strcmp(lruCache.cacheKeys[i], newUrl) == 0) {
            if (lruCache.cacheKeys[i] != NULL) free(lruCache.cacheKeys[i]);

            lruCache.cacheKeys[i] = malloc((strlen(newUrl) + 1) * sizeof(char));
            strcpy(lruCache.cacheKeys[i], newUrl);
            lruCache.accessTimes[i] = time(NULL); 

            break;
        } else if (difftime(time(NULL), lruCache.accessTimes[i]) > 30) { // Clean up stale cache keys 
            free(lruCache.cacheKeys[i]);
            lruCache.cacheKeys[i] = NULL;

        }
    }
    pthread_mutex_unlock(&lruCache.mutex);

    return newUrl;
}
```
