#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_TASKS 10000

typedef struct {
    int priority;
    char status;
    char description[256];
} Task;

typedef struct {
    Task tasks[MAX_TASKS];
    int count;
    pthread_mutex_t mutex;
} TaskCollection;

TaskCollection* create_task_collection() {
    TaskCollection* collection = malloc(sizeof(TaskCollection));
    if (!collection) return NULL;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_task_collection(TaskCollection* collection) {
    free(collection);
}

void add_task(TaskCollection* collection, int priority, char status, const char* description) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->count >= MAX_TASKS) {
        pthread_mutex_unlock(&collection->mutex);
        return;
    }
    Task* new_task = &collection->tasks[collection->count++];
    new_task->priority = priority;
    new_task->status = status;
    strncpy(new_task->description, description, sizeof(new_task->description) - 1);
    new_task->description[sizeof(new_task->description) - 1] = '\0';
    pthread_mutex_unlock(&collection->mutex);
}

Task* get_task_by_priority(TaskCollection* collection, int priority) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->count; ++i) {
        if (collection->tasks[i].priority == priority) {
            Task* result = &collection->tasks[i];
            pthread_mutex_unlock(&collection->mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
