int processDirectory(char* inputDirPath, char* fileNamePattern, char* outputDirPath, char* thirdPartyToolPath, char* params) {
    DIR *dir;
    struct dirent *ent;

    if ((dir = opendir (inputDirPath)) != NULL) {
        while ((ent = readdir (dir)) != NULL) {
            // Skip directories and files that don't match the specified pattern
            if(ent->d_type == DT_DIR || strncmp(ent->d_name, fileNamePattern, strlen(fileNamePattern))) continue;

