['Below is an implementation in C using OpenSSL library for AES-256-CBC encryption and PBKDF2 HMAC with SHA-256 as hashing algorithm.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>

struct CipherContext {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[32];
    unsigned int ivLength;
};

int initCipher(const char* password, const unsigned char* salt, size_t saltLen, 
               unsigned int iterations, struct CipherContext* cipher) {

    if (cipher == NULL || password == NULL || salt == NULL || 
        iterations < 1000 || saltLen == 0) return -1;

    // Derive the encryption key using PBKDF2 with SHA-256 as the hashing algorithm.
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, saltLen, iterations, EVP_sha256(), 32, cipher->key)) {
        return -1;
    }

    // Initialize the AES-256-CBC encryption context.
    cipher->ctx = EVP_CIPHER_CTX_new();
    if (cipher->ctx == NULL) return -1;

    return 0;
}

int encryptData(struct CipherContext* cipher, const unsigned char* plaintext, size_t textLen,
                unsigned char** ciphertext) {

    if (cipher == NULL || plaintext == NULL || cipher->ctx == NULL) return -1;

    // Generate a random IV. The length should be within the allowed range of 12 to 16 bytes.
    unsigned char iv[EVP_MAX_IV_LENGTH];
    if (!RAND_bytes(iv, cipher->ivLength)) return -1;

    // Initialize the encryption operation with our key and IV.
    if (EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, iv) != 1) return -1;

    // Apply padding for the plaintext.
    int len = 0;
    if (EVP_EncryptUpdate(cipher->ctx, *ciphertext, &len, plaintext, textLen) != 1) return -1;

    int ciphertextLength = len;

    // Finalize the encryption operation. 
    if (EVP_EncryptFinal_ex(cipher->ctx, *ciphertext + len, &len) != 1) return -1;

    ciphertextLength += len;

    // Disable the cipher and clean up after use.
    EVP_CIPHER_CTX_reset(cipher->ctx);

    return ciphertextLength;
}

void setIVLength(struct CipherContext* cipher, unsigned int ivLen) {
    if (ivLen >= 12 && ivLen <= 16) cipher->ivLength = ivLen;
}

void cleanupCipher(struct CipherContext* cipher) {
    EVP_CIPHER_CTX_free(cipher->ctx);
}
```
This code defines a `CipherContext` struct to hold the encryption context and derived key. 
The `initCipher` function initializes the AES-256-CBC cipher by using PBKDF2 HMAC with SHA-256 as hashing algorithm.
The `encryptData` function encrypts data using the initialized cipher and generates a random IV for each encryption operation. It then cleans up after use. 
Finally, the `cleanupCipher` function disables the cipher and frees memory allocated by OpenSSL.

Please note that this code does not handle deallocation of dynamically-allocated memory in all error scenarios. A production application should include proper checks and cleanup code wherever necessary. 

Also, please remember to use a strong password or salt value for the encryption as a weak one can easily lead to security issues. 

Additionally, it is not recommended to hardcode constants such as key size (32) and IV length (16). You should let users set them during runtime to ensure flexibility. However, in this case we are assuming a fixed key size of 32 bytes for simplicity. 

Lastly, the verification process for initialization is only performed by checking if the derived key has a length of 32 bytes and IV length within the allowed range (12-16). You should add more checks based on your requirements.
']

