    unsigned char md5[MD5_DIGEST_LENGTH];
    struct node *prev;
    struct node *next;
} Node;
Node* head = NULL, *tail = NULL;
sqlite3 *db;
pthread_mutex_t lock;
int cacheSize = 0;

// Function to insert a new node into the LRU cache
void insertIntoCache(char *url, unsigned char md5[MD5_DIGEST_LENGTH]) {
    Node* list = head;
    while(list) {
        if(!strcmp(list->url, url)) {
            return;
        }
        list = list->next;
    }
    if (cacheSize >= MAX_CACHE_KEY_LENGTH) {
        Node* temp = tail;
        tail = tail->prev;
        tail->next = NULL;
        free(temp);
    } else {
        cacheSize++;
    }
    Node* newNode = malloc(sizeof(Node));
    newNode->url = url;
    memcpy(newNode->md5, md5, MD5_DIGEST_LENGTH);
    newNode->next = head;
    newNode->prev = NULL;
    if (head != NULL) {
        head->prev = newNode;
    }
    head = newNode;
}

// Function to fetch a node from the LRU cache
unsigned char* fetchFromCache(char *url) {
    Node* list = head;
    while(list) {
        if(!strcmp(list->url, url)) {
            unsigned char* md5 = malloc(MD5_DIGEST_LENGTH);
            memcpy(md5, list->md5, MD5_DIGEST_LENGTH);
            return md5;
        }
        list = list->next;
    }
    return NULL;
}

void generateUniqueCacheKeyWithAdvancedFeatures(char *url, char **filePaths) {
    pthread_mutex_lock(&lock);
    unsigned char* md5 = fetchFromCache(url);

    if(!md5) {
        // If the URL is not in cache, we need to compute its MD5 hash and add it to the cache
        CURL *curl;
        CURLcode res;

        curl = curl_easy_init();
        if(curl) {
            char* hostname = strtok(url, "/");

            curl_easy_setopt(curl, CURLOPT_URL, hostname);
            // Set DNS options for asynchronous name resolution
            curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
            curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, 1000L);

            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "DNS resolution failed: %s\n", curl_easy_strerror(res));
                return;
            }

            MD5_CTX context;
            unsigned char digest[MD5_DIGEST_LENGTH];
            int i = 0;
            while (filePaths[i]) {
                // Here goes the code to check if a file path is valid and accessible 
                FILE *f = fopen(filePaths[i], "r");
                if (!f) {
                    printf("Error opening file %s\n", filePaths[i]);
                    continue;
                } else {
                    fclose(f);
                }

                MD5_Init(&context);
                // Here goes the code to update the hash with the content of each file 
                i++;
            }

            MD5_Final(digest, &context);

            curl_easy_cleanup(curl);
            md5 = malloc(MD5_DIGEST_LENGTH);
            memcpy(md5, digest, MD5_DIGEST_LENGTH);
            insertIntoCache(url, md5);
        }
    }

    pthread_mutex_unlock(&lock);
}
```
