['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

typedef struct MacEntity {
    int id;
} MacEntity;

typedef struct PdcpStatistic {
    int count;
} PdcpStatistic;

typedef struct UEContext {
    int UE_ID;
    pthread_mutex_t mutex;
    MacEntity* macEntities;
    size_t entityCount;
    PdcpStatistic pdcpStatistics;
    bool suspended;
} UEContext;

typedef struct ContextManager {
    UEContext** ueContexts;
    size_t contextCount;
    int updateFrequency;
    FILE* logFile;
    pthread_mutex_t mutex;
} ContextManager;

void addUE(ContextManager *manager, int id) {
    if (!pthread_mutex_lock(&manager->mutex)) {
        UEContext* newContext = (UEContext*) malloc(sizeof(UEContext));
        newContext->UE_ID = id;
        newContext->entityCount = 0;
        newContext->suspended = false;
        ++manager->contextCount;
        manager->ueContexts = (UEContext**) realloc(manager->ueContexts, sizeof(UEContext*) * manager->contextCount);
        manager->ueContexts[manager->contextCount - 1] = newContext;
        pthread_mutex_init(&newContext->mutex, NULL);
        fprintf(manager->logFile, "Added UE with ID: %d\n", id);
    }
    else {
        perror("Failed to add UE");
    }
}

void removeUE(ContextManager *manager, int id) {
    if (!pthread_mutex_lock(&manager->mutex)) {
        for (size_t i = 0; i < manager->contextCount; ++i) {
            if (manager->ueContexts[i]->UE_ID == id) {
                free(manager->ueContexts[i]);
                memmove(&manager->ueContexts[i], &manager->ueContexts[i + 1], sizeof(UEContext*) * (manager->contextCount - i));
                --manager->contextCount;
                fprintf(manager->logFile, "Removed UE with ID: %d\n", id);
            }
        }
    }
    else {
        perror("Failed to remove UE");
    }
}

void updateStatistics(ContextManager *manager) {
    for (size_t i = 0; i < manager->contextCount; ++i) {
        if (!pthread_mutex_trylock(&manager->ueContexts[i]->mutex)) {
            if (!manager->ueContexts[i]->suspended && (sleep(manager->updateFrequency), 0) == 0) {
                manager->ueContexts[i]->pdcpStatistics.count++;
                fprintf(manager->logFile, "Updated statistics for UE with ID: %d\n", manager->ueContexts[i]->UE_ID);
            }
        }
    }
}

void suspendUE(ContextManager *manager, int id) {
    for (size_t i = 0; i < manager->contextCount; ++i) {
        if (!pthread_mutex_trylock(&manager->ueContexts[i]->mutex)) {
            if (manager->ueContexts[i]->UE_ID == id) {
                manager->ueContexts[i]->suspended = true;
                fprintf(manager->logFile, "Suspended UE with ID: %d\n", id);
            }
        }
    }
}

void cleanupManager(ContextManager *manager) {
    for (size_t i = 0; i < manager->contextCount; ++i) {
        free(manager->ueContexts[i]);
    }
    fclose(manager->logFile);
}
```
