// Helper function to calculate a unique identifier from filename content
char* getUniqueIdentifier(const char* filename, unsigned int length) {
    // Create SHA-256 hash of the filename
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)filename, strlen(filename), hash);

    // Convert each byte of the hash into two hexadecimal characters
    char* identifier = (char*)calloc(length * 2 + 1, sizeof(char));
    for (int i = 0; i < length; ++i) {
        sprintf(&identifier[i * 2], "%02x", hash[i % SHA256_DIGEST_LENGTH]);
    }

    return identifier;
}

// Main function to modify filename and append a unique identifier
char* addUniqueIdentifier(const char* filename, size_t maxLength) {
    // Validate input
    if (!filename || strlen(filename) >= maxLength) {
        return NULL;  // Return NULL on error (e.g., invalid filename)
    }

    const char* dot = strrchr(filename, '.');
    if (!dot || dot == filename) {
        return NULL;  // Return NULL when no file extension or invalid extension
    }

    // Get the length of the identifier and check that it doesn't exceed maxLength
    size_t extLength = strlen(dot + 1);
    size_t idLength = (extLength <= SHA256_DIGEST_LENGTH * 2) ? extLength : SHA256_DIGEST_LENGTH * 2;
    if ((strlen(filename) + idLength + 1) > maxLength) {
        return NULL;  // Return NULL when the new filename exceeds maxLength
    }

    // Allocate memory for the new filename
    char* newFilename = (char*)malloc((strlen(filename) + idLength + 2) * sizeof(char));
    if (!newFilename) {
        return NULL;  // Return NULL on allocation failure
    }

    // Copy the original filename and append the identifier
    strcpy(newFilename, filename);
    strcat(newFilename, getUniqueIdentifier(filename, g_counter++));

    return newFilename;
}
