int generateMD5Hash(const char* filename, Record* record) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) return -1;

    unsigned char c[MD5_LEN];
    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    MD5_Init(&mdContext);
    while ((bytes = fread(data, 1, 1024, file)) != 0)
        MD5_Update(&mdContext, data, bytes);
    MD5_Final(c, &mdContext);

    record->buffer = malloc(strlen(filename));
    strcpy(record->buffer, filename);
    record->hashLen = MD5_DIGEST_LENGTH * 2; // Each byte represented as two hex digits

    fclose(file);
    return 0;
}

void manageFilePaths(const char* filename) {
    srand((unsigned int)time(NULL));

    Record records[MAX_RECORDS];
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        generateMD5Hash(filename, &records[i]);
    }

    sortAndIterate(records, MAX_RECORDS, compareRecords);
