        sscanf(line, "%s", newExt);

        if (strlen(newExt) < 3 || strcmp(filename + strlen(filename) - strlen(newExt), newExt) == 0) continue;
        else break;
    }

    fclose(file);

    char* dot = strrchr(filename, '.');
    if (dot != NULL && dot != filename) *dot = '\0';
    else {
        printf("Error: Filename does not have an extension or is too long.\n");
        return;
    }

    int digits = 0, length = strlen(filename);
    while (length > 0) {
        length /= 10;
        ++digits;
    }

    char newFilename[256];
    sprintf(newFilename, "%s%.*s.%s", filename, digits, dot + 1, newExt);

    if (rename(filename, newFilename) != 0) printf("Error renaming file.\n");
}
