#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define MAX_RETRY 5
#define BACKOFF_FACTOR 2

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} aes256gcm_context;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

aes256gcm_context *create_context(char* password, unsigned char* salt) {
    /* Generate key and iv using PBKDF2 */
    aes256gcm_context *ctx = malloc(sizeof(aes256gcm_context));
    if (!EVP_BytesToKey(EVP_aes_256_gcm(), EVP_sha256(), salt, password, strlen(password), 1, ctx->key, ctx->iv)) {
        free(ctx);
        return NULL;
    }
    /* Initialize cipher */
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv)) {
        free(ctx);
        return NULL;
    }
    return ctx;
}

int encrypt(aes256gcm_context *ctx, unsigned char* in, int len, unsigned char** out) {
    pthread_mutex_lock(&lock);

    EVP_EncryptUpdate(ctx->ctx, *out, &len, in, strlen((char*)in));
    /* ... */
    pthread_mutex_unlock(&lock);
}

int decrypt(aes256gcm_context *ctx, unsigned char* in, int len, unsigned char** out) {
    pthread_mutex_lock(&lock);

    EVP_DecryptUpdate(ctx->ctx, *out, &len, in, strlen((char*)in));
    /* ... */
    pthread_mutex_unlock(&lock);
}

int with_retry(void* (*fn)(aes256gcm_context*, unsigned char*, int, unsigned char**), 
               aes256gcm_context *ctx, unsigned char* in, int len, unsigned char** out) {
    for (int i = 0; i < MAX_RETRY; i++) {
        if (fn(ctx, in, len, out)) return 0;
        struct timespec ts = {.tv_sec = 1 << i * BACKOFF_FACTOR};
        nanosleep(&ts, NULL);
    }
    return -1;
}
```

