using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Text;

[Serializable]
public class CustomDataProcessor<TKey, TValue> where TKey : IComparable
{
    private Dictionary<TKey, TValue> _dataEntries;
    private Dictionary<Type, int> _typeDistribution;
    private List<string> _history;

    public CustomDataProcessor()
    {
        _dataEntries = new Dictionary<TKey, TValue>();
        _typeDistribution = new Dictionary<Type, int>();
        _history = new List<string>();
    }

    public void Add(TKey key, TValue value)
    {
        if (_dataEntries.ContainsKey(key))
            throw new ArgumentException("Duplicate key not allowed.");

        _typeDistribution[value.GetType()] = _typeDistribution.GetValueOrDefault(value.GetType(), 0) + 1;
        _history.Add($"Added: {key}, {value}");
    }

    public void Update(TKey key, TValue value)
    {
        if (!_dataEntries.ContainsKey(key))
            throw new ArgumentException("Invalid key.");

        _typeDistribution[value.GetType()] = _typeDistribution.GetValueOrDefault(value.GetType(), 0) + 1;
        _history.Add($"Updated: {key}, {value}");
    }

    public TValue Get(TKey key)
    {
        if (!_dataEntries.ContainsKey(key))
            throw new ArgumentException("Invalid key.");

        return _dataEntries[key];
    }

    public void ExportToCsv(string filePath, string headers, string delimiter)
    {
        using (StreamWriter writer = new StreamWriter(filePath))
        {
            writer.WriteLine(headers);

            foreach (var entry in _dataEntries)
                writer.WriteLine($"{entry.Key}{delimiter}{entry.Value}");
        }
    }

    public void SerializeToFile(string filePath)
    {
        BinaryFormatter formatter = new BinaryFormatter();

        using (Stream stream = File.Create(filePath))
            formatter.Serialize(stream, this);
    }

    public static CustomDataProcessor<TKey, TValue> DeserializeFromFile(string filePath)
    {
        BinaryFormatter formatter = new BinaryFormatter();

        using (Stream stream = File.OpenRead(filePath))
            return (CustomDataProcessor<TKey, TValue>)formatter.Deserialize(stream);
    }

    public override string ToString()
    {
        StringBuilder summary = new StringBuilder();

        summary.AppendLine($"Number of entries: {_dataEntries.Count}");
        summary.AppendLine($"Distribution: ");

        foreach (var type in _typeDistribution)
            summary.AppendLine($"\t{type.Key}: {type.Value}");

        return summary.ToString();
    }
}
```
