// Assuming we have a logging function already 
extern void log_message(const char* msg);

void modifyExtensionWithTimestamp(char* filename) {
    if (!filename || strlen(filename) == 0) {
        log_message("Error: Invalid filename");
        return;
    }

    // Get current timestamp
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timeString[20];
    strftime(timeString, sizeof(timeString), "%Y%m%d%H%M%S", timeinfo);

    // Extract directory path and base name
    char* dirPath = strdup(filename);
    char* baseName = basename(dirPath);

    if (strlen(baseName) == 0) {
        log_message("Error: Invalid filename");
        free(dirPath);
        return;
    }

    // Get the length of the base name without extension
    char* dot = strrchr(baseName, '.');
    size_t extLen = (dot) ? strlen(dot+1) : 0;
    size_t baseLen = (dot) ? dot - baseName : strlen(baseName);

    // Calculate new filename length and validate
    int maxLength = 255 - extLen - sizeof(timeString);
    if (baseLen > maxLength || baseLen + extLen + sizeof(timeString) > 255) {
        log_message("Error: Filename too long");
        free(dirPath);
        return;
    }

    // Construct new filename
    char* newFilename = malloc(sizeof(char) * (baseLen + extLen + sizeof(timeString) + 2)); // Plus 2 for the dot and null terminator
    strncpy(newFilename, baseName, baseLen);
    sprintf(&newFilename[baseLen], ".%s.%s", timeString, (dot) ? dot+1 : "");

    // Log success and free memory
    log_message("Success: Filename modified to %s", newFilename);
    strcpy(filename, dirPath);
    strcat(filename, "/");
    strcat(filename, newFilename);
    free(dirPath);
    free(newFilename);
}
```
