struct Response {
    int status;
    char filename[1024]; // Assuming max length for filename is 1024
};

// Function to mimic a web API call
struct Response modify_filename(char* original, int identifier) {
    struct Response response;

    char extension[50];
    sprintf(extension, "%d", (int)(strlen(original) + identifier)); // Extract filename length and unique identifier

    char newFilename[1024] = ""; 
    strcat(newFilename, original);
    strcat(newFilename, ".");
    strcat(newFilename, extension);

    if (strlen(original) > 0 && identifier >= 0) { // If filename and unique identifier are valid
        response.status = 200;  // Success status code
        strcpy(response.filename, newFilename); 
    } else {
        response.status = 400;  // Failure status code
        strcpy(response.filename, "");  
    }

    return response;
}

// Function to handle deletion operations
struct Response delete_file(char* original, int identifier) {
    struct Response response;

    char defaultExt[50];
    sprintf(defaultExt, "%d", (int)(strlen(original) + identifier)); // Generate a default extension based on sum of lengths

    char newFilename[1024] = ""; 
    strcat(newFilename, original);
    strcat(newFilename, "_deleted"); // Append _deleted to mark as deleted
    strcat(newFilename, ".");
    strcat(newFilename, defaultExt);

    if (strlen(original) > 0 && identifier >= 0) { 
        response.status = 200;  
        strcpy(response.filename, newFilename); 
    } else {
        response.status = 400; 
        strcpy(response.filename, "");  
    }

    return response;
}
