#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <time.h>

struct Config {
    char extensions[10][5]; // assuming a max of 10 supported extensions and each can be up to 4 characters
};

void loadConfig(const char *path, struct Config *config) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        printf("Could not open config file\n");
        return;
    }

    int i = 0;
    while (!feof(file)) {
        if (fscanf(file, "%s", config->extensions[i]) != 1) break;
        ++i;
    }

    fclose(file);
}

int renameFilesInDir(const char *dirPath, const struct Config *config) {
    DIR *dir = opendir(dirPath);
    if (dir == NULL) {
        printf("Could not open directory\n");
        return 1;
    }

    int seqNumber = 0;
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", localtime(&now));

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char oldPath[4096], newName[1024];
        sprintf(oldPath, "%s/%s", dirPath, entry->d_name);

        char *word = strtok(entry->d_name, ".");
        if (word == NULL) {
            printf("Could not find word in filename: %s\n", entry->d_name);
            continue;
        }
        sprintf(newName, "%s%s%03d.", word, timestamp, seqNumber++);

        char *extension = strrchr(entry->d_name, '.');
        if (extension == NULL) {
            printf("Could not find extension in filename: %s\n", entry->d_name);
            continue;
        }
        ++extension; // Skip the '.' character

        int i = 0;
        for (; i < 10 && strcmp(extension, config->extensions[i]) != 0; ++i);
        if (i == 10) {
            printf("Unsupported extension: %s\n", extension);
            continue;
        }

        strcat(newName, config->extensions[i]);

        int suffix = 0;
        while (access(newName, F_OK) != -1) {
            ++suffix;
            sprintf(newName, "%s%s%03d.%s", word, timestamp, seqNumber + suffix, config->extensions[i]);
        }

        if (rename(oldPath, newName) != 0) {
            printf("Could not rename file: %s\n", entry->d_name);
        } else {
            printf("Renamed '%s' to '%s'\n", oldPath, newName);
        }
    }

    closedir(dir);
    return 0;
}
```
