void modifyFilenameWithTimestamp(char* filename) {
    // Get current time and format it as YYYYMMDDHHMMSS
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[15];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm_now);

    // Get the directory path from filename
    char dirPath[256] = "";
    struct stat st;
    if (stat(filename, &st) == 0 && S_ISDIR(st.st_mode)) {
        strncpy(dirPath, filename, sizeof(dirPath)-1);
    } else {
        char* lastSlash = strrchr(filename, '/');
        if (lastSlash != NULL) {
            strncpy(dirPath, filename, lastSlash - filename);
        }
    }

    // Get the base name and extension of the original filename
    char* ext = strrchr(filename, '.');
    if (ext == NULL) {
        printf("Invalid filename. No extension found\n");
        return;
    }
    size_t extLen = strlen(ext);

    // Dynamically determine the number of digits for the base name
    size_t baseNameMaxLen = 255 - extLen - strlen(timestamp) - 1; // Minus 1 for dot separator
    if (strlen(filename) > baseNameMaxLen + extLen + 1) { // Plus 1 for null-termination character
        printf("Invalid filename. Length exceeds maximum limit\n");
        return;
    }

    // Construct the new filename using snprintf
    char newFilename[256];
    snprintf(newFilename, sizeof(newFilename), "%s/%.*s_%s%s", dirPath, baseNameMaxLen, filename, timestamp, ext);

    printf("Modified filename: %s\n", newFilename);
}
