struct NFV {
    int id;
    std::vector<std::string> vnfs;
    std::map<std::string, double> metrics;
};

class NFVManager {
public:
    void addNFV(int id) {
        std::unique_lock lock(mtx); // Ensure exclusive access.
        if (instances.find(id) != instances.end()) {
            throw std::runtime_error("Instance already exists.");
        } else {
            instances[id] = NFV{id, {}, {}};
        }
    }

    void addVNF(int id, const std::string& vnf) {
        std::unique_lock lock(mtx); // Ensure exclusive access.
        auto it = instances.find(id);
        if (it != instances.end()) {
            it->second.vnfs.push_back(vnf);
        } else {
            throw std::runtime_error("Instance not found.");
        }
    }

    void updateMetric(int id, const std::string& metricName, double value) {
        std::unique_lock lock(mtx); // Ensure exclusive access.
        auto it = instances.find(id);
        if (it != instances.end()) {
            it->second.metrics[metricName] = value;
        } else {
            throw std::runtime_error("Instance not found.");
        }
    }

private:
    std::map<int, NFV> instances;
    std::shared_mutex mtx; // For concurrency safety.
};
