            return false;
        }
        if (!preg_match('/[A-Za-z].*[0-9]|[0-9].*[A-Za-z]/', $password)) {
            return false;
        }
        return true;
    }

    public function updateUserPassword($userId, $newPassword) {
        // Check password complexity.
        if (!$this->checkPasswordComplexity($newPassword)) {
            $this->logger->log('Invalid password complexity for user ' . $userId);
            throw new Exception('Invalid password complexity');
        }

        // Update the password in database.
        $hashedNewPassword = password_hash($newPassword, PASSWORD_DEFAULT);
        $this->dao->updateUserPassword($userId, $hashedNewPassword);

        $this->logger->log('Successfully updated password for user ' . $userId);
    }
}
