['```c
#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <ftw.h>

FILE *log_file;
char *source_dir, *destination_dir, *filter_pattern;
int return_val = 0;

static int copy_files(const char *fpath, const struct stat *sb, int typeflag) {
    if (typeflag != FTW_F) return 0;

    char source[256];
    sprintf(source, "%s/%s", fpath, sb->st_name);

    if (strstr(source, filter_pattern) == NULL) return 0;

    char destination[256];
    sprintf(destination, "%s/%s", source_dir, strstr(source, source_dir));

    FILE *src = fopen(source, "r");
    if (src == NULL) {
        fprintf(log_file, "Failed to open %s for reading: %s\n", source, strerror(errno));
        return_val = 1;
        return 0;
    }

    FILE *dst = fopen(destination, "w");
    if (dst == NULL) {
        fclose(src);
        fprintf(log_file, "Failed to open %s for writing: %s\n", destination, strerror(errno));
        return_val = 1;
        return 0;
    }

    char buffer[4096];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), src)) > 0) {
        if (fwrite(buffer, 1, bytes_read, dst) != bytes_read) {
            fprintf(log_file, "Failed to write to %s: %s\n", destination, strerror(errno));
            return_val = 1;
            break;
        }
    }

    fclose(src);
    fclose(dst);
    return 0;
}

int copy_directory(char *source, char *destination, char *filter) {
    source_dir = source;
    destination_dir = destination;
    filter_pattern = filter;

    log_file = fopen("log.txt", "w");
    if (log_file == NULL) return 1;

    nftw(source, copy_files, 20, FTW_PHYS);
    fclose(log_file);
    return return_val;
}
```
