#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <uv.h>

typedef struct {
    uv_fs_t req;
    uv_buf_t buf;
    char path[1024];
} write_req_t;

void on_read(uv_fs_t* read_req) {
    if (read_req->result < 0) {
        fprintf(stderr, "Read error: %s\n", uv_strerror((int)read_req->result));
        return;
    }

    write_req_t* req = malloc(sizeof(write_req_t));
    req->buf = uv_buf_init(read_req->data, read_req->result);

    sprintf(req->path, "%s/%s", dst_dir, uv_fs_get_path(read_req));

    int fd = open(req->path, O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        fprintf(stderr, "Open error: %s\n", uv_strerror((int)uv_fs_get_result(&req->req)));
        return;
    }

    uv_fs_write(loop, &req->req, fd, &req->buf, 1, -1, on_write);
}

void on_write(uv_fs_t* write_req) {
    if (write_req->result < 0) {
        fprintf(stderr, "Write error: %s\n", uv_strerror((int)write_req->result));
    } else {
        printf("File copied successfully.\n");
    }
}

void copy_file(const char* src, const char* dst) {
    size_t suggested_size = strlen(src);
    uv_buf_t buf = uv_buf_init((char*) malloc(suggested_size), suggested_size);
    memcpy(buf.base, src, suggested_size);

    uv_fs_open(loop, &read_req, buf.base, O_RDONLY, 0, on_read);
}

int main() {
    loop = uv_default_loop();

    const char* src = "/path/to/source";
    const char* dst = "/path/to/destination";

    copy_file(src, dst);

    return uv_run(loop, UV_RUN_DEFAULT);
}
```
