#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <errno.h>

typedef struct {
    int handle_symlinks;
    int overwrite;
    int log_level;
    void (*progress_update)(int); // callback function for progress updates
} Config;

void copyFile(char *sourcePath, char *destinationPath, const Config* config) {
    FILE *src = fopen(sourcePath, "rb");
    if (src == NULL) return;

    FILE *dst = fopen(destinationPath, "wb");
    if (dst == NULL) {
        fclose(src);
        return;
    }

    // Copy the file in chunks to avoid memory issues.
    const size_t bufferSize = 1024 * 1024; // 1MB buffer
    char buffer[bufferSize];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, bufferSize, src)) > 0) {
        if (fwrite(buffer, bytesRead, 1, dst) != 1) {
            break; // Error handling.
        }
        config->progress_update((int)(ftell(src) * 100 / fileSize));
    }

    fclose(dst);
    fclose(src);
}

void copyDirectoryRecursively(char *source, char *destination, const Config* config) {
    DIR *dir = opendir(source);
    if (dir == NULL) return; // Error handling.

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue; // Skip self and parent links.

        char sourcePath[1024];
        sprintf(sourcePath, "%s/%s", source, entry->d_name);

        char destinationPath[1024];
        sprintf(destinationPath, "%s/%s", destination, entry->d_name);

        struct stat st;
        if (stat(sourcePath, &st) == 0) {
            if (S_ISREG(st.st_mode)) { // Check if it's a regular file.
                copyFile(sourcePath, destinationPath, config);
            } else if (S_ISDIR(st.st_mode)) { // It's a directory.
                mkdir(destinationPath, 0755); // Create the directory in the destinatio path.
                copyDirectoryRecursively(sourcePath, destinationPath, config); // Recurse into it.
            }
        } else { // Error handling.
        }
    }

    closedir(dir);
}

int copyDirToDirWithFilter(char *src_directory, char *dst_directory, const Config* config) {
    DIR *dir = opendir(src_directory);
    if (dir == NULL) return 1; // Error handling.

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        copyDirectoryRecursively(src_directory, dst_directory, config);
    }

    closedir(dir);
    return 0;
}
```
Please note that C is not the best language to do this in because of its low-level nature. High level languages like Python or Java would be more suitable for such tasks due to their built-in support for file I/O, error handling and concurrency primitives. Also, they have more comprehensive libraries to handle these issues.
