int copy_files(const char* source, const char* destination, const char* filter, Config config) {
    DIR *dir = opendir(source);
    if (dir == NULL) {
        fprintf(config.log_file, "Failed to open directory %s: %s\n", source, strerror(errno));
        return 1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char source_path[4096];
        snprintf(source_path, sizeof(source_path), "%s/%s", source, entry->d_name);

        struct stat st;
        if (stat(source_path, &st) < 0 || !S_ISREG(st.st_mode)) continue;

        char *match = strstr(entry->d_name, filter);
        if (match == NULL) continue;

        FILE *source_file = fopen(source_path, "rb");
        if (source_file == NULL) {
            fprintf(config.log_file, "Failed to open file %s: %s\n", source_path, strerror(errno));
            continue;
        }

        char destination_path[4096];
        snprintf(destination_path, sizeof(destination_path), "%s/%s", destination, entry->d_name);

        FILE *destination_file = fopen(destination_path, "wb");
        if (destination_file == NULL) {
            fprintf(config.log_file, "Failed to create file %s: %s\n", destination_path, strerror(errno));
            continue;
        }

        char buffer[4096];
        size_t bytes_read = 0;
        while ((bytes_read = fread(buffer, 1, sizeof(buffer), source_file)) > 0) {
            if (fwrite(buffer, 1, bytes_read, destination_file) != bytes_read) {
                fprintf(config.log_file, "Failed to write to file %s: %s\n", destination_path, strerror(errno));
                break;
            }
        }

        fclose(source_file);
        fclose(destination_file);
    }

    closedir(dir);
    return 0;
}
```

