    private final Lock fileLock = new ReentrantLock();
    private MessageDigest digest;

    public FileProcessor() throws NoSuchAlgorithmException {
        this.digest = MessageDigest.getInstance("SHA-256");
    }

    public void processFile(Path filePath, Path metadataPath) throws IOException {
        if (isValidChecksum(filePath, metadataPath)) {
            try {
                // Acquire the lock before processing the file.
                fileLock.lock();

                Reader in = new FileReader(filePath.toFile());
                Iterable<CSVRecord> records = CSVFormat.DEFAULT.parse(in);

                for (CSVRecord record : records) {
                    // Extract relevant metrics from each log entry and write to the database.

                }
            } finally {
                fileLock.unlock();
            }
        } else {
            System.out.println("File integrity check failed, skipping...");
        }
    }

    private boolean isValidChecksum(Path filePath, Path metadataPath) throws IOException {
        byte[] fileContent = Files.readAllBytes(filePath);
        byte[] hashedContent = digest.digest(fileContent);

        String storedChecksum = new String(Files.readAllBytes(metadataPath));
        String currentChecksum = new String(hashedContent);

        return storedChecksum.equals(currentChecksum);
    }
}
