#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
} AES_256_GCM_session;

AES_256_GCM_session* init_encrypt(unsigned char *passphrase, unsigned char *salt) {
    // initialize cipher context and set key using KDF
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // perform the key derivation function to generate a secret key from the passphrase and salt

    unsigned char derived_key[32];  // AES-256 requires a 256 bit key (32 bytes)
    EVP_KDF(passphrase, strlen((char*)passphrase), salt, sizeof(salt), derived_key, sizeof(derived_key));

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, derived_key, NULL)) {
        // handle error here
    }

    AES_256_GCM_session *session = malloc(sizeof(AES_256_GCM_session));
    session->ctx = ctx;

    return session;
}

int encrypt(AES_256_GCM_session* session, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    // generate random nonce and set it in the cipher context
    unsigned char nonce[12];  // AES-GCM requires a 96 bit nonce (12 bytes)
    RAND_bytes(nonce, sizeof(nonce));

    if (!EVP_EncryptInit_ex(session->ctx, NULL, NULL, NULL, nonce)) {
        // handle error here
    }

    int ciphertext_len = 0;

    // encrypt the plaintext
    if(!EVP_EncryptUpdate(session->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) {
        // handle error here
    }

    unsigned char tag[16];  // AES-GCM uses a 128 bit tag (16 bytes)
    if(!EVP_EncryptFinal_ex(session->ctx, ciphertext + ciphertext_len, &ciphertext_len)) {
        // handle error here
    }

    if(!EVP_CIPHER_CTX_ctrl(session->ctx, EVP_CTRL_GCM_GET_TAG, 16, tag)) {
        // handle error here
    }

    return ciphertext_len + 12 + 16;  // add the nonce and tag to the total length of the ciphertext
}
```
