```C#
using System;

public class CustomRandomGenerator 
{
    private float minValue;
    private float maxValue;

    public CustomRandomGenerator(float min, float max)
    {
        SetRange(min, max);
    }

    public void SetRange(float min, float max)
    {
        if (min <= max)
        {
            this.minValue = min;
            this.maxValue = max;
        }
        else
        {
            this.minValue = max;
            this.maxValue = min;
        }
    }

    public float GenerateFloatInclusive() 
    {
        Random rnd = new Random();
        return (float)rnd.NextDouble() * (this.maxValue - this.minValue) + this.minValue;
    }

    public float GenerateFloatExclusive() 
    {
        Random rnd = new Random();
        return (float)(rnd.NextDouble() * (this.maxValue - this.minValue)) + this.minValue;
    }

    public int GenerateIntegerInRange() 
    {
        if (!IsValid())
            throw new InvalidOperationException("Invalid range, cannot generate integer.");

        Random rnd = new Random();
        return rnd.Next((int)this.minValue, (int)this.maxValue + 1);
    }

    public float CalculateMidpoint(out bool isValid) 
    {
        float midPoint = this.minValue + ((this.maxValue - this.minValue) / 2);

        isValid = IsValid();

        return midPoint;
    }

    public override string ToString() 
    {
        CalculateMidpoint(out bool isRangeValid);

        return $"Current range: [{this.minValue}, {this.maxValue}]. Midpoint: {CalculateMidpoint(out _)}. " + 
               $"Is valid?: {isRangeValid}";
    }

    private bool IsValid() 
    {
        return this.minValue < this.maxValue;
    }
}
```
