['Here's how you can implement this function using zlib for compression and openssl for encryption.

```c
#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>
#include <zlib.h>

char* compressAndEncryptLogData(const char* logEntry) {
    const int maxSize = 1024;
    const int aesBlockSize = 32; // AES-256 block size is 32 bytes
    const unsigned char key[aesBlockSize] = "yourkeyhere"; // Replace with your actual key
    const unsigned char iv[aesBlockSize] = "yourivhere"; // Replace with your actual IV

    int originalSize = strlen(logEntry);
    int compressedMaxSize = maxSize - aesBlockSize; // Leave space for IV

    // Truncate log entry if it exceeds the limit
    char* truncatedLogEntry = (char*)malloc(compressedMaxSize + 1);
    strncpy(truncatedLogEntry, logEntry, compressedMaxSize);
    truncatedLogEntry[compressedMaxSize] = '\0';

    // Compress the data
    unsigned char* compressedData = (unsigned char*)malloc(compressedMaxSize + 12);
    uLongf compressedLength = compressBound(compressedMaxSize) + 1;
    int compressionResult = compress(compressedData, &compressedLength, (Bytef*)truncatedLogEntry, strlen(truncatedLogEntry));

    if (compressionResult != Z_OK) {
        printf("Error during compression: %d\n", compressionResult);
        return NULL;
    }

    // Encrypt the compressed data
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    int encryptedLength = 0;
    unsigned char* encryptedData = (unsigned char*)malloc(compressedLength + aesBlockSize);

    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, encryptedData, &encryptedLength, compressedData, compressedLength);

    int finalLength = 0;
    EVP_EncryptFinal_ex(ctx, encryptedData + encryptedLength, &finalLength);

    EVP_CIPHER_CTX_free(ctx);

    // Metadata string
    char metadata[128];
    sprintf(metadata, "Original size: %d, Compression ratio: %.2f", originalSize, (float)compressedLength / compressedMaxSize);
    printf("%s\n", metadata);

    // Return encrypted data and its length
    char* result = (char*)malloc(encryptedLength + aesBlockSize + 1);
    memcpy(result, encryptedData, encryptedLength + aesBlockSize);
    result[encryptedLength + aesBlockSize] = '\0';

    // Free memory
    free(truncatedLogEntry);
    free(compressedData);
    free(encryptedData);

    return result;
}
```
Please replace `"yourkeyhere"` and `"yourivhere"` with your actual key and IV. 

Also, remember that this is a simple example and for production-level code, you would need to handle errors appropriately (e.g., returning error codes instead of NULL pointers), securely manage keys and memory (consider using safer functions than `malloc()`), validate the inputs, etc. 

This function also doesn't include any padding scheme for encryption, which might be necessary depending on your use case to handle data that isn't a multiple of AES block size. This would require additional code to add/remove padding. You may want to consider using an existing library or framework that provides these features out-of-the-box.
']

