['Here's how you could implement the `generate_md5_hashes` function in Python using the built-in hashlib library:

```python
import os
import sys
import hashlib
from tqdm import tqdm

def generate_md5_hashes(filepaths):
    filepath_hash = {}
    chunk_size = 4096  # bytes to read at a time

    for path in filepaths:
        try:
            filesize = os.path.getsize(path)

            with open(path, 'rb') as f:
                hasher = hashlib.md5()

                with tqdm(total=filesize, unit='B', unit_scale=True, desc=path) as pbar:
                    for chunk in iter(lambda: f.read(chunk_size), b""):
                        hasher.update(chunk)
                        pbar.update(sys.getsizeof(chunk))  # assuming 32-bit system, adjust as needed

                filepath_hash[path] = hasher.hexdigest()

        except (FileNotFoundError, PermissionError):
            print(f"Could not access {path}, please check the path and permissions.")
        except Exception:
            print(f"An error occurred while calculating MD5 hash for {path}.")

    return filepath_hash
```

