['```c
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

void generate_cache_key(const char* url, char* cache_key) {
    // Extract components from URL
    char domain[256] = "";
    char path[1024] = "/";
    char query[1024] = "";
    sscanf(url, "http://%255[^/?]/%1023[^?]", domain); // Extracts domain from URL
    if (strchr(domain, '?')) {
        *strchr(domain, '?') = '\0'; // Removes query parameters from domain
    }

    char* path_start = strchr(url, '/'); // Find start of path or end of string if no path exists
    if (path_start != NULL) {
        sscanf(path_start, "/%1023[^?]", path); // Extracts path from URL
        char* query_start = strchr(url, '?'); // Find start of query parameters or end of string if no parameters exist
        if (query_start != NULL) {
            sscanf(query_start, "?%1023s", query); // Extracts query parameters from URL
        }
    }

    // Generate unique cache key based on components
    char timestamp[32];
    time_t current_time = time(NULL);
    snprintf(timestamp, sizeof(timestamp), "%ld", current_time);

    MD5_CTX mdContext;
    unsigned char digest[16];
    char hexDigest[33];
    int i;

    MD5_Init(&mdContext);
    MD5_Update(&mdContext, domain, strlen(domain));
    MD5_Update(&mdContext, path, strlen(path));
    MD5_Update(&mdContext, query, strlen(query));
    MD5_Update(&mdContext, timestamp, strlen(timestamp));
    MD5_Final(digest, &mdContext);

    for (i = 0; i < 16; ++i) {
        snprintf(hexDigest + i * 2, 3, "%02x", digest[i]);
    }

    // Construct final cache key
    strcpy(cache_key, "");
    strcat(cache_key, domain);
    strcat(cache_key, path);
    if (strlen(query) > 0) {
        strcat(cache_key, query);
    }
    strcat(cache_key, timestamp);
    snprintf(cache_key + strlen(cache_key), 33, "%s", hexDigest); // Append hash to cache key
}
```
