// This function assumes you have a URL struct with fields like domain, path, query etc.
char* generate_cache_key(URL url) {
    char buffer[4096] = ""; // 4KB is a reasonable cache key size
    time_t t = time(NULL);

    if (url.domain == NULL || strlen(url.domain) == 0) {
        snprintf(buffer, sizeof(buffer), "NONE%ld", t);
    } else {
        char* urlString = malloc(sizeof(char) * 4096); // Again, assuming a URL is not larger than this
        strcat(urlString, url.domain);

        if (url.path != NULL && strlen(url.path) > 0) {
            strcat(urlString, url.path);
        }

        // Repeat for other components as needed

        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)&urlString, strlen(urlString), md5);

        snprintf(buffer, sizeof(buffer), "%s%ld", md5, t); // Append timestamp
    }

    return buffer;
}
```

