void add_device(const char *dev_id, void *sensor) {
    pthread_mutex_lock(&mutex);

    // Check if device already exists
    for (int i = 0; i < num_devices; i++) {
        if (!strcmp(devices[i]->dev_id, dev_id)) {
            devices[i]->num_sensors++;
            devices[i]->sensors = realloc(devices[i]->sensors, sizeof(void *) * devices[i]->num_sensors);
            devices[i]->sensors[devices[i]->num_sensors - 1] = sensor;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // If not, create new device context
    num_devices++;
    devices = realloc(devices, sizeof(DevContext *) * num_devices);
    if (!devices) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    devices[num_devices - 1] = malloc(sizeof(DevContext));
    if (!devices[num_devices - 1]) {
        num_devices--;
        pthread_mutex_unlock(&mutex);
        return;
    }

    devices[num_devices - 1]->dev_id = strdup(dev_id);
    if (!devices[num_devices - 1]->dev_id) {
        free(devices[num_devices - 1]);
        num_devices--;
        pthread_mutex_unlock(&mutex);
        return;
    }

    devices[num_devices - 1]->num_sensors = 1;
    devices[num_devices - 1]->sensors = malloc(sizeof(void *));
    if (!devices[num_devices - 1]->sensors) {
        free(devices[num_devices - 1]->dev_id);
        free(devices[num_devices - 1]);
        num_devices--;
        pthread_mutex_unlock(&mutex);
        return;
    }

    devices[num_devices - 1]->sensors[0] = sensor;
    pthread_mutex_unlock(&mutex);
}

