    char **interfaces;
    SSL_SESSION *tls_session;
    pthread_mutex_t lock;
} DeviceContext;

DeviceContext* devices[1024]; // Array of device contexts
pthread_mutex_t devicesLock = PTHREAD_MUTEX_INITIALIZER;
int devicesCount = 0;

DeviceContext* createNewDevice(int devId) {
    DeviceContext *device = (DeviceContext *) malloc(sizeof(DeviceContext));
    device->id = devId;
    device->interfaces = NULL;
    device->tls_session = NULL;
    pthread_mutex_init(&device->lock, NULL);
    return device;
}

void addNewInterface(DeviceContext *devCtx, char *interface) {
    pthread_mutex_lock(&devCtx->lock);

    int numInterfaces = 0;
    while (devCtx->interfaces[numInterfaces] != NULL) {
        numInterfaces++;
    }

    devCtx->interfaces = realloc(devCtx->interfaces, sizeof(char *) * (numInterfaces + 2));
    devCtx->interfaces[numInterfaces] = interface;
    devCtx->interfaces[numInterfaces + 1] = NULL;

    pthread_mutex_unlock(&devCtx->lock);
}

void updateTLSSession(DeviceContext *devCtx, SSL_SESSION *session) {
    pthread_mutex_lock(&devCtx->lock);

    if (devCtx->tls_session != NULL) {
        SSL_SESSION_free(devCtx->tls_session);
    }
    devCtx->tls_session = session;

    pthread_mutex_unlock(&devCtx->lock);
}

void addDevice(int devId) {
    DeviceContext *device = createNewDevice(devId);

    pthread_mutex_lock(&devicesLock);
    devices[devicesCount++] = device;
    pthread_mutex_unlock(&devicesLock);
}

void cleanup() {
    for (int i = 0; i < devicesCount; i++) {
        if (devices[i]->tls_session != NULL) {
            SSL_SESSION_free(devices[i]->tls_session);
        }

        free(devices[i]);
    }
}
