#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct UserProfile {
    char *username;
    char *email;
    int accessIndex;
    char *biography;
    int refCount;
    pthread_mutex_t lock;
} UserProfile;

UserProfile* createProfile(char* username, char* email, char* biography) {
    UserProfile* newProfile = (UserProfile*)malloc(sizeof(UserProfile));

    if (newProfile == NULL) {
        printf("Error: Failed to allocate memory for profile.\n");
        return NULL;
    }

    newProfile->username = username;
    newProfile->email = email;
    newProfile->accessIndex = 0;
    newProfile->biography = biography;
    newProfile->refCount = 1;
    pthread_mutex_init(&(newProfile->lock), NULL);

    return newProfile;
}

void processRecordCallback(char *username, char* email, char* biography, int accessIndex, bool modified) {
    printf("Processing record: %s, %s, %s, %d, Modified: %d\n", username, email, biography, accessIndex, modified);
}

void iterateRecords(UserProfile** profiles, int size, void (*callback)(char*, char*, char*, int, bool)) {
    for (int i = 0; i < size; i++) {
        pthread_mutex_lock(&(profiles[i]->lock));
        if (--(profiles[i]->refCount) == 0) {
            free(profiles[i]);
        } else {
            callback(profiles[i]->username, profiles[i]->email, profiles[i]->biography, profiles[i]->accessIndex, false);
        }
        pthread_mutex_unlock(&(profiles[i]->lock));
    }
}
```
This code creates a user profile structure with fields for username, email, access index, biography, reference count and a mutex to prevent data races. It provides a function to create new profiles safely, another to process records using callbacks and a last one to iterate over all profiles in an array-like manner, decrementing their reference counts before freeing them when they are no longer used.

