using System;

public class DynamicRangeGenerator
{
    private float minVal;
    private float maxVal;

    public DynamicRangeGenerator(float min, float max)
    {
        if (min > max)
        {
            this.maxVal = min;
            this.minVal = max;
        }
        else
        {
            this.minVal = min;
            this.maxVal = max;
        }
    }

    public void SetRange(float min, float max)
    {
        if (min > max)
        {
            this.maxVal = min;
            this.minVal = max;
        }
        else
        {
            this.minVal = min;
            this.maxVal = max;
        }
    }

    public float GetRandomFloatInclusive()
    {
        Random rnd = new Random();
        return (float)(rnd.NextDouble() * (this.maxVal - this.minVal) + this.minVal);
    }

    public float GetRandomFloatExclusive()
    {
        Random rnd = new Random();
        return (float)(rnd.NextDouble() * (this.maxVal - this.minVal - 1) + this.minVal + 1);
    }

    public int GetRandomIntInclusive()
    {
        Random rnd = new Random();
        return rnd.Next((int)(this.minVal), (int)(this.maxVal));
    }

    public bool IsValid()
    {
        if(this.minVal <= this.maxVal) 
            return true;
         else 
            return false;
    }

    public float GetMidPoint()
    {
        return (this.minVal + this.maxVal) / 2;
    }

    public override string ToString()
    {
        return "Range: (" + this.minVal + ", " + this.maxVal + ") | Midpoint: " + GetMidPoint() + " | Validation Status: " + IsValid();
    }
}
