['Here is a Python function that calculates the MD5 hash of a file in chunks:
```python
import os
import hashlib

def md5_file(path):
    h = hashlib.md5()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            h.update(chunk)
    return h.hexdigest()
```
The following C code implements the functionality described:
```c
#include <stdio.h>
#include <openssl/md5.h>
#include <string.h>

char* generate_unique_filename(const char *filename) {
    FILE *file;
    MD5_CTX c;
    unsigned char digest[16];
    int bytes;
    char buffer[4096], newname[256] = "";

    file = fopen(filename, "rb");

    if (!file) {
        printf("Could not open the file.\n");
        return NULL;
    }

    MD5_Init(&c);
    while ((bytes = fread(buffer, 1, sizeof buffer, file))) {
        MD5_Update(&c, buffer, bytes);
    }
    MD5_Final(digest, &c);

    for (int i = 0; i < sizeof digest; ++i) {
        sprintf(newname + strlen(newname), "%02x", digest[i]);
    }

    fclose(file);

    const char *ext = strrchr(filename, '.');
    if (!ext) {
        ext = "";
    }

    snprintf(newname + strlen(newname), sizeof newname - strlen(newname), "%s", ext);

    char *result = malloc((strlen(filename) + 32) * sizeof(*result));
    if (!result) {
        printf("Could not allocate memory.\n");
        return NULL;
    }

    strcpy(result, newname);
    return result;
}
```
Remember to link with the OpenSSL library: `-lssl -lcrypto`. This code is efficient as it uses buffered I/O and doesn't load the entire file into memory at once, which would be inefficient for large files. It also checks if memory allocation was successful before proceeding to prevent a potential crash due to out of memory error.
']

['Here is a Python version of your request using `hashlib` for MD5 hash calculation and a C function `generate_unique_filename` that generates a unique identifier from the filename's content using `mmap` for memory efficiency. 

```python
import os
import hashlib
from mmap import mmap, ACCESS_READ

def calculate_file_md5(path):
    md5 = hashlib.md5()
    with open(path, 'rb') as f:
        with mmap(f.fileno(), 0, access=ACCESS_READ) as mm:
            md5.update(mm)
    return md5.hexdigest()
```

For the C function, it's important to note that this is a complex task and may not meet all edge cases due to the nature of the problem. In particular, generating unique identifiers from file content is nontrivial and could result in collisions if two different files have identical content (though the probability of such an event is low).

```c
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <openssl/md5.h>

char *generate_unique_filename(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Cannot open the file");
        return NULL;
    }

    off_t size = lseek(fd, 0, SEEK_END);
    char *file_content = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (file_content == MAP_FAILED) {
        perror("Cannot map the file");
        close(fd);
        return NULL;
    }

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5((unsigned char*) file_content, size, md5);

    munmap(file_content, size);
    close(fd);

    // Convert the MD5 hash to hex string (32 bytes) plus one byte for null termination
    char *md5hex = calloc(MD5_DIGEST_LENGTH*2 + 1, sizeof(char));
    if (!md5hex) {
        perror("Cannot allocate memory");
        return NULL;
    }

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) 
        sprintf(&md5hex[i*2], "%02x", md5[i]);

    // Find the extension part of the filename, if any
    char *extension = strrchr(filename, '.');

    size_t base_len = (extension == NULL) ? strlen(filename) : extension - filename;
    size_t new_name_len = base_len + MD5_DIGEST_LENGTH*2 + 1; // include the dot and null termination
    if (new_name_len > 128) {
        fprintf(stderr, "New filename too long\n");
        free(md5hex);
        return NULL;
    }

    char *new_filename = malloc(sizeof(char) * new_name_len);
    if (!new_filename) {
        perror("Cannot allocate memory");
        free(md5hex);
        return NULL;
    }

    strncpy(new_filename, filename, base_len);
    strcat(new_filename, ".");
    strcat(new_filename, md5hex);

    free(md5hex);

    return new_filename;
}
```
This C code uses OpenSSL's `MD5` function to calculate the MD5 hash of a file's content. It then converts this hash into a hexadecimal string, appending it to the filename as an identifier. Note that this implementation assumes filenames are valid and don't contain invalid characters or paths. It also doesn't handle cases where the new filename exceeds 128 characters by checking the length before concatenation. Finally, memory allocation and deallocation is managed using `calloc` and `free` to prevent leaks.
']

['Here's a Python implementation for your task:

```python
import hashlib
import os
import re
from uuid import uuid4

def generate_file_hash_and_rename(filepath):
    block_size = 8192  # Arbitrary value to fit memory
    with open(filepath, 'rb') as f:
        hasher = hashlib.md5()
        buf = f.read(block_size)
        while len(buf) > 0:
            hasher.update(buf)
            buf = f.read(block_size)
    filehash = hasher.hexdigest()

    _, ext = os.path.splitext(filepath)
    new_name = re.sub(r'\W+', '', filehash[:64]) + ext  # Remove non-alphanumeric characters and use hash as unique identifier
    if len(new_name) > 128:  # Limit filename length to 128 characters
        new_name = re.sub(r'\W+', '', filehash[:64 - (len(new_name) - 128)] + ext  # Adjust identifier to fit within limit
    os.rename(filepath, os.path.join(os.path.dirname(filepath), new_name))
    return filehash
```

For the companion C function, you would need access to the specific system's file management functions and library functions for string manipulation/regular expressions. Here's a simple example based on Linux system:

