char* modify_filename(const char *filepath) {
    FILE *file = fopen(filepath, "rb");
    if (!file) return NULL;  // Return null on file open error

    unsigned char buffer[1024];  // Define a buffer size
    MD5_CTX context;
    unsigned char digest[MD5_DIGEST_LENGTH];

    int bytes;
    MD5_Init(&context);
    while ((bytes = fread(buffer, 1, sizeof(buffer), file)) != 0) {
        MD5_Update(&context, buffer, bytes);
    }
    MD5_Final(digest, &context);

    char *hexdigest = malloc((MD5_DIGEST_LENGTH*2+1)*sizeof(char));  // Allocate memory for hex digest
    if (!hexdigest) return NULL;  // Return null on allocation error

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hexdigest[i*2], "%02x", digest[i]);
    }

    uuid_t id;
    char *new_name = malloc(sizeof(char)*130);  // Allocate memory for new name
    if (!new_name) return NULL;  // Return null on allocation error

    strncpy(new_name, hexdigest, 64);  // Use hash as unique identifier

    char *ext = strrchr(filepath, '.');
    if (ext) {
        strcat(new_name, ext);
    }

    free(hexdigest);
    fclose(file);

    return new_name;  // Return the new filename or null on error
}
