#[derive(Parser, Debug)]
struct Args {
    #[arg(short, long)]
    filename: String,
}

fn rename_file(filename: &str) -> Result<()> {
    let digest = compute_md5(&fs::read(filename)?);

    let ext = filename.split('.').last().unwrap();
    let unique_id = format_unique_id(&digest, ext);

    if let Some((name, _)) = filename.rsplit_once('.') {
        fs::rename(filename, &format_new_filepath(name, unique_id, ext))?;
    } else {
        fs::rename(filename, &unique_id)?;
    }

    Ok(())
}

fn format_unique_id(digest: &[u8], ext: &str) -> String {
    let unique_len = digest.len() / 2;
    format_filename(&format_hex(&digest[..unique_len]), Some(ext))
}

fn compute_md5(content: &Vec<u8>) -> Vec<u8> {
    md5::compute_md5(content).into_iter().collect()
}

fn format_filename(name: &str, ext: Option<&str>) -> String {
    match ext {
        Some(ext) => format_name(name, ext),
        None => name.to_string(),
    }
}

fn format_hex(data: &[u8]) -> String {
    data.iter().map(|byte| format_part(*byte as usize)).collect()
}

fn format_name(name: &str, ext: &str) -> String {
    match name.len() <= 127 - ext.len() - 1 {
        true => format![{}.{}", name, ext],
        false => panic_unwrap(format_truncated_name(name, ext)),
    }
}

fn format_part(value: usize) -> String {
    format![{:02x}", value]
}

fn format_hex_chars() -> impl Iterator<Item = char> {
    ('a'..='f').chain('0'..='9')
}

fn panic_unwrap(result: Result<String>) -> String {
    result.unwrap_or_else(|error| panic![Failed to format filename, {}", error])
}

pub fn format_truncated_name(name: &str, ext: &str) -> Result<String> {
    let truncate = |value: usize| value.min(127 - ext.len() - 1);

    Ok(format![{}.{}", &name[..truncate(name.len())], ext])
}
```
In this Rust code, `Args::parse` will parse the command line arguments and throw an error if they are invalid or not provided. It uses the `tokio` runtime to execute the blocking function asynchronously using `spawn_blocking`. If any error occurs during this process, it will be returned in a `Result<()>` type. If no errors occur, `Ok(())` is returned.
