For the Rust function `modify_filename` using Tokio for asynchronous execution:
```rust
use std::fs;
use std::path::Path;
use tokio::task::spawn_blocking;
use uuid::Uuid;

async fn modify_filename(mut filename: String) -> Result<String, &'static str> {
    if let Some(extension) = Path::new(&filename).extension() {
        let unique_identifier = Uuid::new_v5(&Uuid::NAMESPACE_URL, filename.as_bytes()).to_simple().to_string();
        let new_extention = format![unique_identifier,"{}", extension];
        if filename.len() + new_extention.len() > 128 {
            return Err("Filename too long")
        } else {
           filename += &new_extention; 
        }
    } else {
        return Err("Invalid Filename");
    }
    spawn_blocking(move || {
        fs::rename(&filename, &format![filename,".new"])
    })
    .await?;
    Ok(filename)
}
```
This Rust function first checks the file's extension and if there is no valid extension it returns an error. If the extension exists then a unique identifier is generated using UUIDv5. The unique identifier is appended to the new filename ensuring that its length does not exceed 128 characters. Then, Tokio's `spawn_blocking` function is used for asynchronous renaming of files.
']

