public class DynamicRangeGenerator
{
    private float minValue;
    private float maxValue;
    private bool isValid = true;

    public DynamicRangeGenerator(float min, float max)
    {
        if (min > max)
        {
            Console.WriteLine("Invalid range provided, swapping values.");
            this.maxValue = min;
            this.minValue = max;
            isValid = false;
        }
        else
        {
            this.minValue = min;
            this.maxValue = max;
        }
    }

    public void SetRange(float min, float max)
    {
        if (min > max)
        {
            Console.WriteLine("Invalid range provided, swapping values.");
            this.maxValue = min;
            this.minValue = max;
            isValid = false;
        }
        else
        {
            this.minValue = min;
            this.maxValue = max;
            isValid = true;
        }
    }

    public float GenerateFloatInclusive()
    {
        if (!isValid) throw new InvalidOperationException("Invalid range!");

        Random rand = new Random();
        return (float)(minValue + rand.NextDouble() * (maxValue - minValue));
    }

    public float GenerateFloatExclusive()
    {
        if (!isValid) throw new InvalidOperationException("Invalid range!");

        Random rand = new Random();
        return (float)(minValue + rand.NextDouble() * (maxValue - minValue + 0.001));
    }

    public int GenerateIntegerInclusive()
    {
        if (!isValid) throw new InvalidOperationException("Invalid range!");

        Random rand = new Random();
        return rand.Next((int)minValue, (int)(maxValue + 1));
    }

    public float GetMidpoint()
    {
        if (!isValid) throw new InvalidOperationException("Invalid range!");

        return (minValue + maxValue) / 2;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}], Midpoint: {GetMidpoint()}, Is Valid? {isValid}";
    }

    public static string GetMD5Hash(string input)
    {
        try
        {
            using (var md5 = MD5.Create())
            {
                byte[] data = md5.ComputeHash(Encoding.UTF8.GetBytes(input));

                StringBuilder sBuilder = new StringBuilder();

                for (int i = 0; i < data.Length; i++)
                    sBuilder.Append(data[i].ToString("x2"));

                return sBuilder.ToString();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred while creating MD5 hash: " + ex.Message);
            return string.Empty;
        }
    }
}
