    int capacity;
    int size;
    UEContext **array;
} DynamicArray;

void initDynamicArray(DynamicArray *arr) {
    arr->capacity = 10;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    arr->array = malloc(arr->capacity * sizeof(UEContext*));
}

void addToDynamicArray(DynamicArray *arr, UEContext *context) {
    pthread_mutex_lock(&arr->lock);

    // Check if we need to resize the array
    if (arr->size == arr->capacity) {
        arr->capacity *= 2;
        arr->array = realloc(arr->array, arr->capacity * sizeof(UEContext*));
    }

    // Add the context to the array
    arr->array[arr->size++] = context;

    pthread_mutex_unlock(&arr->lock);
}
