import os
import hashlib

def calc_file_hashes(files):
    result = {}

    for file in files:
        if not os.path.isfile(file):
            print(f"Error: {file} does not exist.")
            continue

        try:
            with open(file, 'rb') as f:
                sha256 = hashlib.sha256()
                while True:
                    data = f.read(65536) # read file in 64kb chunks

                    if not data:
                        break

                    sha256.update(data)

            result[file] = sha256.hexdigest()

        except (IOError, PermissionError):
            print(f"Error occurred while reading {file}.")

    return result
```
