void handle_large_files_efficiently(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == nullptr) {
        std::cerr << "Cannot open file: " << filename << std::endl;
        return;
    }

    fseek(file, 0L, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    char* buffer = (char*) malloc((fileSize + 1) * sizeof(char)); // use of malloc to handle large files efficiently
    if (!buffer) {
        std::cerr << "Memory allocation failed!" << std::endl;
        fclose(file);
        return;
    }

    size_t bytesRead = fread(buffer, 1, fileSize, file);
    buffer[bytesRead] = 0; // null-terminating the string
    fclose(file);

    handle_service_lifecycle();
    modify_config(filename);
}
