#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int EVENT_TYPE;
    long TIMESTAMP;
    int SOURCE_ID;
} LOG_EVENT_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    size_t head;
    size_t tail;
    size_t size;
    LOG_EVENT_T *buffer;
} CircularBuffer;

static void checkAndResize(CircularBuffer* cb, int newSize) {
    if (newSize > cb->size) {
        cb->buffer = realloc(cb->buffer, sizeof(LOG_EVENT_T) * newSize);

        // handle the case when we wrapped around the end of the buffer 
        if (cb->tail < cb->head) {
            memmove(&cb->buffer[newSize - (cb->size - cb->head)], &cb->buffer[cb->head], sizeof(LOG_EVENT_T) * (cb->size - cb->head));
            cb->head = newSize - (cb->size - cb->head);
        }

        cb->size = newSize;
    }
}

void pushEvent(CircularBuffer* cb, LOG_EVENT_T event) {
    pthread_mutex_lock(&mutex);

    // check and resize if needed
    if ((cb->tail + 1) % cb->size == cb->head) 
        checkAndResize(cb, cb->size * 2);

    // check SOURCE_ID is unique
    for (size_t i = cb->head; i != cb->tail; i = (i + 1) % cb->size) {
        if (cb->buffer[i].SOURCE_ID == event.SOURCE_ID) 
            return;
    }

    // check TIMESTAMP is monotonically increasing
    if (!(cb->tail == 0 || cb->buffer[(cb->tail - 1 + cb->size) % cb->size].TIMESTAMP < event.TIMESTAMP))
        return;

    cb->buffer[cb->tail] = event;
    cb->tail = (cb->tail + 1) % cb->size;

    pthread_mutex_unlock(&mutex);
}
```
