public class JsonProcessor {
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final Gson gson = new Gson();

    public void processJsonFile(String filePath) throws IOException, InterruptedException {
        // Read the JSON file
        FileReader reader = new FileReader(filePath);

        JsonNode rootNode = mapper.readTree(reader);

        if (rootNode.isArray()) {
            for (JsonNode node : rootNode) {
                processObject(node);
            }
        } else {
            processObject(rootNode);
        }
    }

    private void processObject(JsonNode node) throws InterruptedException, IOException {
        ExecutorService executor = Executors.newFixedThreadPool(10); // 10 threads in the pool

        for (Iterator<Map.Entry<String, JsonNode>> it = node.fields(); it.hasNext(); ) {
            Map.Entry<String, JsonNode> field = it.next();

            if (!field.getValue().isContainerNode()) { // If it's not a container node (like array or object)
                processField(field);
            } else {
                if (field.getValue().isArray()) { // Nested Array
                    for (JsonNode child : field.getValue()) {
                        executor.submit(() -> processObject(child));
                    }
                } else { // Nested Object
                    executor.submit(() -> processObject(field.getValue()));
                }
            }
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS); // Wait for all tasks to finish
    }

