    private readonly ISessionTokenService _sessionTokenService;
    private readonly IPageSectionUpdateService _pageSectionUpdateService;
    private readonly IForwardListOperations _forwardListOperations;

    public HttpRequestProcessor(ILogger<HttpRequestProcessor> logger, 
                                 ISessionTokenService sessionTokenService, 
                                 IPageSectionUpdateService pageSectionUpdateService, 
                                 IForwardListOperations forwardListOperations)
    {
        _logger = logger;
        _sessionTokenService = sessionTokenService;
        _pageSectionUpdateService = pageSectionUpdateService;
        _forwardListOperations = forwardListOperations;
    }

    public async Task<HttpStatusCode> ProcessRequestAsync(string sessionToken, int sectionId, string elementId, string htmlContent)
