typedef struct Node {
    MAC_CONTEXT_T* context;
    int priority;
    struct Node* prev;
    struct Node* next;
} Node;

#define MAX_QUEUES 10
Node* queues[MAX_QUEUES];
pthread_mutex_t lock;
MallocExtension mExt = MallocExtension();

void insert(MAC_CONTEXT_T* context) {
    pthread_mutex_lock(&lock);

    int priority = context->priority;
    if (priority < 0 || priority >= MAX_QUEUES) {
        printf("Invalid Priority\n");
        return;
    }

    Node* node = malloc(sizeof(Node));
    node->context = context;
    node->next = queues[priority];
    node->prev = NULL;

    if (queues[priority] != NULL) {
        queues[priority]->prev = node;
    }
    queues[priority] = node;

    pthread_mutex_unlock(&lock);
}

void delete(MAC_CONTEXT_T* context) {
    pthread_mutex_lock(&lock);

    int priority = context->priority;
    if (priority < 0 || priority >= MAX_QUEUES) {
        printf("Invalid Priority\n");
        return;
    }

    Node* node = queues[priority];
    while(node != NULL){
        if(node->context == context){
            if(node->prev != NULL){
                node->prev->next = node->next;
            } else {
                queues[priority] = node->next;
            }

            if(node->next != NULL){
                node->next->prev = node->prev;
            }

            free(node);
            break;
        }

        node = node->next;
    }

    pthread_mutex_unlock(&lock);
}

