['Implementing all these details in one single C code block would require significant space, but below is a simplified version of how such DNS resolution function could be implemented using libc's getaddrinfo() and a basic cache system for storing resolved IP addresses.

```C
#include <netdb.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/time.h>

#define CACHE_EXPIRY 60 // Cache entries expire after 1 minute
#define WHITELIST_SIZE 5 // Size of the whitelist

typedef struct {
    char hostname[253];
    struct in_addr ip;
    time_t timestamp;
} DNSCacheEntry;

DNSCacheEntry dns_cache[WHITELIST_SIZE] = {0}; // Initialize cache with zeroes
char whitelist[WHITELIST_SIZE][253] = {"google.com", "facebook.com", /* other trusted hostnames */ };

int resolve(const char* hostname, u_char ip[4]) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // Only IPv4 addresses

    int i;
    for(i = 0; i < WHITELIST_SIZE; ++i) {
        if(!strcmp(whitelist[i], hostname)) break; // If hostname in whitelist, proceed
    }
    if(i == WHITELIST_SIZE) return -1; // Hostname not in whitelist

    time_t current_time = time(NULL);
    for(i = 0; i < WHITELIST_SIZE; ++i) {
        if(!strcmp(dns_cache[i].hostname, hostname)) { // If found in cache and not expired
            if((current_time - dns_cache[i].timestamp) <= CACHE_EXPIRY) {
                memcpy(ip, &dns_cache[i].ip.s_addr, 4);
                return 0; // Found in cache and not expired
            } else {
                break; // Expired, but still exists in cache
            }
        }
    }

    int ret = getaddrinfo(hostname, NULL, &hints, &res); // Perform DNS resolution
    if(!ret) { // If successful
        struct sockaddr_in *sa = (struct sockaddr_in *)res->ai_addr;
        memcpy(ip, &sa->sin_addr.s_addr, 4); // Store IP in u_char array

        // Update cache entry
        strncpy(dns_cache[i].hostname, hostname, sizeof(dns_cache[i].hostname));
        dns_cache[i].ip = sa->sin_addr;
        dns_cache[i].timestamp = current_time;

        freeaddrinfo(res); // Free memory allocated by getaddrinfo()
    } else {
        return -2; // DNS resolution failed, possibly due to network condition or timeout
    }

    return 0;
}
```
Please note that this is a simplified example and does not address many concerns such as thread safety for cache access, error handling with respect to logging system, integration of time-based eviction policy in the cache, concurrent query processing and resource management. Also, using libc's getaddrinfo() will not work on all network environments or configurations, so a more comprehensive solution might involve platform specific APIs or use of third party libraries like c-ares.
