['```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>

// Struct to hold task data
typedef struct Task {
    int id;
    char *description;
    time_t executionTime; // Execution time in seconds since epoch
    pthread_mutex_t mutex; // Mutex for thread safety
} Task;

// Global array of tasks, dynamically allocated
Task **tasks = NULL;
int taskCount = 0;
int taskCapacity = 0;
pthread_mutex_t taskMutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

// Load default execution time from config file
time_t getDefaultExecutionTime() {
    FILE *file = fopen("config.txt", "r");
    if (file == NULL) {
        printf("Failed to open configuration file\n");
        return -1;
    }
    char buffer[256];
    if(fgets(buffer, sizeof(buffer), file) != NULL) {
        time_t defaultTime = atoi(buffer);
        fclose(file);
        return defaultTime;
    } else {
        printf("Failed to read execution time from configuration file\n");
        fclose(file);
        return -1;
    }
}

// Add a task to the list, thread-safe
void addTask(int id, char *description) {
    pthread_mutex_lock(&taskMutex); // Lock tasks array for modification

    Task *newTask = (Task *)malloc(sizeof(Task));
    newTask->id = id;
    newTask->description = description;
    time_t defaultTime = getDefaultExecutionTime();
    if(defaultTime != -1) { // If successfully read from config, set as execution time
        newTask->executionTime = defaultTime;
    } else {
        free(newTask);
        return;
    }

    pthread_mutex_init(&newTask->mutex, NULL); // Initialize task mutex

    if (taskCount == taskCapacity) { // Reallocate array if full
        taskCapacity = (taskCapacity == 0 ? 1 : taskCapacity * 2);
        tasks = (Task **)realloc(tasks, sizeof(Task *) * taskCapacity);
    }

    tasks[taskCount++] = newTask; // Add to array

    pthread_mutex_unlock(&taskMutex); // Unlock tasks array after modification
}

// Remove a task from the list, thread-safe
void removeTask(int id) {
    pthread_mutex_lock(&taskMutex); // Lock tasks array for modification

    int i;
    for (i = 0; i < taskCount; i++) {
        if (tasks[i]->id == id) break; // Find task by ID
    }

    if (i != taskCount) { // Task found, remove it
        pthread_mutex_lock(&tasks[i]->mutex); // Lock task for removal

        free(tasks[i]); // Free memory

        tasks[i] = tasks[--taskCount]; // Move last task to removed position
        if (taskCapacity > 4 * taskCount) { // Shrink array if 25% unused space
            taskCapacity /= 2;
            tasks = (Task **)realloc(tasks, sizeof(Task *) * taskCapacity);
        }

        pthread_mutex_unlock(&tasks[i]->mutex); // Unlock task after removal
    }

    pthread_mutex_unlock(&taskMutex); // Unlock tasks array after modification
}
```

This is a basic implementation of the described functionality. Please note that the exact API and behavior may vary based on your specific requirements or constraints. For example, you might want to consider using a more efficient data structure than an array for storing tasks. Additionally, this code does not handle task execution; it just manages adding and removing tasks. Task execution would typically involve creating threads or processes to run the tasks at their specified times, which is beyond the scope of this function.
']

