['Here's an example of how you can implement this function in C using the OpenSSL library. 
Please note that this is just a simple illustration and does not cover all features mentioned above due to complexity of cryptography libraries handling. 

```c
#include <openssl/evp.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    const char *name;
    EVP_MD *(*getFunc)();
} HashData;

HashData hashes[] = {
    {"md5", &EVP_md5},
    {"sha1", &EVP_sha1},
    {"sha256", &EVP_sha256},
};
#define NUM_HASHES (sizeof(hashes)/sizeof(HashData))

typedef struct node {
    const char *name;
    EVP_MD *(*getFunc)();
    struct node *next;
} Node;

Node* createNode(const char *name, EVP_MD *(*getFunc)()) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->name = name;
    node->getFunc = getFunc;
    return node;
}

void addNodeToEnd(Node **head, const char *name, EVP_MD *(*getFunc)()) {
    Node *node = createNode(name, getFunc);
    if (*head == NULL) {
        *head = node;
    } else {
        Node *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

void freeList(Node **head) {
    Node* current = *head;
    Node* next;

    while (current != NULL)
    {
       next = current->next;
       free(current);
       current = next;
    }
    *head = NULL;
}

Node* getAvailableHashes() {
    Node *head = NULL;

    for (size_t i = 0; i < NUM_HASHES; ++i) {
        if (hashes[i].getFunc() != NULL) {
            addNodeToEnd(&head, hashes[i].name, hashes[i].getFunc);
        }
    }

    return head;
}
