["The task you're asking for involves several complex aspects and may not be fully doable with a single code block due to its complexity. However, here is an example of what your program might look like in a simplified form:

```cpp
#include <random>
#include <vector>
#include <mutex>
#include <chrono>

namespace RandomService {
    class GeneratorPool {
        private:
            std::vector<std::mt19937> generators;
            std::recursive_mutex mtx;  // allows recursion and guarantees thread safety.

            void resize(int newSize) {
                if (newSize > generators.size()) {
                    for(int i = generators.size(); i < newSize; ++i) {
                        unsigned seed = std::chrono::system_clock::now().time_since_epoch().count() + getpid();
                        generators.push_back(std::mt19937(seed));
                    }
                } else if (newSize < generators.size()) {
                    generators.resize(newSize);
                }
            }

        public:
            GeneratorPool(int initialSize = 1) {
               resize(initialSize);
            }

            int getRandomInt() {
                std::lock_guard<std::recursive_mutex> lock(mtx);
                return generators[0]();  // get a random number from the first generator.
            }

            double getRandomDouble() {
                std::lock_guard<std::recursive_mutex> lock(mtx);
                return std::generate_canonical<double, std::numeric_limits<double>::digits>(generators[0]);
            }
    };
}
```
This is a simplified example. The actual implementation could be much more complex and would need to take into account things like: 

