using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Diagnostics;
using Dapper;
using NLog;

public class SqlQueryExecutor
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();
    private IDbConnection connection;

    public SqlQueryExecutor(IDbConnection connection)
    {
        this.connection = connection;
    }

    public List<Dictionary<string, object>> ExecuteDynamicSqlQuery(string schemaName, IEnumerable<string> fieldsToSelect, string filterCondition, IDictionary<string, object> parameters = null)
    {
        var stopwatch = new Stopwatch();
        stopwatch.Start();

        try
        {
            var query = $"SELECT {string.Join(", ", fieldsToSelect)} FROM {schemaName} WHERE {filterCondition}";

            logger.Info("Executing SQL Query: " + query);

            // Parameterize your queries to prevent SQL injection attacks 
            var results = parameters != null ? 
                this.connection.Query(query, parameters).ToList() :
                this.connection.Query(query).ToList();

            stopwatch.Stop();
            logger.Info("SQL Query execution time: " + stopwatch.ElapsedMilliseconds + "ms");

            // Cache the results here if required by your application 
            return results;
        }
        catch (Exception ex)
        {
            stopwatch.Stop();
            logger.Error("SQL Query execution failed: " + ex);
            throw;
        }
    }
}
```
This class is simple and assumes that you have set up your logging correctly. It will log the SQL queries as they are executed, along with their execution times in milliseconds. If an error occurs during query execution, it logs the error message and then rethrows the exception to be handled by the caller. 

