['Here is a basic implementation using NodeJS's `fs`, `readline` and `lru-cache` modules for asynchronous file reading, line by line reading, caching and LRU cache respectively. This code doesn't integrate with external logging service or any existing logging framework because it is not provided in the question. For network latency optimization DNS resolution can be done using NodeJS `dns` module but since we are only reading local files here, I didn't implement that part. 

```javascript
const fs = require('fs');
const readline = require('readline');
const { Cache } = require('lru-cache');

// Initialize LRU cache with a maximum size of 1000 files
let fileCache = new Cache({ max: 1000 });

function readAndCacheFiles(dirPath) {
    return new Promise((resolve, reject) => {
        fs.readdir(dirPath, (err, files) => {
            if (err) {
                console.error("An error occurred while reading the directory: ", err);
                resolve({ success: false, error: err });
            } else {
                let fileContents = '';
                let metadata = { readFiles: [], errors: [] };

                files.forEach(file => {
                    // Check if this file is cached and not modified since last access
                    let cachedContent = fileCache.get(file);

                    if (cachedContent && fs.statSync(`${dirPath}/${file}`).mtime <= cachedContent.lastAccessed) {
                        // File was read before, and hasn't been modified since
                        metadata.readFiles.push(file);
                        fileContents += cachedContent.content;
                    } else {
                        // Else read the file content
                        const rl = readline.createInterface({ input: fs.createReadStream(`${dirPath}/${file}`) });

                        rl.on('line', line => {
                            fileContents += `${line}\n`;
                        }).on('close', () => {
                            // Cache this read content for future access
                            let lastAccessed = new Date();
                            fileCache.set(file, {content: fileContents, lastAccessed});

                            metadata.readFiles.push(file);
                        }).on('error', err => {
                            console.error("An error occurred while reading a file: ", err);
                            metadata.errors.push({file, error: err});
                        });
                    }
                });

                resolve({ success: true, fileContents, metadata });
            }
        });
    });
}
```
Please be aware that this is just a basic implementation and may not cover all edge cases. Always thoroughly test your code before deploying to production. This function reads files line by line which might become inefficient if the files are very large. You might want to consider reading files in chunks or using streaming APIs for large files. 

Also, this function doesn't handle non-standard file extensions and will throw an error when encountering them. For more robustness, you might want to add additional checks or conversions based on your use case.
']

