["Here is a simple JavaScript implementation of your requirements using NodeJS Buffer API. It uses worker threads for concurrent read and write operations. 

```javascript
const { Worker } = require('worker_threads');
const MAX_BUFFER_SIZE = 64 * 1024; // 64KB
let completedRequestCount = 0;
let totalBytesRemainingToBeProcessed = 0;

// Create a new worker for each chunk of data.
function processDataChunks(dataChunks, callback) {
  let totalSize = dataChunks.reduce((accumulator, chunk) => accumulator + chunk.length, 0);
  totalBytesRemainingToBeProcessed += totalSize;

  for (let i = 0; i < dataChunks.length; i++) {
    const workerData = {
      index: i,
      chunk: dataChunks[i],
      callback
    };

    // Each worker will copy MAX_BUFFER_SIZE bytes of data into a new buffer and notify the main thread when done.
    const worker = new Worker('./worker-thread.js', { workerData });
    worker.on('message', handleWorkerCompletion);
  }
}

function handleWorkerCompletion(completedChunkSize) {
  totalBytesRemainingToBeProcessed -= completedChunkSize;
  ++completedRequestCount;

  if (totalBytesRemainingToBeProcessed === 0 && completedRequestCount % 100 === 0) {
    callback(null, 'All data successfully copied');
  }
}
```

For the worker thread implementation:

```javascript
const { parentPort, workerData } = require('worker_threads');
const MAX_BUFFER_SIZE = 64 * 1024; // 64KB

// Copies data from the chunk to a new buffer in chunks of size MAX_BUFFER_SIZE.
function copyChunkToBuffer(chunk, index) {
  const numCopies = Math.ceil(chunk.length / MAX_BUFFER_SIZE);

  for (let i = 0; i < numCopies; ++i) {
    const startIndex = i * MAX_BUFFER_SIZE;
    let endIndex = Math.min((i + 1) * MAX_BUFFER_SIZE, chunk.length);

    // Create a new buffer and copy the data from the chunk to it.
    let newBuffer = Buffer.alloc(endIndex - startIndex);
    chunk.copy(newBuffer, 0, startIndex, endIndex);

    console.log(`Chunk ${index}: copied ${startIndex}-${endIndex} of ${chunk.length} bytes.`);
  }

  return numCopies * MAX_BUFFER_SIZE; // Return the total size of data copied.
}

const completedSize = copyChunkToBuffer(workerData.chunk, workerData.index);
parentPort.postMessage(completedSize);
```
