["Here is a simplified outline of what this JavaScript module might look like using Promises and async/await for better control flow and error handling. 

```javascript
const loadedFiles = [];
let cachedAPIData;

async function loadFile(file) {
    if (loadedFiles.includes(file)) {
        return Promise.resolve();
    }

    try{
        const response = await fetch(`/${file}`);

        if (!response.ok) throw new Error('Network response was not ok');

        eval(await response.text()); // Execute the script
        loadedFiles.push(file); // Mark as loaded
    } catch (error) {
        console.log('Error loading file:', error);
        return Promise.reject();
    }
}

async function validateFileWithAPI(file){
  if(!cachedAPIData){
    try{
      const response = await fetch('/api/validate');

      if (!response.ok) throw new Error('Network response was not ok');

      cachedAPIData = await response.json();
    } catch (error) {
        console.log('Error validating file with API:', error);
        return Promise.reject(`Failed to validate ${file} with API, proceeding without validation.`);
    }
  }

  if(!cachedAPIData[file]){
    return Promise.reject(`File ${file} not found in cached API data.`);
  }

  return Promise.resolve();
}

async function loadAndValidateFilesInOrder(files) {
    for (let file of files) {
        try{
          await validateFileWithAPI(file);
          await loadFile(file);
        } catch (error){
          console.log('Error validating or loading a file:', error);
          return Promise.reject(); // Stop on first validation/load failure
        }
    }

    return Promise.resolve();
}

module.exports = {
  loadAndValidateFilesInOrder,
};
```

Please note that this is a simplified solution and might require additional adjustments based on the exact requirements. For example, you might want to consider using a bundler like webpack or Rollup for managing dependencies between your files instead of using `eval()` directly. You also need to implement caching strategies according to your specific needs and scale testing methodologies.
