function handleAuthFlow($tenantId) {
    // Retrieve client ID and secret from configuration store based on tenant ID
    $client = getClientCredentialsFromStore($tenantId);

    // Initialize cache to store access tokens securely
    $cacheKey = $tenantId . '_access_token';
    $cachedToken = Cache::get($cacheKey);

    if ($cachedToken && !isExpired($cachedToken)) {
        return $cachedToken;
    } elseif ($cachedToken && isExpired($cachedToken)) {
        // Refresh expired token in the background to avoid API disruption
        $refreshedToken = refreshAccessToken($client);

        Cache::set($cacheKey, $refreshedToken);

        return $refreshedToken;
    } else {
        // If there's no cached token or it's expired, fetch a new one
        $fetchedToken = fetchAccessToken($client);

        Cache::set($cacheKey, $fetchedToken);

        return $fetchedToken;
    }
}
