void processTransaction(Transaction *tx, int maxVolume, double agingThreshold) {
    static size_t volume = 0;
    static double weightedSum = 0.0;
    static time_t lastTimestamp = -1;

    if (lastTimestamp == -1 || difftime(tx->timestamp, lastTimestamp) > agingThreshold) {
        volume = 0;  // reset the volume counter for a new timestamp
    } else {
        ++volume;
    }

    if (volume < maxVolume) {
        weightedSum += tx->amount;
    } else {
        fprintf(stderr, "Transaction volume exceeded threshold\n");
    }

    lastTimestamp = tx->timestamp;
}

void *thread_processTransactions(void *arg) {
    Transaction *tx = (Transaction *)arg;

    processTransaction(tx, 50, 3.0);

    return NULL;
}

