// Function to load a resource bundle from a file
SectionNode* loadResourceBundle(const char* path) {
    // Lock mutex before starting operation
    pthread_mutex_lock(&mutex);

    SectionNode* head = NULL;
    SectionNode** tail = &head;

    // Check if the file is already open and cached
    for(int i = 0; i < 256; ++i) {
        if(cache[i] != NULL && strcmp(path, cache[i]->data->name) == 0) {
            pthread_mutex_unlock(&mutex);
            return cache[i];
        }
    }

    // Open file in read mode and get its size
    FILE* fp = fopen(path, "r");
    if (fp == NULL) {
        logError(E_ACCESS_DENIED, "Failed to open resource bundle file: %s", strerror(errno));
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    struct stat st;
    fstat(fileno(fp), &st);

    // Check if the file is already open and cache it
    for(int i = 0; i < 256; ++i) {
        if(cache[i] == NULL) {
            strncpy(cache[i]->data->name, path, 256);
            break;
        }
    }

    // Read file in chunks and validate each section
    char* buffer = malloc(1024);
    if (buffer == NULL) {
        logError(E_INSUFFICIENT_MEMORY, "Failed to allocate memory for reading resource bundle");
        fclose(fp);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    long offset = 0;
    while(!feof(fp)) {
        size_t bytesRead = fread(buffer, 1, 1024, fp);

        // Validate and add section to list if valid
        ResourceSection* section = (ResourceSection*)buffer;
        if(validateSection(section, st.st_size, offset) == 0) {
            *tail = malloc(sizeof(SectionNode));
            (*tail)->data = section;
            (*tail)->next = NULL;
            tail = &((*tail)->next);
        } else {
            logError(E_CORRUPTED_DATA, "Invalid data in resource bundle at offset: %ld", offset);
        }

        offset += bytesRead;
    }

    free(buffer);
    fclose(fp);
    openFilesCount--;
    pthread_mutex_unlock(&mutex);
    return head;
}

// Function to validate a section
