            fprintf(stderr, "Error: Invalid file metadata for %s\n", files[i].filePath);
            continue;
        }

        pthread_mutex_lock(&configFileMutex);
        if (fwrite(&files[i], sizeof(FileInfo), 1, fp) != 1){
            perror ("Failed to write file info");
            pthread_mutex_unlock(&configFileMutex);
            return false;
        }
        pthread_mutex_unlock(&configFileMutex);

        processedFiles++;
    }

    if (fclose(fp) != 0){
        perror ("Failed to close config file");
        return false;
    }

    return true;
}
