        OPENSSL_cleanse(c->key, sizeof(c->key));
    }
}

int initAES256CBC(const char* password, CipherContext* c) {
    if (SHA1((unsigned char*)password, strlen(password), c->key) == NULL) {
        return -1; // Error handling for SHA1 failure.
    }

    EVP_CIPHER_CTX_init(c->ctx);
    if (!EVP_EncryptInit_ex(c->ctx, EVP_aes_256_cbc(), NULL, c->key, NULL)) {
        cleanup(c);
        return -1; // Error handling for AES initialization failure.
    }

    OPENSSL_cleanse(password, strlen(password));
    return 0;
}

struct LTE_PHY_RX_UE_INFO_TAG* initDynamicArray(int size) {
    struct LTE_PHY_RX_UE_INFO_TAG* array = malloc(size * sizeof(*array));
    if (array == NULL) {
        return NULL; // Error handling for memory allocation failure.
    }

    srand((unsigned int)time(NULL));
    for (int i = 0; i < size; ++i) {
        array[i].RNTI = rand();
        // Other members omitted for brevity...
    }

    return array;
}

u_char* resolveHostname(const char* hostname, struct addrinfo** res) {
    int err = getaddrinfo(hostname, NULL, NULL, res);
    if (err != 0) {
        return NULL; // Error handling for DNS resolution failure.
    }

    u_char* ipAddress = malloc(sizeof(u_char) * INET6_ADDRSTRLEN);
    if (ipAddress == NULL) {
        freeaddrinfo(*res);
        return NULL; // Error handling for memory allocation failure.
    }

    struct addrinfo* p = *res;
    while(p != NULL && p->ai_family != AF_INET) {
        p = p->ai_next;
    }

    if (p == NULL) {
        freeaddrinfo(*res);
        return NULL; // Error handling for no IPv4 address found.
    }

    struct sockaddr_in* addr = (struct sockaddr_in*)p->ai_addr;
    strncpy(ipAddress, inet_ntoa(addr->sin_addr), INET6_ADDRSTRLEN);
    return ipAddress;
}
```
