    public void processFilesInDir(File dir) throws IOException, InterruptedException {
        File[] files = dir.listFiles(); // list all the files in the directory

        for (final File file : files) {
            if (!file.isDirectory()) { 
                executor.execute(new Runnable() {
                    public void run() {
                        try {
                            long start = System.currentTimeMillis(); // start timer
                            deleteFileIfExists(file); // check and delete if exists

                            Runtime rt = Runtime.getRuntime(); 
                            Process proc = rt.exec("command", null, file.getParentFile()); 
                            BufferedReader in = new BufferedReader(new InputStreamReader(proc.getInputStream()));
                            String line;

                            while ((line = in.readLine()) != null) {
                                logMessage(LOGGING_SERVICE + "/log?msg=" + line); // send logs to external service
                            }

                            long end = System.currentTimeMillis(); // end timer
                            reportProcessingMetrics("File processed in " + (end - start) + "ms"); 
                        } catch(IOException | InterruptedException ex){
                            handleException(ex);
                        } finally {
                            proc.destroy(); // ensure process is destroyed
                            IOUtils.closeQuietly(in); // close all resources
                        }
                    }
                });
            }
        }
    }

    private void deleteFileIfExists(File file) {
