int validate(Configuration *config) {
    if (pthread_mutex_lock(&config->lock) != 0) {
        // Locking the mutex failed, another thread is probably doing this already.
        return -1;
    }

    if (*config->data_source_URL == NULL || strlen(*config->data_source_URL) == 0) {
        pthread_mutex_unlock(&config->lock);
        return INVALID_URL;
    }

    // You can add more validation checks here for the cache and callback function.

