        pthread_mutex_unlock(&config->lock);
        return INVALID_CACHE;
    }

    if (config->callback == NULL) {
        pthread_mutex_unlock(&config->lock);
        return NULL_CALLBACK;
    }

    pthread_mutex_unlock(&config->lock);
    return SUCCESS;
}
