        fprintf(stderr, "Failed to read configuration file '%s': %s\n", 
                name, config_error_text(&ctx->cfg));
        free(ctx);
        return NULL;
    }

    pthread_mutex_init(&ctx->mutex, NULL);

    return ctx;
}

bool validate_json_object(context_t *ctx, const char *appName, const char* json) {
    config_setting_t *setting = config_lookup(&ctx->cfg, appName);
    if(!setting || config_setting_type(setting) != CONFIG_TYPE_GROUP) {
        fprintf(stderr, "Invalid application context: %s\n", appName);
        return false;
    }

    pthread_mutex_lock(&ctx->mutex);

    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        pthread_mutex_unlock(&ctx->mutex);
        return false;
    }

    // Implement the actual validation logic here...

    json_decref(root);
    pthread_mutex_unlock(&ctx->mutex);
    return true;
}
