```csharp
using System;
using System.Security.Cryptography;
using System.IO;
using System.Text;
using System.Threading;

public class DecryptionService
{
    private readonly SymmetricAlgorithm _aes;
    private byte[] _key;
    private byte[] _iv;
    private PaddingMode _padding = PaddingMode.PKCS7;

    public DecryptionService(byte[] key, byte[] iv)
    {
        if (key == null || key.Length <= 0)
            throw new ArgumentNullException("Key cannot be empty.");

        if (iv == null || iv.Length != _aes.BlockSize / 8)
            throw new CryptographicException("Invalid IV length");

        _key = key;
        _iv = iv;
        _aes = Aes.Create();
    }

    public byte[] Decrypt(byte[] cipherText, byte[] hmacKey, int hmacErrorMargin)
    {
        if (cipherText == null || cipherText.Length <= 0)
            throw new ArgumentNullException("Ciphertext cannot be empty.");

        using (var decryptor = _aes.CreateDecryptor(_key, _iv))
        using (MemoryStream msDecrypt = new MemoryStream(cipherText))
        {
            try
            {
                CryptographicOperations.TransformFinalBlock(msDecrypt, decryptor);
            }
            catch (CryptographicException)
            {
                Console.WriteLine("Decryption failed.");
            }

            byte[] plainText = msDecrypt.ToArray();
            if (!IsHMACValid(plainText, hmacKey, hmacErrorMargin))
            {
                throw new CryptographicException("Invalid HMAC");
            }

            return plainText;
        }
    }

    private bool IsHMACValid(byte[] ciphertext, byte[] key, int margin)
    {
        using (var hmac = new HMACSHA256(key))
        {
            var hash = hmac.ComputeHash(ciphertext);
            return IsWithinMargin(hash, margin);
        }
    }

    private bool IsWithinMargin(byte[] hash1, int margin)
    {
        // calculate the difference between the hashes
        int diff = 0;
        for (int i = 0; i < hash1.Length; i++)
            diff += Math.Abs(hash1[i]);

        return diff <= margin;
    }

    public void SetPaddingMode(string paddingScheme)
    {
        switch (paddingScheme)
        {
            case "PKCS7": 
                _aes.Padding = PaddingMode.PKCS7;
                break;
            case "Zero": 
                _aes.Padding = PaddingMode.Zeros;
                break;
            default: 
                Console.WriteLine("Invalid padding scheme. Defaulting to PKCS7.");
                _aes.Padding = PaddingMode.PKCS7;
                break;
        }
    }
}
```

