    public static String deserializeAndModifyFilename(byte[] data, String filename, Class<?> clazz, BiFunction<Object, Integer, String> generator) throws RuntimeException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data); ObjectInputStream in = new ObjectInputStream(bais)) {
