        pthread_mutex_unlock(&context.mutex);
        return NULL;
    }

    new_ue->UE_ID = UE_ID;
    new_ue->mutex = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;

    context.UEs[context.UE_count++] = new_ue;

    pthread_mutex_unlock(&context.mutex);

    return NULL;
}

void cleanup() {
    for (int i = 0; i < context.UE_count; ++i) {
        free(context.UEs[i]);
    }
}
