['Here is a simple implementation of such a function in C:

```c
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <stdio.h>
#include <time.h>

#define LOG_SIZE 1024 * 1024 // 1MB
#define ROTATIONS 5

int execute_command(char *command) {
    pid_t pid;
    int status = 0, timeout = FALSE;
    time_t start, end;

    signal(SIGTERM, SIG_IGN); // Ignore SIGTERM in child process
    signal(SIGINT, SIG_IGN);  // Ignore SIGINT in child process

    if ((pid = fork()) < 0) {
        perror("fork");
        return -1;
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, NULL);
        _exit(EXIT_FAILURE);  // exec never returns
    }

    start = time(NULL);

    do {
        if (waitpid(pid, &status, WNOHANG) == pid) {
            break;
        }

        end = time(NULL);

        // Check timeout after waitpid() for more accurate timeout handling
        if ((end - start) >= TIMEOUT_SEC) {
            kill(pid, SIGKILL);
            return -2;  // Return error code for timeout
        }
    } while (!WIFEXITED(status) && !WIFSIGNALED(status));

    return WEXITSTATUS(status);
}
```
This function spawns a child process to execute the given command, and then uses `waitpid()` with the `WNOHANG` flag to wait for the child process to terminate without blocking. If the child process does not terminate within the specified timeout (in seconds), it sends a SIGKILL signal to terminate it, and returns an error code (-2).

Please note that this is a simplified version of the function, and it doesn't include features like log rotation and handling race conditions. Also, this example uses `execl` system call to execute the command in the child process. If the user input is not properly sanitized before passing to this function, it could lead to security issues (like shell injection). Therefore, a more complete version of the function would include proper error checking and handling, signal management, log rotation, and race condition prevention, among other things.
