    char *in_filename = NULL;
    char *out_filename = NULL;
    int case_sensitive = 0;
    while ((opt = getopt(argc, argv, "cs:o:")) != -1) {
        switch (opt) {
            case 'c':
                case_sensitive = 1;
                break;
            case 's':
                in_filename = optarg;
                break;
            case 'o':
                out_filename = optarg;
                break;
            default: 
                usage();
                return 1;
        }
    }

    if(in_filename == NULL){
