['Here's a basic C# implementation to fulfill your requirements. This code is based on .NET Framework 4.7.2 and utilizes System.Security.Cryptography, System.Text and Newtonsoft.Json for encryption/decryption, parsing JSON and handling errors respectively.

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json.Linq;

public class OAuthResponseHandler
{
    public enum ErrorCode
    {
        Success,
        InvalidTokenType,
        InvalidExpiresIn,
        TooLongRefreshToken,
        DecryptionError
    }

    public static (string access_token, ErrorCode error) ProcessEncryptedOAuthResponse(string encryptedMessage, object key, object iv)
    {
        string decoded;

        try
        {
            // First, convert the Base64-encoded message back to bytes.
            byte[] cipherText = Convert.FromBase64String(encryptedMessage);

            // Then, attempt decryption using Triple DES in EDE3 mode with the given key and IV.
            using (TripleDES des = CreateDesWithIv(key, iv))
            {
                ICryptoTransform decryptor = des.CreateDecryptor();
                using (MemoryStream msDecrypt = new MemoryStream(cipherText))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                            // Decrypt the message.
                            decoded = srDecrypt.ReadToEnd();
                    }
                }
            }
        }
        catch (Exception)
        {
            return (null, ErrorCode.DecryptionError);
        }

        JObject parsed;
        try
        {
            // Attempt to parse the decrypted JSON.
            parsed = JObject.Parse(decoded);
        }
        catch (Exception)
        {
            return (null, ErrorCode.DecryptionError);
        }

        if (parsed["token_type"].ToString() != "Bearer")
            return (null, ErrorCode.InvalidTokenType);

        int expiresIn;
        try
        {
            // Ensure 'expires_in' is a positive integer.
            expiresIn = parsed["expires_in"].Value<int>();
            if (expiresIn <= 0)
                return (null, ErrorCode.InvalidExpiresIn);
        }
        catch (Exception)
        {
            return (null, ErrorCode.DecryptionError);
        }

        // If 'refresh_token' is present and its length exceeds 1024 characters, return an error code.
        if (parsed["refresh_token"] != null && parsed["refresh_token"].ToString().Length > 1024)
            return (null, ErrorCode.TooLongRefreshToken);

        // If all checks pass, return the access token and a success code.
        return (parsed["access_token"].ToString(), ErrorCode.Success);
    }

    private static TripleDES CreateDesWithIv(object key, object iv)
    {
        byte[] keyArray;
        if (key is string strKey)
            keyArray = Encoding.UTF8.GetBytes(strKey);
        else if (key is byte[] bytesKey)
            keyArray = bytesKey;
        else
            throw new ArgumentException("Invalid type for 'key'. Expected: string or byte[]");

        byte[] ivArray;
        if (iv is string strIv)
            ivArray = Encoding.UTF8.GetBytes(strIv);
        else if (iv is byte[] bytesIv)
            ivArray = bytesIv;
        else
            throw new ArgumentException("Invalid type for 'iv'. Expected: string or byte[]");

        return new TripleDES { Key = keyArray, IV = ivArray };
    }
}
