unsigned char* calcMD5(const char *filename) {
    int BUFSIZE = 1024;  // Adjust this size based on your needs
    FILE *inFile = fopen (filename, "rb");
    MD5_CTX mdContext;
    unsigned char *buffer;
    buffer = malloc(BUFSIZE);

    int bytes;
    unsigned char digest[16];

    if (inFile == NULL) {
        printf ("%s can't be opened.\n", filename);
        return NULL;
    }

    MD5_Init(&mdContext);
    while ((bytes = fread(buffer, 1, BUFSIZE, inFile)) != 0)
