#define MAX_CONFIG_LINE_LENGTH 1024
#define MAX_PATH_LEN 4096

typedef struct ConfigLine {
    char source[MAX_EXTENSION_LEN];
    char target[MAX_EXTENSION_LEN];
    int digitCount;
    char filter[MAX_SUBSTRING_FILTER_LEN];
} ConfigLine;

void readConfigFile(const char* path, ConfigLine** configLines, int* lineCount) {
    // This function is not shown here. It reads the config file into the ConfigLine array.
}

int renameFilesInDirectory(const char* directoryPath, const char* configFilePath) {
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir (directoryPath)) != NULL) {
        while ((ent = readdir (dir)) != NULL) {
            // Check for hidden file.
            if(ent->d_name[0] == '.'){
                continue;
            }

            char oldPath[MAX_PATH_LEN];
            snprintf(oldPath, MAX_PATH_LEN, "%s/%s", directoryPath, ent->d_name);

            // Get the extension.
            char* ext = strrchr(ent->d_name, '.');
            if (ext == NULL) {
                continue;
            }

            ConfigLine* configLines;
            int lineCount;
            readConfigFile(configFilePath, &configLines, &lineCount);

            for(int i = 0; i < lineCount; i++){
                if (strcmp(ext, configLines[i].source) == 0) {
                    // Construct new filename.
                    char newFilename[MAX_PATH_LEN];
                    snprintf(newFilename, MAX_PATH_LEN, "%s/%.*s%s", directoryPath, configLines[i].digitCount, configLines[i].filter, configLines[i].target);

                    if (rename(oldPath, newFilename) != 0) {
                        // Error handling for rename.
                        perror("Error renaming file");
                        return -1;
                    }
                }
            }

            free(configLines);
        }

        closedir (dir);
    } else {
        /* could not open directory */
        perror ("Cannot open directory.");
        return -1;
    }

    return 0;
}
```
Please note that the above code does not have any checks for concurrent access to the directory. Handling such cases would require some form of file locking or inter-process communication, which is beyond the scope of this example. To handle concurrent access, you might want to consider using a language with built-in support for concurrency (like Python) and a robust filesystem library. 

Also, remember that error checking in C can be quite verbose because we are dealing with low level APIs which often return errors via their return values instead of exceptions or other more user friendly mechanisms.
