    public async Task AddEdgeWithRandomPropertiesAsync(string id1, string id2)
    {
        try
        {
            var properties = await GenerateRandomValuesForAllRangesAsync(); // You would need to implement this method.
            await _graphManager.AddEdgeAsync(id1, id2, properties); 
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }

    public void AddFloatRangeDefinition(string rangeName, float min, float max)
    {
        _floatRanges[rangeName] = (min, max);
    }

    public void AddIntegerRangeDefinition(string rangeName, int min, int max)
    {
        _integerRanges[rangeName] = (min, max);
    }

    private async Task<Dictionary<string, object>> GenerateRandomValuesForAllRangesAsync() 
    {
        var properties = new Dictionary<string, object>();

        foreach (var range in _floatRanges)
        {
            var value = await _random.GenerateFloat(range.Value.min, range.Value.max);
            properties[range.Key] = value;
        }

        foreach (var range in _integerRanges)
        {
            var value = await _random.GenerateInteger(range.Value.min, range.Value.max);
            properties[range.Key] = value;
        }

        return properties;
    }

    public void Dispose() 
    {
        _graphManager?.Dispose();
    }
}
