['Here's an example of how you might approach this task in C using the POSIX APIs. Note that this implementation does not include error handling for brevity, but it should give a basic idea of how one could structure such a function:

```c
#include <stdio.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* dir_path;
    char* config_file_path;
    int logging_level;
} RenameContext;

void* renameFile(void *arg) {
    // This is where the actual renaming logic would go. For now, it just sleeps for a few seconds to simulate work.
    sleep(3);

    return NULL;
}

void handleDirEntry(RenameContext *ctx, struct dirent *entry) {
    if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
        // Ignore . and .. directories
        return;
    }

    pthread_t thread;
    int ret = pthread_create(&thread, NULL, renameFile, ctx);
    if (ret) {
        perror("pthread_create failed");
        return;
    }

    // Join the thread to ensure it finishes before we continue. This isn't efficient for a large directory with many files, but it keeps things simple for this example.
    pthread_join(thread, NULL);
}

void renameFilesInDirConcurrently(RenameContext *ctx) {
    DIR *dir = opendir(ctx->dir_path);
    if (!dir) {
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        handleDirEntry(ctx, entry);
    }

    closedir(dir);
}
``` 
This is a high-level example. It doesn't include parsing the configuration file, retry mechanism for atomic file operations, handling files with no extension or exceeding the system's maximum length, hidden files, symbolic links and files owned by other users etc. You need to implement these features according to your needs.
