pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;
LTE_UE_context *head = NULL;

int add_to_list(const char* UE_ID) {
    pthread_mutex_lock(&listLock);

    LTE_UE_context *newNode = malloc(sizeof(LTE_UE_context));
    if (!newNode) {
        return -1; // memory allocation error
    }
    strncpy(newNode->UE_ID, UE_ID, MAX_URL_LEN);

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&listLock);
    return 0; // success
}

void cleanup() {
    LTE_UE_context *current = head, *tmp;

    while (current) {
        tmp = current->next;
        free(current);
        current = tmp;
    }

    pthread_mutex_destroy(&listLock);
}
