#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int UE_ID;
    // MAC entities and PDCP statistics...
} LTEUEContext;

typedef struct {
    pthread_mutex_t lock;
    size_t numUEContexts;
    size_t maxUEContexts;
    LTEUEContext* UEContextArray;
} LTEManager;

void initLTEManager(LTEManager *manager) {
    manager->numUEContexts = 0;
    manager->maxUEContexts = 10;  // Start with a reasonable default.
    manager->UEContextArray = malloc(sizeof(LTEUEContext) * manager->maxUEContexts);
    pthread_mutex_init(&manager->lock, NULL);
}

void addUEContext(LTEManager *manager, LTEUEContext context) {
    pthread_mutex_lock(&manager->lock);

    if (manager->numUEContexts == manager->maxUEContexts) {
        manager->maxUEContexts *= 2;
        manager->UEContextArray = realloc(manager->UEContextArray, sizeof(LTEUEContext) * manager->maxUEContexts);
    }

    manager->UEContextArray[manager->numUEContexts++] = context;

    pthread_mutex_unlock(&manager->lock);
}

void cleanupManager(LTEManager *manager) {
    free(manager->UEContextArray);
}
```
In this code, we use a dynamic array to store the LTE UE contexts. The `addUEContext` function ensures thread safety by locking the mutex before accessing or modifying the array. If the array is full, it doubles its size to ensure there's always enough space for new entries.

The `cleanupManager` function should be called at program termination to free the allocated memory and clean up resources. 

