["Here's an example solution in C using pthreads for thread safety and a simple hash map implementation for efficient management of UEs:

```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    // PDCP statistics here
} PDCP_stats;

typedef struct {
    int UE_ID;
    pthread_mutex_t lock;
    char **MAC_entities;  // list of MAC entities
    size_t num_macs;
    PDCP_stats stats;
} UE_context;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    UE_context **ue_array;  // array of UE contexts
} UE_manager;

UE_manager *create_manager(size_t max_ues) {
    UE_manager *mgr = malloc(sizeof(UE_manager));
    if (!mgr) return NULL;

    mgr->ue_array = calloc(max_ues, sizeof(UE_context*));
    if (!mgr->ue_array) {
        free(mgr);
        return NULL;
    }

    mgr->capacity = max_ues;
    mgr->count = 0;
    pthread_mutex_init(&mgr->lock, NULL);

    return mgr;
}

int add_UE(UE_manager *mgr, int UE_ID) {
    if (!mgr || mgr->count >= mgr->capacity) return -1;  // manager full

    pthread_mutex_lock(&mgr->lock);

    for (size_t i = 0; i < mgr->count; ++i) {
        if (mgr->ue_array[i]->UE_ID == UE_ID) {  // UE already exists
            pthread_mutex_unlock(&mgr->lock);
            return -2;
        }
    }

    mgr->ue_array[mgr->count] = calloc(1, sizeof(UE_context));
    if (!mgr->ue_array[mgr->count]) {
        pthread_mutex_unlock(&mgr->lock);
        return -3;  // allocation failed
    }

    mgr->ue_array[mgr->count]->UE_ID = UE_ID;
    pthread_mutex_init(&mgr->ue_array[mgr->count]->lock, NULL);
    ++mgr->count;

    pthread_mutex_unlock(&mgr->lock);
    return 0;  // UE added successfully
}

int add_MAC(UE_manager *mgr, int UE_ID, char* MAC) {
    if (!mgr || !MAC) return -1;  // NULL input

    for (size_t i = 0; i < mgr->count; ++i) {
        if (mgr->ue_array[i]->UE_ID == UE_ID) {  // found UE
            pthread_mutex_lock(&mgr->ue_array[i]->lock);

            mgr->ue_array[i]->MAC_entities = realloc(mgr->ue_array[i]->MAC_entities, 
                (mgr->ue_array[i]->num_macs + 1) * sizeof(char*));
            if (!mgr->ue_array[i]->MAC_entities) {
                pthread_mutex_unlock(&mgr->ue_array[i]->lock);
                return -2;  // allocation failed
            }

            mgr->ue_array[i]->MAC_entities[mgr->ue_array[i]->num_macs] = strdup(MAC);
            ++mgr->ue_array[i]->num_macs;

            pthread_mutex_unlock(&mgr->ue_array[i]->lock);
            return 0;  // MAC added successfully
        }
    }

    return -3;  // UE not found
}

// Add other functions for updating PDCP stats and periodically updating them based on thresholds

void cleanup_manager(UE_manager *mgr) {
    if (!mgr) return;

    pthread_mutex_lock(&mgr->lock);

    for (size_t i = 0; i < mgr->count; ++i) {
        pthread_mutex_destroy(&mgr->ue_array[i]->lock);

        // Free MAC entities and stats here
        free(mgr->ue_array[i]);
    }

    free(mgr->ue_array);
    pthread_mutex_unlock(&mgr->lock);
    pthread_mutex_destroy(&mgr->lock);
    free(mgr);
}
```
Please note that error checking and handling of return values are not provided in the above example code. It's crucial to handle errors properly in a real application. This sample demonstrates how to manage dynamic memory allocation for UEs and MAC entities, as well as thread safety with pthread mutexes, but does not include PDCP statistics updating or any periodic tasks.
