    LTE_DL_FRAME_MSG* messages;
    size_t capacity;
    size_t size;
} Array;

int initArray(Array* arr) {
    if (arr == NULL) return -1; // invalid input.

    arr->messages = malloc(INITIAL_CAPACITY * sizeof(LTE_DL_FRAME_MSG));
    if (arr->messages == NULL) return -2; // memory allocation failed.

    arr->capacity = INITIAL_CAPACITY;
    arr->size = 0;

    return 0; // success.
}

int addMessage(Array* arr, int UE_ID, char* CCCH_MESSAGE) {
    if (arr == NULL || CCCH_MESSAGE == NULL) return -1; // invalid input.

    if (arr->size >= MAX_CAPACITY) return -2; // capacity exceeded.

    if (arr->size >= arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        LTE_DL_FRAME_MSG* newMessages = realloc(arr->messages, newCapacity * sizeof(LTE_DL_FRAME_MSG));
        if (newMessages == NULL) return -3; // memory reallocation failed.

        arr->messages = newMessages;
        arr->capacity = newCapacity;
    }

    arr->messages[arr->size].UE_ID = UE_ID;
    arr->messages[arr->size].CCCH_MESSAGE = CCCH_MESSAGE; // assumes you want to share the pointer.
    ++(arr->size);

    return 0; // success.
}
```

Please note that `realloc` does not guarantee that it will succeed, and may return NULL if there is insufficient memory available. It would be better to have a mechanism for handling memory allocation failures (like checking the return value of realloc before assigning it to your array) or use a custom allocator that can handle such cases.
