    if (cur == NULL || xmlStrcmp(cur->name, "algorithms")) { // Check root element's name
        xmlFreeDoc(doc); 
        return NULL;
    }

    for (cur = cur->xmlChildrenNode; cur != NULL; cur = cur->next) {
        if (!xmlStrcmp(cur->name, "algorithm")) count++; // Count the number of algorithms
    }

    Algorithm** algos = malloc(count * sizeof(Algorithm*)); // Allocate array to hold algorithm structs

    for (cur = cur->xmlChildrenNode; cur != NULL; cur = cur->next) {
        if (!xmlStrcmp(cur->name, "algorithm")) {
            algos[i] = malloc(sizeof(Algorithm)); // Allocate memory for each algorithm struct
            xmlChar* algo_name = xmlGetProp(cur, "name"); // Get the name of the algorithm
            algos[i]->name = strdup((char*)algo_name);
