        if (!handle) {
            /* Handle error - cannot load the driver */
            continue;
        }

        /* Perform runtime checks for the availability of each database driver */
        void* (*connectionPoolImpl)(DriverContext*) = loadAndGetFunction(handle, "connectionPoolImpl");

        if (connectionPoolImpl != NULL) { // If a function is found.
