void initialize() {
    queue.data = malloc(sizeof(LTE_PHY_RX_UE_INFO_TAG) * 10000);
    queue.size = 0;
    queue.capacity = 10000;
    pthread_mutex_init(&queue.mutex, NULL);
}

void add(LTE_PHY_RX_UE_INFO_TAG item) {
    if (queue.size == queue.capacity) {
        errorCode = -1; //Queue is full
        return;
    }
    pthread_mutex_lock(&queue.mutex);
    memcpy(&queue.data[queue.size++], &item, sizeof(LTE_PHY_RX_UE_INFO_TAG));
    pthread_mutex_unlock(&queue.mutex);
}

LTE_PHY_RX_UE_INFO_TAG remove() {
    if (queue.size == 0) {
        errorCode = -2; //Queue is empty
        return NULL;
    }
    pthread_mutex_lock(&queue.mutex);
    LTE_PHY_RX_UE_INFO_TAG item = queue.data[--queue.size];
    pthread_mutex_unlock(&queue.mutex);
    return item;
}

void cleanup() {
    free(queue.data);
    pthread_mutex_destroy(&queue.mutex);
}

