void addToListIfAvailable(char* name, void* (*driver_function)(DriverContext *ctx), DriverContext* ctx) {
    if (checkHardwareAvailability(name, driver_function, ctx)) {
        pthread_mutex_lock(&listMutex);

        // Create a new node and assign values.
        DriverNode* newNode = malloc(sizeof(DriverNode));
        newNode->name = name;
        newNode->driver_function = driver_function;
        newNode->ctx = ctx;
