        if (driverList == NULL) {
            driverList = newNode;  // If list is empty, set as head of list.
        } else {
            DriverNode* current = driverList;

            // Iterate to end of linked list.
            while(current->next != NULL){
                current = current->next;
            }

            current->next = newNode;  // Add node at the end.
        }

        pthread_mutex_unlock(&listMutex);
    } else {
        printf("Hardware not available: %s\n", name);
    }
}
