pthread_mutex_t bufferLock = PTHREAD_MUTEX_INITIALIZER;
TCP_CONNECTION_INFO* buffer[1000] = { NULL };
int bufferCount = 0;

void addToBuffer(TCP_CONNECTION_INFO *info) {
    pthread_mutex_lock(&bufferLock); 

    // Check for uniqueness
    for (int i = 0; i < bufferCount; ++i) {
        if (buffer[i]->CONN_ID == info->CONN_ID) {
            printf("Error: Duplicate CONN_ID\n"); 
            pthread_mutex_unlock(&bufferLock); 
            return;
        }
    }

    // Add to buffer
    if (bufferCount < 1000) {
        buffer[bufferCount++] = info;  
    } else {
        printf("Error: Buffer full\n"); 
    }

    pthread_mutex_unlock(&bufferLock); 
}

TCP_CONNECTION_INFO* removeFromBuffer() {
    TCP_CONNECTION_INFO *info = NULL;
    pthread_mutex_lock(&bufferLock); 
    if (bufferCount > 0) {
        info = buffer[--bufferCount];  
        buffer[bufferCount] = NULL; 
    } else {
        printf("Error: Buffer empty\n"); 
    }
    pthread_mutex_unlock(&bufferLock); 
    return info; 
}

EVP_MD_CTX* initHMAC(const char *password) {
    EVP_MD_CTX *mdctx = NULL; 

    // Create and initialize the context
    mdctx = EVP_MD_CTX_new(); 
    if (EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL) != 1) {
        printf("Error: Unable to init HMAC\n"); 
        return NULL; 
    }

    // Set key length and derive key
    if (EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL) != 1 || 
        EVP_DigestUpdate(mdctx, password, strlen(password)) != 1) {
        printf("Error: Unable to set HMAC key\n"); 
        return NULL; 
    }

    // Enable the context
    if (EVP_MD_CTX_set_flags(mdctx, EVP_MD_CTX_FLAG_ONESHOT) != 1) {
        printf("Error: Unable to enable HMAC\n"); 
        return NULL; 
    }

    return mdctx; 
}

void cleanup(EVP_MD_CTX *mdctx) {
    EVP_CIPHER_CTX_cleanup(mdctx); 
    EVP_MD_CTX_free(mdctx); 
}

u_char* resolveDNS(const char *hostname, int *errorCode) {
