    if ((hp = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        *errorCode = 1;  
        return NULL;
    }

    u_char* addr = (u_char *)malloc(hp->h_length); 
    memcpy(addr, hp->h_addr, hp->h_length);
    *errorCode = 0;  
    return addr; 
}
