HMAC_CTX *initialize_HMAC(const char* password) {
    EVP_MD_CTX* mdctx;
    HMAC_CTX* ctx = HMAC_CTX_new();
    unsigned int len = 0;
    unsigned char key[EVP_MAX_MD_SIZE] = {0};
    const EVP_MD *md = EVP_sha256();

    // Generate HMAC Key using SHA-256 hash of password
    mdctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(mdctx, md, NULL);
    EVP_DigestUpdate(mdctx, (const void*)password, strlen(password));
