#include <netdb.h>
int resolve_hostname(const char* hostname, u_char* ip) {
    struct addrinfo hints, *res;
    int errcode;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = PF_UNSPEC;  // use IPv4 or IPv6, whichever
    hints.ai_socktype = SOCK_STREAM;

    errcode = getaddrinfo(hostname , "http" , &hints , &res);
    if (errcode != 0) {
        return -1;  // Resolution Failed
    }

    memcpy(ip, &((struct sockaddr_in *)res->ai_addr)->sin_addr, sizeof(u_char));
    freeaddrinfo(res);
    return 0;  // Resolution Successful
}
