        }
        catch (Exception ex)
        {
            _logger.LogError("DNS resolution error: " + ex.Message);
            throw;
        }
    }

    public void Dispose()
    {
        if(_aesAlgorithm != null)
        {
            ((IDisposable)_aesAlgorithm).Dispose();
        }
    }
}
