// Define the struct for storing thread arguments
typedef struct {
    char *source_dir;
    char *output_dir;
    char **file_names;
    int num_files;
} thread_arg_t;

void *convert(void *arguments) {
    // Extract the thread arguments
    thread_arg_t *args = (thread_arg_t *) arguments;

    for (int i = 0; i < args->num_files; ++i) {
        char source[1024];
        sprintf(source, "%s/%s", args->source_dir, args->file_names[i]);

        // Open the image file for reading
        FILE *infile = fopen(source, "rb");
        if (infile == NULL) {
            printf("Could not open input file %s\n", source);
            return NULL;
        }

        // Create a new JPEG decompress object and initialize it with the input image file
        struct jpeg_decompress_struct cinfo;
        struct jpeg_error_mgr jerr;
        cinfo.err = jpeg_std_error(&jerr);
        jpeg_create_decompress(&cinfo);
        jpeg_stdio_src(&cinfo, infile);

        // Read the image header and start the decompression process
        jpeg_read_header(&cinfo, TRUE);
        jpeg_start_decompress(&cinfo);

        int row_stride = cinfo.output_width * cinfo.output_components;
        JSAMPARRAY buffer = (*cinfo.mem->alloc_sarray) ((j_common_ptr) &cinfo, JPOOL_IMAGE, row_stride, 1);

        // Create a new PDF file for output
        char destination[1024];
        sprintf(destination, "%s/%s.pdf", args->output_dir, args->file_names[i]);
        FILE *outfile = fopen(destination, "wb");

        // Write the decompressed image data to the PDF file
        while (cinfo.output_scanline < cinfo.output_height) {
            jpeg_read_scanlines(&cinfo, buffer, 1);

            // TODO: Add code here for writing the scanline data to the PDF file
        }

        // Clean up and close all resources
        jpeg_finish_decompress(&cinfo);
        jpeg_destroy_decompress(&cinfo);
        fclose(infile);
        fclose(outfile);
    }

    return NULL;
}

void process_files(char *source_dir, char **file_names, int num_files, char *output_dir) {
    // Create a thread attribute object for setting the joinable state
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    // Initialize an array of threads and thread arguments
    int num_threads = sysconf(_SC_NPROCESSORS_ONLN);  // Use number of available cores as default
    pthread_t threads[num_threads];
    thread_arg_t thread_args[num_files / num_threads + 1];

    // Create and start each thread
    for (int i = 0; i < num_threads && i * num_files / num_threads < num_files; ++i) {
        // Initialize the argument struct with necessary data
        thread_args[i].source_dir = source_dir;
        thread_args[i].output_dir = output_dir;
        thread_args[i].file_names = file_names + i * num_files / num_threads;
        thread_args[i].num_files = (i + 1) * num_files / num_threads - i * num_files / num_threads;

        // Create and start the thread
        int rc = pthread_create(&threads[i], &attr, convert, (void *)&thread_args[i]);
        if (rc) {
            printf("Error creating thread\n");
            return;
        }
    }

    // Wait for all threads to complete their execution
    void *status;
    for (int i = 0; i < num_threads && i * num_files / num_threads < num_files; ++i) {
        int rc = pthread_join(threads[i], &status);
        if (rc) {
            printf("Error joining thread\n");
            return;
        }
    }

    // Clean up and exit
    pthread_attr_destroy(&attr);
    pthread_exit(NULL);
}
```

