static void* workerThread(gpointer data) {
    ImageToPdfArgs* args = (ImageToPdfArgs*)data;

    g_mutex_lock(&args->loggingMutex);
    // Log process start for this thread
    g_mutex_unlock(&args->loggingMutex);

    GList* node = g_list_first(args->file_names);
    while (node) {
        char* imagePath = g_strjoin("/", args->source_directory, node->data, NULL);
