            // Log error if converting fails for this image file
        }

        g_free(imagePath);
        g_free(pdfPath);
        node = g_list_next(node);
    }

    g_mutex_lock(&args->loggingMutex);
    // Log process end for this thread
    g_mutex_unlock(&args->loggingMutex);
}

void convertImagesToPDF(char* sourceDirectory, GList* fileNames, char* outputDirectory, char* toolPath) {
    ImageToPdfArgs args = {sourceDirectory, fileNames, outputDirectory, toolPath, PTHREAD_MUTEX_INITIALIZER};

    // Log process start for all threads

    GList* node = g_list_first(fileNames);
    int threadCount = 0;
    while (node) {
        pthread_t thread;
        ++threadCount;
        if (pthread_create(&thread, NULL, workerThread, &args)) {
            // Log error if creating a new thread fails
        } else {
            pthread_detach(thread); // Let the threads run independently
        }
    }

    while (threadCount > 0) {
        sleep(1); // Wait for all threads to finish

        g_mutex_lock(&args->loggingMutex);
        // Check if any thread has finished, update threadCount if needed
        g_mutex_unlock(&args->loggingMutex);
    }

    // Log process end for all threads
}
