            Thread.sleep(delay);

            // start the service
            ProcessBuilder processBuilder = new ProcessBuilder("service", "start");
            Process process = processBuilder.start();

            // stop and send message to monitoring system
            processBuilder = new ProcessBuilder("service", "stop");
