            System.out.println(e.getMessage());
            return;
        }

        String model = getModel(device);
        ArrayList<String> interfaces = getInterfaces(device);

        try{
            Path path = Paths.get("template_config.txt");
            byte[] data = Files.readAllBytes(path);

            for (Map.Entry<String, String> entry : parameters.entrySet()) {
                if(!parameters.containsKey(entry.getValue())){
                    System.out.println("Missing parameter: " + entry.getKey());
                    return;
                }

                data = new String(data).replaceAll(entry.getKey(), entry.getValue()).getBytes();
