            Date date = new Date() ;
            SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss") ;
            String currentTime = dateFormat.format(date);
            data = (new String(data) + "\n" + "Last Modified Time: "+currentTime+", Device Model: "+model).getBytes();

