using System;
using System.Threading;
using System.Collections.Generic;
using System.Diagnostics;
using System.Text;

public class DynamicMultiDimensionalValueGenerator
{
    private object lockObject = new object(); // Ensures thread safety.
    private Random rand = new Random(); // For generating random values.

    // Storing dimension boundaries for all dimensions in a dictionary, where the key is the dimension index and value is an array with inclusive bounds.
    private Dictionary<int, int[]> boundaries = new Dictionary<int, int[]>(); 

    public void UpdateBoundary(int dimensionIndex, int lowerBound, int upperBound)
    {
        lock (lockObject) // Ensuring thread safety.
        {
            if (!boundaries.ContainsKey(dimensionIndex)) boundaries[dimensionIndex] = new int[2];
            boundaries[dimensionIndex][0] = lowerBound;
            boundaries[dimensionIndex][1] = upperBound;
        }
    }

    public int[] GetRandomVector(int dimensionCount)
    {
        var vector = new int[dimensionCount];

        for (var i = 0; i < dimensionCount; i++)
        {
            lock (lockObject) // Ensuring thread safety.
            {
                if (!boundaries.ContainsKey(i)) boundaries[i] = new int[] {int.MinValue, int.MaxValue}; 
                var lowerBound = boundaries[i][0];
                var upperBound = boundaries[i][1];

                vector[i] = rand.Next(lowerBound, upperBound); // Generating random value within the boundary for each dimension.
            }
        }

        return vector;
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        foreach (var entry in boundaries)
        {
            sb.AppendLine($"Dimension {entry.Key}: [{entry.Value[0]}, {entry.Value[1]}]"); // Converting boundaries to string representation.
        }

