    MAC_Entity* MACEntities;
    int numMACs;
    pthread_mutex_t lock;
    PDCP_Statistics stats;
    struct UEContext *next;
} UEContext;

pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;
UEContext* head = NULL;  // Global linked list of UE contexts
int totalPDCPUpdates = 0;

void *updatePDCPStats(void *args) {
    int frequency = *((int *) args);

    while (1) {
        sleep(frequency);

        pthread_mutex_lock(&globalLock);

        UEContext* tempUECtx = head;
        while (tempUECtx != NULL) {
            // Update PDCP statistics for each UE context

            totalPDCPUpdates++;
            tempUECtx->stats.totalUpdates += 1;
            pthread_mutex_unlock(&globalLock);  // release lock to allow other threads to update PDCPs
        }
    }
}

int addMACEntity(char* MAC, int UEID) {
    pthread_mutex_lock(&globalLock);

    UEContext* tempUECtx = head;
    while (tempUECtx != NULL) {
        if (tempUECtx->UEID == UEID) {
            // Add MAC entity to this UE context

            pthread_mutex_unlock(&globalLock);  // release lock to allow other threads to update PDCPs
            return 1;
        }

        tempUECtx = tempUECtx->next;
    }

    pthread_mutex_unlock(&globalLock);  // release lock if UE not found
    return -1;
}

// Function to add a new UE context
void addUEContext(int UEID) {
    UEContext* newNode = (UEContext*)malloc(sizeof(UEContext));

    if (newNode == NULL) {
        // Handle memory allocation failure here, e.g., by exiting the program with an error message
        exit(-1);
    }

    newNode->UEID = UEID;
    pthread_mutex_init(&(newNode->lock), NULL);

    // Add to linked list of UE contexts
    pthread_mutex_lock(&globalLock);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&globalLock);
}

// Function to free memory when a UE context is no longer needed
void removeUEContext(int UEID) {
    pthread_mutex_lock(&globalLock);

    UEContext* temp = head;
    UEContext* prev = NULL;

    while (temp != NULL && temp->UEID != UEID) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;  // UE context not found, do nothing

    // Remove from linked list of UE contexts
    if (prev != NULL) {
        prev->next = temp->next;
    } else {
        head = temp->next;
    }

    free(temp);  // Free the memory allocated for this UE context

    pthread_mutex_unlock(&globalLock);
}
```
