#define BUFFER_SIZE 256

typedef struct {
    char *filename;
    int lineCount;
} Arguments;

void* processFile(void* args) {
    Arguments *a = (Arguments*)args;
    FILE *file = fopen(a->filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", a->filename);
        return NULL;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        // Comment lines that start with "//" are ignored
        if (strncmp(buffer, "//", 2) != 0) a->lineCount++;
    }

    fclose(file);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: ./program [options] input_files\n");
        return 0;
    }

    int numFiles = argc - 1, i;
    pthread_t *threads = malloc(numFiles * sizeof(pthread_t));
    Arguments *args = malloc(numFiles * sizeof(Arguments));

    for (i = 0; i < numFiles; ++i) {
        args[i].filename = argv[i + 1];
        args[i].lineCount = 0;

        pthread_create(&threads[i], NULL, processFile, &args[i]);
    }

    for (i = 0; i < numFiles; ++i) {
        pthread_join(threads[i], NULL);
        printf("File: %s has %d lines\n", args[i].filename, args[i].lineCount);
    }

    free(args);
    free(threads);
    return 0;
}
```
Please note that in this code, each file is processed by a separate thread. Each thread reads the file line by line and increments a counter for every non-commented line it finds. The main process then waits for all threads to finish their work before reporting back their results. 

