void renameFiles(char* dirPath, char* configFile) {
    FILE *file = fopen (configFile, "r");
    if (file == NULL){
        printf("Couldn't open %s: %d\n", configFile, errno);
        return;
    }
    // Process the config file to create a list of valid extensions. This could be as simple as reading lines and storing them in an array or it could involve parsing JSON/XML if more complex configs are needed.

    DIR *dir = opendir(dirPath);
    if (dir == NULL) {
        printf("Couldn't open %s: %d\n", dirPath, errno);
        fclose(file);
        return;
    }
    struct dirent *entry;
    int fileCount = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp (entry->d_name, ".") == 0 || strcmp (entry->d_name, "..") == 0) continue; // Ignore the current and parent directories.

        char oldName[256] = "";
        sprintf(oldName, "%s/%s", dirPath, entry->d_name);

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char newFileName[512];
        strcpy(newFileName, "");
        char *token = strtok(entry->d_name, "_.");  // Extract the first word from filename
        if (token != NULL) {
            sprintf(newFileName, "%s_%ld_%05d", token, t, fileCount); // Append timestamp and sequential number.
        }

        char *extension = strrchr(entry->d_name, '.'); // Get the extension from filename
        if (extension != NULL) {
            for (char **validExt = validExtensions; *validExt != NULL; ++validExt) {  // Check if this is a valid extension from our config.
                if(strcmp(extension, *validExt) == 0) {
                    strcat(newFileName, extension);
                    break;
                }
            }
        } else { // If the original file doesn't have an extension, use the first valid one in our list for it.
            strcat(newFileName, validExtensions[0]);
        }

        char newPath[512];
        sprintf(newPath, "%s/%s", dirPath, newFileName); 

        if (rename(oldName, newPath) != 0){ // If renaming fails
            printf("Renaming %s to %s failed: %d\n", oldName, newPath, errno);
            ++fileCount;
            continue;
        }

        printf("%s was successfully renamed to %s\n", entry->d_name, newFileName);
        ++fileCount;
    }

    closedir(dir);
    fclose(file);
}
