void suspend_ue_context(int UE_ID) {
    pthread_mutex_lock(&global_lock);

    for (int i = 0; i < ue_count; ++i) {
        if (ue_contexts[i]->UE_ID == UE_ID) {
            pthread_mutex_lock(&ue_contexts[i]->lock);

            // Suspend the UE context here

            pthread_mutex_unlock(&ue_contexts[i]->lock);
        }
    }

    pthread_mutex_unlock(&global_lock);
}

void add_ue(int UE_ID) {
    if (ue_count == ue_capacity) {
        ue_contexts = realloc(ue_contexts, sizeof(*ue_contexts) * (ue_capacity + 10));

        if (!ue_contexts)
            exit(-1); // Handle out of memory error

        for (int i = 0; i < 10; ++i) {
