                exit(-1); // Handle out of memory error

            memset(ue_contexts[ue_capacity + i], 0, sizeof(*ue_contexts));
        }

        ue_capacity += 10;
    }

    pthread_mutex_init(&ue_contexts[ue_count]->lock, NULL);

