```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    int Dev_ID;
    char** sensorEntities;
    double connectivityStats[2];
    pthread_mutex_t lock;
} DeviceContext;

DeviceContext* deviceArray = NULL;
int arraySize = 0;
pthread_mutex_t resizeLock;

void initDevice(DeviceContext *device, int id) {
    device->Dev_ID = id;
    device->sensorEntities = calloc(1, sizeof(char*));
    if (device->sensorEntities == NULL) {
        perror("Error in memory allocation");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&device->lock, NULL);
}

void addDeviceContext() {
    DeviceContext *newArray = calloc(arraySize + 1, sizeof(DeviceContext));
    if (newArray == NULL) {
        perror("Error in memory allocation");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < arraySize; ++i) {
        newArray[i] = deviceArray[i];
    }

    initDevice(&newArray[arraySize], arraySize + 1);
    ++arraySize;

    pthread_mutex_lock(&resizeLock);
    free(deviceArray);
    deviceArray = newArray;
    pthread_mutex_unlock(&resizeLock);
}

void addSensorEntity(int devID, char* sensor) {
    DeviceContext *dev = &deviceArray[devID - 1];

    pthread_mutex_lock(&dev->lock);
    // Add sensor entity to the list of associated sensors
    int numEntities = 0;
    while (dev->sensorEntities[numEntities] != NULL) ++numEntities;
    ++numEntities;

    char** newArray = realloc(dev->sensorEntities, sizeof(char*) * (numEntities + 1));
    if (newArray == NULL) {
        perror("Error in memory allocation");
        exit(EXIT_FAILURE);
    }

    dev->sensorEntities = newArray;
    dev->sensorEntities[numEntities - 1] = sensor;
    dev->sensorEntities[numEntities] = NULL;

    pthread_mutex_unlock(&dev->lock);
}

void updateConnectivityStats(int devID, double latency, double throughput) {
    DeviceContext *dev = &deviceArray[devID - 1];

    pthread_mutex_lock(&dev->lock);
    // Update network connectivity statistics
    dev->connectivityStats[0] = latency;
    dev->connectivityStats[1] = throughput;
    pthread_mutex_unlock(&dev->lock);
}

void freeResources() {
    for (int i = 0; i < arraySize; ++i) {
        DeviceContext *device = &deviceArray[i];
        pthread_mutex_destroy(&device->lock);

        for(int j=0; device->sensorEntities[j] != NULL; j++){
            free(device->sensorEntities[j]);
        }

        free(device->sensorEntities);
    }

    free(deviceArray);
}
```
