void modify_metadata(const char *filename) {
    struct stat sb;
    if (stat(filename, &sb) == -1) {
        perror("stat");
        return;
    }

    time_t t = sb.st_mtime;
    struct tm *tm = localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm);

    const char *ext = strrchr(filename, '.');
    if (ext == NULL) ext = "";  // If no extension, then consider it as empty string.

    size_t baseLen = ext - filename;  // Calculate the length of the base name.
    size_t newNameLength = baseLen + 16;  // Add space for version number and timestamp.

    char newFilename[newNameLength + 1];  // Allocate space for the new filename.
    snprintf(newFilename, newNameLength+1, "%.*s_v%ld_t%s%s", (int)baseLen, filename, sb.st_mtime, timestamp, ext);

    if (rename(filename, newFilename) != 0) {
        perror("rename");
    }
}
