#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Forward declarations
typedef struct DeviceDriverNode DeviceDriverNode;
typedef struct DriverContext DriverContext;

struct DriverContext {
    // Parameters for driver initialization go here
};

struct DeviceDriverNode {
    char *deviceName;
    int (*driverFunction)(DriverContext *); // Function pointer to the driver implementation
    DriverContext context;
    DeviceDriverNode *next;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
DeviceDriverNode *head = NULL;

void registerDriver(char *deviceName, int (*driverFunction)(DriverContext *), DriverContext context) {
    // Dynamically allocate memory for new node
    DeviceDriverNode *newNode = malloc(sizeof(DeviceDriverNode));

    if (!newNode) {
        return;
    }

    // Copy device name into allocated memory
    newNode->deviceName = strdup(deviceName);

    // Assign function pointer and context to node fields
    newNode->driverFunction = driverFunction;
    newNode->context = context;

    pthread_mutex_lock(&lock);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
}

int loadDriver(char *deviceName) {
    DeviceDriverNode *currentNode = head;

    while (currentNode != NULL) {
        if (!strcmp(currentNode->deviceName, deviceName)) {
            return currentNode->driverFunction(&currentNode->context);
        }

        currentNode = currentNode->next;
    }

    // Return an error code if driver not found
    return -1;
}

void unloadDriver(char *deviceName) {
    DeviceDriverNode **indirect = &head;

    while (*indirect != NULL) {
        if (!strcmp((*indirect)->deviceName, deviceName)) {
            DeviceDriverNode *temp = *indirect;
            *indirect = temp->next;

            free(temp->deviceName);
            free(temp);

            return;
        }

        indirect = &(*indirect)->next;
    }
}
```
