```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

typedef struct {
    char *if_id;
    char **ip_list;
    int num_ips;
} NIC;

typedef struct {
    NIC *nics;
    pthread_mutex_t lock;
    int num_nics;
} NICContext;

NICContext *nic_context = NULL;
int update_frequency = 10;  // Update every 10 seconds.
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int blacklisted = 0;

void *update_transport_stats(void *arg) {
    while (1) {
        pthread_mutex_lock(&mutex);

        if (!blacklisted && nic_context != NULL) {
            // Update transport layer statistics here.
            for (int i = 0; i < nic_context->num_nics; i++) {
                NIC *nic = &(nic_context->nics[i]);
                // Update stats...
            }
        }

        pthread_mutex_unlock(&mutex);

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += update_frequency;
        pthread_cond_timedwait(&cond, &mutex, &ts);
    }

    return NULL;
}

void add_nic(char *if_id) {
    pthread_mutex_lock(&(nic_context->lock));
    nic_context->nics = realloc(nic_context->nics, (nic_context->num_nics + 1) * sizeof(NIC));
    NIC *new_nic = &(nic_context->nics[nic_context->num_nics]);
    new_nic->if_id = strdup(if_id);
    new_nic->ip_list = NULL;
    new_nic->num_ips = 0;
    nic_context->num_nics++;
    pthread_mutex_unlock(&(nic_context->lock));
}

void add_ip_address(char *if_id, char *ip) {
    pthread_mutex_lock(&(nic_context->lock));

    for (int i = 0; i < nic_context->num_nics; i++) {
        NIC *nic = &(nic_context->nics[i]);

        if (!strcmp(nic->if_id, if_id)) {
            nic->ip_list = realloc(nic->ip_list, (nic->num_ips + 1) * sizeof(char *));
            nic->ip_list[nic->num_ips] = strdup(ip);
            nic->num_ips++;

            // Logging here.
        }
    }

    pthread_mutex_unlock(&(nic_context->lock));
}

void blacklist() {
    pthread_mutex_lock(&(nic_context->lock));
    blacklisted = 1;
    // Logging here.
    pthread_mutex_unlock(&(nic_context->lock));
}

void cleanup() {
    for (int i = 0; i < nic_context->num_nics; i++) {
        NIC *nic = &(nic_context->nics[i]);
        free(nic->if_id);

        for (int j = 0; j < nic->num_ips; j++) {
            free(nic->ip_list[j]);
        }

        free(nic->ip_list);
    }

    pthread_mutex_destroy(&(nic_context->lock));
}
``` 

