    nicList[nicCount-1]->IF_ID = strdup(ifId);
    nicList[nicCount-1]->ipList = ipList;
    nicList[nicCount-1]->ipCount = ipCount;
    pthread_mutex_init(&nicList[nicCount-1]->lock, NULL);
    logChanges("Added NIC");  // Logging changes
    pthread_mutex_unlock(&nicMutex);  // Unlock mutex after operation is complete
    return nicCount - 1;
}

void removeNIC(int index) {
    if (index >= nicCount || index < 0) return;
    pthread_mutex_lock(&nicList[index]->lock);
    free(nicList[index]->IF_ID);
    /* Free ipList and stats also */
    pthread_mutex_unlock(&nicList[index]->lock);
    free(nicList[index]);

    nicCount--;
    if (nicCount) {
        nicList[index] = nicList[nicCount];  // Swap last NIC to the removed index
        pthread_mutex_init(&nicList[index]->lock, NULL);  // Re-initialize lock
    } else {
        free(nicList);
        nicList = NULL;
    }

    logChanges("Removed NIC");
}

void updateStats(int index, TransportStats *stats) {
    if (index >= nicCount || index < 0) return;
    pthread_mutex_lock(&nicList[index]->lock);
    /* Update stats here */
    logChanges("Updated Stats");
    pthread_mutex_unlock(&nicList[index]->lock);
}
```
This is just a basic implementation and doesn't cover all your requirements. The actual implementation would be much more complex, especially for handling dynamic resizing of the NIC array, concurrent access to the NIC array with proper thread safety, blacklisting mechanism for certain interfaces, etc. Also, you should consider using libraries such as libpcap or PF_RING for network monitoring and packet capturing instead of implementing it manually from scratch.
