```CSharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;

public class DynamicDataManager<TValue> where TValue : IConvertible {
    private ConcurrentDictionary<string, TValue> data = new ConcurrentDictionary<string, TValue>();
    private ReaderWriterLockSlim locker = new ReaderWriterLockSlim();
    private const string FILE_NAME = "data.bin";

    public DynamicDataManager() {
        LoadFromDisk();
    }

    public bool Add(string key, TValue value) {
        if (data.ContainsKey(key)) return false; // avoid duplicates

        locker.EnterWriteLock();
        try {
            data[key] = value;
            SaveToDisk();
            return true;
        } finally {
            locker.ExitWriteLock();
        }
    }

    public bool Update(string key, TValue value) {
        if (!data.ContainsKey(key)) return false; // ensure key exists

        locker.EnterUpgradeableReadLock();
        try {
            data[key] = value;
            SaveToDisk();
            return true;
        } finally {
            locker.ExitUpgradeableReadLock();
        }
    }

    public TValue Get(string key) {
        locker.EnterReadLock();
        try {
            if (data.TryGetValue(key, out var value)) return value;
            else throw new KeyNotFoundException("Invalid Key");
        } finally {
            locker.ExitReadLock();
        }
    }

    private void SaveToDisk() {
        BinaryFormatter bf = new BinaryFormatter();
        using (FileStream fs = File.Create(FILE_NAME)) {
            var copyData = new ConcurrentDictionary<string, TValue>(data); // ensure data is thread-safe 
            bf.Serialize(fs, copyData);
        }
    }

    private void LoadFromDisk() {
        if (File.Exists(FILE_NAME)) {
            BinaryFormatter bf = new BinaryFormatter();
            using (FileStream fs = File.OpenRead(FILE_NAME)) {
                var loadedData = (ConcurrentDictionary<string, TValue>)bf.Deserialize(fs);

                locker.EnterWriteLock(); // protect data during load process
                try { 
                    data = loadedData; 
                } finally { 
                    locker.ExitWriteLock(); 
                }
            }
        }
    }
}
```

This example assumes that `IConvertible` covers all of the possible types you mentioned, which might not be the case in a real scenario. You will need to extend this implementation with more functionality and error handling according to your requirements. For instance, adding support for multiple data types would require an approach where each type has its own collection or implementing some form of type erasure or dynamic typing via `object`. Additionally, you may want to consider using other serialization formats like JSON or XML if binary formatting is not suitable for your use case.
