        Ok(t) => t,
        Err(_e) => return Err(Box::new(std::io::Error::new(std::io::ErrorKind::Other, "Failed to get modification time"))),
    };

    let sha256 = compute_sha256(&filename).await;

    let unique_identifier = format_unique_id(&[filename.as_bytes(), &sha256]);

    cache.insert(filename.to_string(), FileDetails { size, modified_time, sha256, unique_identifier });

    Ok(format_identifier(filename, &cache[&filename]))
}

