    for (int i = 0; i < num_modes; ++i) {
        if (strcmp(mode[i], "HYBRID") == 0 && env_security_level != NULL) {
            // Handle hybrid mode based on security level
            if (strcmp(env_security_level, "STANDARD") == 0) {
                set->cipher[i] = EVP_get_cipherbyname("AES-128-ECB");
            } else if (strcmp(env_security_level, "ENHANCED") == 0) {
                set->cipher[i] = EVP_get_cipherbyname("AES-256-CFB");
            } 
