    json_t *env = json_object_get(root, "environment");
    if(!json_is_object(env)) {
        logError(log_file, "Invalid or missing 'environment' section in configuration file.");
        return;
    }

    const char *key;
    json_t *value;
    json_object_foreach(env, key, value) {
        if(!json_is_string(value)) {
            logError(log_file, "Invalid environment variable type.");
            continue;
        }
        setenv(key, json_string_value(value), 1);
    }

    /* Load vendor autoloader */
    json_t *vendor = json_object_get(root, "vendor");
    if(!json_is_string(vendor)) {
        logError(log_file, "Invalid or missing 'vendor' section in configuration file.");
