['```c
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int capacity;
    int front;
    int rear;
    int count;
    pthread_mutex_t lock;
    sem_t full;
    sem_t empty;
} SignalQueue;

void signal_queue_init(SignalQueue *q, int capacity) {
    q->capacity = capacity;
    q->front = 0;
    q->rear = 0;
    q->count = 0;
    pthread_mutex_init(&q->lock, NULL);
    sem_init(&q->full, 0, 0);
    sem_init(&q->empty, 0, capacity);
}

void signal_queue_destroy(SignalQueue *q) {
    pthread_mutex_destroy(&q->lock);
    sem_destroy(&q->full);
    sem_destroy(&q->empty);
}

void signal_queue_push(SignalQueue *q, int data) {
    sem_wait(&q->empty); // decrement empty count or wait if 0
    pthread_mutex_lock(&q->lock);

    q->rear = (q->rear + 1) % q->capacity;
    // push data into the queue

    pthread_mutex_unlock(&q->lock);
    sem_post(&q->full); // increment full count
}

int signal_queue_pop(SignalQueue *q) {
    int data = 0;

    sem_wait(&q->full); // decrement full count or wait if 0
    pthread_mutex_lock(&q->lock);

    q->front = (q->front + 1) % q->capacity;
    // pop data from the queue into data

    pthread_mutex_unlock(&q->lock);
    sem_post(&q->empty); // increment empty count

    return data;
}
```
