// Function to create and return a new transaction from the CSV line
Transaction* createTransaction(char* csvLine) {
    Transaction* t = (Transaction*)malloc(sizeof(Transaction));
    if (t == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    char *token, *rest = csvLine;
