            case 0: t->transactionID = strdup(token); break;
            // Assumes time format YYYY-MM-DD hh:mm:ss
            case 1: strptime(token, "%F %T", &t->timestamp); break;
            case 2: t->amount = atof(token); break;
            case 3: t->status = !strcmp(token, "success"); break; //0 for success, 1 for failure
            case 4: t->customerID = strdup(token); break;
            case 5: t->merchantID = strdup(token); break;
