pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
MAC_CONTEXT_T* head = NULL;
int seqNums[1000000] = {0}; // Assuming maximum possible sequence numbers

void addToList(MAC_CONTEXT_T* node) {
    pthread_mutex_lock(&lock);

    if (head == NULL) {
        head = node;
        seqNums[node->rx_frame->FRAME_SEQ_NUM] = 1; // Mark the sequence number as used
    } else {
        MAC_CONTEXT_T* currentNode = head;

        while (currentNode != NULL) {
            if (currentNode->MAC_INSTANCE_ID == node->MAC_INSTANCE_ID || seqNums[node->rx_frame->FRAME_SEQ_NUM] == 1) {
                // Skip the current node, as its INSTANCE_ID or FRAME_SEQ_NUM is already in use.
            } else {
                if (currentNode->next == NULL) {
                    // Append at the end of the list
                    currentNode->next = node;
                    node->prev = currentNode;
                } else {
                    // Insert between two nodes
                    node->next = currentNode->next;
                    currentNode->next->prev = node;
                    currentNode->next = node;
                    node->prev = currentNode;
                }
                seqNums[node->rx_frame->FRAME_SEQ_NUM] = 1; // Mark the sequence number as used
            }

            currentNode = currentNode->next;
        }
    }

    pthread_mutex_unlock(&lock);
}
```

