["This is quite a comprehensive task. Here's an outline of how you might structure your code using pthread library functions for thread synchronization. Note that actual implementation would require a detailed design and testing, especially to ensure performance under high load scenarios and thread safety:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int SID;
    pthread_mutex_t actionMutex;  // For concurrent access of user actions
} UserSessionContext;

// Global array to store USCs and associated mutex for thread-safe operations
UserSessionContext **USCArray = NULL;
int USCCapacity = 0, USCSize = 0;
pthread_mutex_t USCMutex = PTHREAD_MUTEX_INITIALIZER;  // For synchronizing access to the array

// Add a new USC to the array
void addUSC(int SID) {
    pthread_mutex_lock(&USCMutex);

    if (USCSize >= USCCapacity) {
        // Resize array and reallocate memory
        USCCapacity = USCCapacity ? USCCapacity * 2 : 1;
        USCArray = realloc(USCArray, sizeof(*USCArray) * USCCapacity);

        if (!USCArray) {
            // Handle allocation failure error
            pthread_mutex_unlock(&USCMutex);
            return;
        }
    }

    UserSessionContext* newUSC = malloc(sizeof(*newUSC));
    newUSC->SID = SID;
    pthread_mutex_init(&newUSC->actionMutex, NULL);  // Initialize mutex for user actions

    USCArray[USCSize++] = newUSC;

    pthread_mutex_unlock(&USCMutex);
}

// Remove an existing USC from the array
void removeUSC(int SID) {
    pthread_mutex_lock(&USCMutex);

    for (int i = 0; i < USCSize; ++i) {
        if (USCArray[i]->SID == SID) {
            pthread_mutex_destroy(&USCArray[i]->actionMutex);  // Destroy mutex before freeing memory
            free(USCArray[i]);

            // Shift all elements after the removed one to fill the gap
            for (int j = i; j < USCSize - 1; ++j) {
                USCArray[j] = USCArray[j + 1];
            }

            --USCSize;
            break;
        }
    }

    pthread_mutex_unlock(&USCMutex);
}
