['Here is an implementation of this task in C using system calls for file manipulation. This code does not include error handling for memory allocation failures (malloc), so it's important to check the return values of these functions before proceeding. 

```c
#include <stdio.h>
#include <dirent.h> 
#include <sys/stat.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

int copy_files(char *src, char *dest, char *filter, int sizeLimit, FILE* logFile) {
    DIR *dir;
    struct dirent *entry;
    struct stat buf;
    char srcPath[4096], destPath[4096];
    int copiedFiles = 0, failedCopies = 0;
    if (!(dir = opendir(src))) {
        fprintf(logFile, "Cannot open directory: %s\n", strerror(errno));
        return 1;
    }

    while ((entry = readdir(dir)) != NULL) {
        snprintf(srcPath, sizeof(srcPath), "%s/%s", src, entry->d_name);
        if (lstat(srcPath, &buf) < 0) {
            fprintf(logFile, "Cannot stat file: %s\n", strerror(errno));
            continue;
        }

        if (!S_ISREG(buf.st_mode)) {
            continue;  // Skip directories and symbolic links
        }

        if (strstr(entry->d_name, filter) == NULL) {
            continue;  // Filter files that don't match the pattern
        }

        if ((intmax_t)buf.st_size > sizeLimit * 1024 * 1024) {
            fprintf(logFile, "Skipping file: %s (too large)\n", entry->d_name);
            continue;
        }

        snprintf(destPath, sizeof(destPath), "%s/%s", dest, entry->d_name);
        if (access(destPath, F_OK) == 0) {  // Check if destination file already exists
            fprintf(logFile, "Destination file already exists: %s\n", destPath);
            failedCopies++;
            continue;
        }

        int srcFd = open(srcPath, O_RDONLY);
        if (srcFd < 0) {
            fprintf(logFile, "Cannot open source file: %s\n", strerror(errno));
            failedCopies++;
            continue;
        }

        int destFd = open(destPath, O_WRONLY | O_CREAT, buf.st_mode);
        if (destFd < 0) {
            fprintf(logFile, "Cannot create destination file: %s\n", strerror(errno));
            failedCopies++;
            close(srcFd);
            continue;
        }

        char buf[4096];
        ssize_t bytesRead;
        while ((bytesRead = read(srcFd, buf, sizeof(buf))) > 0) {
            if (write(destFd, buf, bytesRead) < 0) {
                fprintf(logFile, "Cannot write to destination file: %s\n", strerror(errno));
                failedCopies++;
                break;
            }
        }

        if (bytesRead < 0) {
            fprintf(logFile, "Cannot read source file: %s\n", strerror(errno));
            failedCopies++;
        } else {
            copiedFiles++;
        }

        close(srcFd);
        close(destFd);
    }

    printf("Total files copied: %d, Failed copies: %d\n", copiedFiles, failedCopies);
    return 0;
}
```
This function will copy all regular files (not directories or symbolic links) in the source directory that match the filter pattern and are smaller than the specified size limit to the destination directory. It will create new files with the same permissions as the original ones, but it does not handle overwriting or copying non-regular files. It also logs any errors that occur during the process to a specified log file, without terminating the program.
']

