typedef struct {
    int sid;
    // other fields...
} UserSessionContext;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    UserSessionContext *uscArray;
} USCManager;

// Initialize the USC manager
void initUSCManager(USCManager* mgr, size_t initialCapacity) {
    mgr->capacity = initialCapacity;
    mgr->size = 0;
    mgr->uscArray = (UserSessionContext*)malloc(initialCapacity * sizeof(UserSessionContext));
    pthread_mutex_init(&(mgr->lock), NULL);
}

// Add a USC to the manager with locking
void addUSC(USCManager* mgr, UserSessionContext usc) {
    pthread_mutex_lock(&(mgr->lock));

    if (mgr->size >= mgr->capacity) {
        // Resize the array
        mgr->capacity *= 2;
        mgr->uscArray = realloc(mgr->uscArray, mgr->capacity * sizeof(UserSessionContext));
    }

    mgr->uscArray[mgr->size++] = usc;

    pthread_mutex_unlock(&(mgr->lock));
}

// Get a USC by SID, or NULL if not found
UserSessionContext* getUSCBySid(USCManager* mgr, int sid) {
    UserSessionContext *usc;

    pthread_mutex_lock(&(mgr->lock));

    for (size_t i = 0; i < mgr->size; ++i) {
        if (mgr->uscArray[i].sid == sid) {
            usc = &(mgr->uscArray[i]);
            break;
        } else {
            usc = NULL;
        }
    }

    pthread_mutex_unlock(&(mgr->lock));

    return usc;
}
