            // Update stats...

            pthread_mutex_unlock(&(NICs[i]->stats_lock));
        }
        pthread_mutex_unlock(&array_lock);
    }
}

// Compute MD5 hash of a file in chunks.
char* computeMD5(const char* filepath, unsigned long chunkSize) {
    int file = open(filepath, O_RDONLY);
    if (file < 0) {
        return NULL; // File access error...
    }

    struct stat st;
    fstat(file, &st);
    off_t size = st.st_size;

    MD5_CTX context;
    MD5_Init(&context);

    unsigned char buffer[chunkSize];
    ssize_t bytesRead;
    for (off_t i = 0; i < size; i += chunkSize) {
        if ((bytesRead = read(file, buffer, sizeof(buffer))) < 1) {
            return NULL; // Read error...
        }

        MD5_Update(&context, buffer, bytesRead);
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &context);

    close(file);

    // Convert the result to a hexadecimal string.
    char* hex = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hex[i * 2], "%02x", digest[i]); // Each byte as two hex digits...
    }

    return hex;
}
