['Here is a simple implementation of such a system in C. It uses a combination of locks and atomic operations to ensure thread safety while updating DIOC structures. However, please note that this is a simplistic approach and might not be optimal for all scenarios. The code does not include mechanisms for blacklisting or unblacklisting devices, as those would need more complex synchronization strategies. It also lacks the mechanisms for adjusting update frequency based on disk throughput or logging changes to DIOC contexts - these could be added but are left out for simplicity and focusing on thread safety and resource cleanup:

```c
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct {
    int fd;
    atomic_int performance_metrics;
} FileDescriptorContext;

typedef struct {
    int dev_id;
    pthread_mutex_t lock;
    size_t num_fds;
    FileDescriptorContext **fdc_list;
} DIOC;

DIOC *new_dio(int id) {
    DIOC *dio = malloc(sizeof(DIOC));

    if (dio == NULL || pthread_mutex_init(&dio->lock, NULL) != 0) {
        free(dio);
        return NULL;
    }

    dio->dev_id = id;
    dio->num_fds = 0;
    dio->fdc_list = NULL;

    return dio;
}

void add_file_descriptor(DIOC *dio, int fd) {
    pthread_mutex_lock(&dio->lock);

    FileDescriptorContext **new_list = realloc(dio->fdc_list, (dio->num_fds + 1) * sizeof(FileDescriptorContext *));

    if (new_list == NULL) {
        pthread_mutex_unlock(&dio->lock);
        return;
    }

    dio->fdc_list = new_list;
    dio->fdc_list[dio->num_fds] = malloc(sizeof(FileDescriptorContext));
    dio->fdc_list[dio->num_fds]->fd = fd;
    ++dio->num_fds;

    pthread_mutex_unlock(&dio->lock);
}

void update_performance(DIOC *dio, size_t index, int metrics) {
    atomic_store(&dio->fdc_list[index]->performance_metrics, metrics);
}

void cleanup_dio(DIOC **diocs, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&diocs[i]->lock);

        for (size_t j = 0; j < diocs[i]->num_fds; ++j) {
            free(diocs[i]->fdc_list[j]);
        }

        pthread_mutex_unlock(&diocs[i]->lock);

        free(diocs[i]->fdc_list);
        diocs[i]->fdc_list = NULL;
        pthread_mutex_destroy(&diocs[i]->lock);
        free(diocs[i]);
    }

    free(diocs);
}
``` 

In the above code, DIOCs are protected by locks to ensure that only one thread can access or modify a particular DIOC at any given time. This avoids race conditions and ensures data integrity. However, this does not account for blacklisting devices - which would require more complex synchronization strategies.
