        if (newArray == NULL) {
            // handle memory allocation failure
            pthread_mutex_unlock(&manager->lock);
            return;
        }

        manager->configs = newArray;
        manager->capacity = newCapacity;
    }

    manager->configs[manager->count++] = config;

    pthread_mutex_unlock(&manager->lock);
