using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Dapper; // Use Dapper for simplifying DB operations

public async Task<List<Dictionary<string, object>>> ExecuteDynamicQuery(
    SqlConnection connection, 
    string schemaName, 
    List<string> fieldsToSelect)
{
    var query = $"SELECT {string.Join(", ", fieldsToSelect)} FROM {schemaName}";

    using (var multi = await connection.QueryMultipleAsync(query))
    {
        var resultSets = new List<Dictionary<string, object>>();

        while (!multi.IsConsumed)
        {
            var currentSet = multi.Read().MapToDictionary();
            resultSets.Add(currentSet);
        }

        return resultSets;
    }
}
