#include <openssl/evp.h>

typedef struct {
    char* buffer;
    int size;
} FileData;

FileData readFile(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error while opening the file.\n");
        exit(EXIT_FAILURE);
    }

    fseek(file, 0L, SEEK_END);
    long numbytes = ftell(file);

    FileData data;
    data.buffer = (char *)malloc(numbytes * sizeof(char));
    if(data.buffer == NULL) {
        fclose(file);
        perror("Error while allocating memory.\n");
        exit(EXIT_FAILURE);
    }

    fseek(file, 0L, SEEK_SET);
    fread(data.buffer, sizeof(char), numbytes, file);
    data.size = (int)numbytes;

    fclose(file);
    return data;
}

void processAndWriteFile(const char *inFilename, const char *outFilename, const char *ruleString, int encryptFlag) {
    FileData inputData = readFile(inFilename);

    // Here you can apply your rules to the data

