["Here's a high-level overview of how you might structure your code according to these requirements. Please note that C does not inherently support concurrent threads or garbage collection like languages like Java, Python, etc. so we need to manage those manually. Memory allocation failures are also handled with return codes in this example.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UE_ID;
    int* MAC;
    size_t mac_size;
    void* PDCP; // replace with actual structure if known
} UEContext;

// global mutex for managing access to UE contexts
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

typedef struct {
    size_t capacity;
    size_t count;
    UEContext** contexts; // dynamic array of pointers to context structures
} UEMemoryPool;

// function to initialize memory pool
int initMemoryPool(UEMemoryPool* pool, size_t initialCapacity) {
    pool->capacity = initialCapacity;
    pool->count = 0;
    pool->contexts = (UEContext**) malloc(sizeof(UEContext*) * initialCapacity);

    if (pool->contexts == NULL) return -1; // allocation failed

    for (size_t i = 0; i < initialCapacity; ++i) {
        pool->contexts[i] = NULL; // initialize all pointers to null initially
    }

    return 0;
}

// function to add UE context to memory pool
int addUEContext(UEMemoryPool* pool, UEContext* context) {
    pthread_mutex_lock(&lock);

    if (pool->count == pool->capacity) {
        // double the size of the array
        size_t newCapacity = pool->capacity * 2;
        UEContext** newArray = (UEContext**) realloc(pool->contexts, sizeof(UEContext*) * newCapacity);

        if (newArray == NULL) {
            pthread_mutex_unlock(&lock);
            return -1; // allocation failed
        }

        pool->capacity = newCapacity;
        pool->contexts = newArray;
    }

    pool->contexts[pool->count] = context;
    pool->count++;

    pthread_mutex_unlock(&lock);

    return 0; // success
}

// function to remove UE context from memory pool
int removeUEContext(UEMemoryPool* pool, int UE_ID) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->contexts[i]->UE_ID == UE_ID) {
            // shift all elements to the left, overwriting the removed element
            for (size_t j = i; j < pool->count - 1; ++j) {
                pool->contexts[j] = pool->contexts[j + 1];
            }

            free(pool->contexts[pool->count - 1]); // free memory for removed context
            pool->count--;

            pthread_mutex_unlock(&lock);
            return 0; // success
        }
    }

    pthread_mutex_unlock(&lock);
    return -1; // UE ID not found
}

// Similar functions for handling MAC entities and PDCP stats. Add error handling, logging, and concurrent access management as needed based on the above requirements.
```
This is a basic example that covers some of your requirements. In a real-world application, you would likely want to use existing libraries or frameworks that provide these features, such as glib's GArray for dynamic arrays (though it doesn't natively support concurrent access), pthreads for threads and mutexes, libconfig for managing configurations, syslog for logging, etc.
