// Function to generate md5 hash of a file.
void generate_md5_hashes(const std::string& filePath) {
    std::ifstream inputFile (filePath, std::ios::binary);

    if(!inputFile){
        throw std::runtime_error("Failed to open the file!");
    }

    unsigned char c;
    unsigned char digest[16]; // 128 bit or 16 byte buffer.
    MD5_CTX ctx;
    MD5_Init(&ctx);

    while(inputFile.read((char *) &c, sizeof(unsigned char))) {
        if(!MD5_Update(&ctx, (const void*)&c, 1)) // Process the next piece of data.
            throw std::runtime_error("Failed to update MD5 hash!");
    }

    if(!MD5_Final(digest, &ctx)) // Wrap up and finish the current message.
        throw std::runtime_error("Failed to finalize MD5 hash!");

    for (int i = 0; i < 16; ++i) {
       printf("%02x", digest[i]);
    }
}

int main() {
