import java.util.*;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class SessionManager {
    private Map<String, UserSession> sessions = new HashMap<>();
    private ReadWriteLock lock = new ReentrantReadWriteLock();

    public void addService(String sessionId, String service) {
        try {
            lock.writeLock().lock();
            if (sessions.containsKey(sessionId)) {
                sessions.get(sessionId).addService(service);
            } else {
                UserSession userSession = new UserSession(sessionId);
                userSession.addService(service);
                sessions.put(sessionId, userSession);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void updateMetrics(String sessionId, Metrics metrics) {
        try {
            lock.writeLock().lock();
            if (sessions.containsKey(sessionId)) {
                sessions.get(sessionId).updateMetrics(metrics);
            } else {
                UserSession userSession = new UserSession(sessionId, metrics);
                sessions.put(sessionId, userSession);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

