namespace RandomNumberGenerator {
    class Generator {
    private:
        std::mt19937 gen;
        std::uniform_int_distribution<unsigned int> dis;
        std::mutex mtx;

    public:
        Generator() : dis(0, UINT_MAX) {
            std::random_device rd;
            gen.seed(rd());
        }

        unsigned int generateRandomNumber() {
            std::lock_guard<std::mutex> lock(mtx);  // Ensure thread-safe access
            return dis(gen);
        }
    };
}

void generate_md5_hashes(const std::string &filename) {
    unsigned char c[MD5_DIGEST_LENGTH];
    MD5_CTX mdContext;
    int bytes;

    FILE *inFile = fopen (filename.c_str(), "rb");
    if (inFile == NULL) throw std::runtime_error("Could not open the file!");

    unsigned long lSize;
    char *buffer;
    size_t result;

    // Get the size of the file
    fseek(inFile, 0, SEEK_END);
    lSize = ftell(inFile);
    rewind(inFile);

    // Allocate memory for buffer
    buffer = (char*) malloc (sizeof(char)*lSize);
    if (buffer == NULL) throw std::runtime_error("Memory error!");

    // Copy file into the buffer 
    result = fread(buffer, 1, lSize, inFile);
    if (result != lSize) throw std::runtime_error("Reading error");

    MD5_Init(&mdContext);
    MD5_Update(&mdContext, buffer, lSize);
    MD5_Final(c, &mdContext);

    free(buffer);
}

int main() {
    RandomNumberGenerator::Generator gen;
    std::cout << "Random Number: " << gen.generateRandomNumber() << std::endl;

    try{
        generate_md5_hashes("testfile");
