};

class IoTContextManager {
private:
    std::map<std::string, DeviceContext> devices;
    std::recursive_mutex globalLock;  // Recursive mutex for multiple levels of locking

public:
    void AddDevice(const std::string& devID) {
        std::lock_guard<std::recursive_mutex> lock(globalLock);
        devices[devID] = DeviceContext();
        // Logging mechanism to record addition 
    }

    void UpdateMetric(const std::string& devID, const std::string& metric, double value) {
        std::lock_guard<std::recursive_mutex> lock(globalLock);

        if (devices.count(devID)) {
            DeviceContext &context = devices[devID];

            // Thread safety for write operation on 'metrics' map
            std::lock_guard<std::mutex> lock2(context.mtx);  
            context.metrics[metric] = value; 

            // Logging mechanism to record update
        } else {
            throw "Device ID not found!";
        }
    }

    void SuspendDevice(const std::string& devID) {
        std::lock_guard<std::recursive_mutex> lock(globalLock);

        if (devices.count(devID)) {
            DeviceContext &context = devices[devID];

            // Thread safety for write operation on 'suspended' flag
            context.suspended = true; 

            // Logging mechanism to record suspension
        } else {
            throw "Device ID not found!";
        }
    }

    void SetUpdateFrequency(const std::string& devID, int freq) {
        std::lock_guard<std::recursive_mutex> lock(globalLock);

        if (devices.count(devID)) {
            DeviceContext &context = devices[devID];

            // Thread safety for write operation on 'updateFrequency' field
            context.updateFrequency = freq; 

            // Logging mechanism to record update frequency setting
        } else {
            throw "Device ID not found!";
        }
    }

    void AddSensorEntity(const std::string& devID, const SensorEntity& sensor) {
        std::lock_guard<std::recursive_mutex> lock(globalLock);

        if (devices.count(devID)) {
            DeviceContext &context = devices[devID];

            // Thread safety for write operation on 'sensorEntities' vector
            std::lock_guard<std::mutex> lock2(context.mtx);  
            context.sensorEntities.push_back(sensor); 

            // Logging mechanism to record addition of sensor entity
        } else {
