['```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct RX_UE_INFORMATION_TAG {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ueInfo;
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T value;
    struct ListNode *next;
} ListNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
ListNode* head = NULL;

int add_unique(NFAPI_CRC_INDICATION_PDU_T pdu, int max_pdu_count) {
    pthread_mutex_lock(&lock);
    if (max_pdu_count <= 0) {
        printf("Error: Max PDU count is not valid\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    ListNode *current = head;
    while(current != NULL && current->value.ueInfo.RNTI != pdu.ueInfo.RNTI) {
        current = current->next;
    }
    if (current == NULL) {
        if (max_pdu_count <= 0) {
            printf("Error: Max PDU count reached\n");
            pthread_mutex_unlock(&lock);
            return -1;
        } else {
            ListNode *newNode = malloc(sizeof(ListNode));
            newNode->value = pdu;
            newNode->next = head;
            head = newNode;

            srand(time(NULL));
            newNode->value.crcIndication.CRCFLAG = rand();

            max_pdu_count--;
        }
    } else {
        printf("Error: Duplicate RNTI found\n");
    }

    pthread_mutex_unlock(&lock);
    return 0;
}
```
