    for (int i = 0; i < interfaceCount; ++i) {
        if (networkInterfaces[i]->if_id == id) {
            iface = networkInterfaces[i];
            break;
        }
    }

    if (!iface) return; // Interface not found

    pthread_mutex_lock(&iface->lock);
    iface->connections = realloc(iface->connections, sizeof(TCPConnection*) * ++iface->conn_count);
    iface->connections[iface->conn_count - 1] = conn;
    pthread_mutex_unlock(&iface->lock);
}

void cleanup() {
    for (int i = 0; i < interfaceCount; ++i) {
        free(networkInterfaces[i]->connections);
        pthread_mutex_destroy(&networkInterfaces[i]->lock);
        free(networkInterfaces[i]);
