```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DL_MAC_SDU {
    // Add fields according to the requirements of SDUs
} DL_MAC_SDU;

typedef struct LTE_DL_MAC_PDU {
    size_t capacity;
    size_t count;
    DL_MAC_SDU* data;
    pthread_mutex_t lock;
} LTE_DL_MAC_PDU;

int init_LTE_DL_MAC_PDU(LTE_DL_MAC_PDU *pdu, size_t initial_capacity) {
    if (initial_capacity <= 0 || !pdu) {
        return -1;
    }

    pdu->data = (DL_MAC_SDU*)malloc(sizeof(DL_MAC_SDU) * initial_capacity);

    if (!pdu->data) {
        return -2;  // Out of memory error
    }

    pdu->count = 0;
    pdu->capacity = initial_capacity;

    pthread_mutex_init(&(pdu->lock), NULL);

    return 0;  // Success
}

int add_DL_MAC_SDU(LTE_DL_MAC_PDU *pdu, DL_MAC_SDU sdu) {
    if (!pdu || !pdu->data) {
        return -1;  // Invalid or corrupted data error
    }

    pthread_mutex_lock(&(pdu->lock));

    if (pdu->count >= pdu->capacity) {
        size_t new_capacity = pdu->capacity * 2;

        DL_MAC_SDU* temp = (DL_MAC_SDU*)realloc(pdu->data, sizeof(DL_MAC_SDU) * new_capacity);
        if (!temp) {
            pthread_mutex_unlock(&(pdu->lock));
            return -2;  // Out of memory error
        }

        pdu->data = temp;
        pdu->capacity = new_capacity;
    }

    memcpy(&(pdu->data[pdu->count]), &sdu, sizeof(DL_MAC_SDU));
    (pdu->count)++;

    pthread_mutex_unlock(&(pdu->lock));

    return 0;  // Success
}
```
This code includes a `init_LTE_DL_MAC_PDU` function to initialize the list and an `add_DL_MAC_SDU` function to add SDUs. It uses mutex locks for thread safety. The memory is allocated efficiently, and the size of the list (capacity) will be doubled when necessary to avoid frequent reallocations.
