    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->data = malloc(initial_capacity * sizeof(UeContext));
    if (array->data == NULL) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;

    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void add_ue_context(DynamicArray* array, UeContext context) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        UeContext* new_data = realloc(array->data, new_capacity * sizeof(UeContext));

        if (new_data == NULL) {
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size] = context;
    array->size++;

    pthread_mutex_unlock(&array->lock);
}
```
In the example above, a `DynamicArray` struct is used to hold our data. It includes a lock for thread safety and also a way to resize when we run out of space. The `add_ue_context` function adds an element to the array making sure it's thread-safe by locking the mutex before we modify the data structure. 

