#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct RAN_Entity {
    // Implementation specifics here
} RAN_Entity;

typedef struct MAC_Metrics {
    // Implementation specifics here
} MAC_Metrics;

typedef struct NodeContext {
    int nodeId;
    atomic_int numRANEntities;
    RAN_Entity** ranEntities;  // Dynamic array of pointers to RAN entities
    pthread_mutex_t lock;      // Lock for thread safety
    MAC_Metrics macMetrics;   // Metrics struct
} NodeContext;

NodeContext* createNode(int nodeId) {
    NodeContext *node = malloc(sizeof(NodeContext));  // Allocate memory
    if (node == NULL) return NULL;                    // Check for allocation failure

    atomic_init(&node->numRANEntities, 0);             // Initialize atomic variables
    pthread_mutex_init(&node->lock, NULL);            // Initialize locks

    node->ranEntities = malloc(sizeof(RAN_Entity*));   // Allocate initial memory for RAN entities array
    if (node->ranEntities == NULL) {                  // Check allocation failure
        free(node);                                  
        return NULL; 
    }

    node->nodeId = nodeId;                           // Initialize Node ID
    return node;                                     // Return initialized NodeContext pointer
}

void addRANEntity(NodeContext* node, RAN_Entity* entity) {
    pthread_mutex_lock(&node->lock);                  // Acquire lock to ensure thread safety 

    atomic_fetch_add(&node->numRANEntities, 1);        // Increment counter atomically
    node->ranEntities = realloc(node->ranEntities, sizeof(RAN_Entity*) * (atomic_load(&node->numRANEntities) + 1));
    if (node->ranEntities == NULL) return;            // Check allocation failure

    node->ranEntities[atomic_load(&node->numRANEntities) - 1] = entity;

    pthread_mutex_unlock(&node->lock);                // Release lock after modification
}
```
This is a basic start and does not include all the mentioned functionalities like logging, performance updates or isolation periods. The implementation specifics would depend on your actual requirements and design choices.
