struct ServiceManager {
    cache: HashMap<String, (Vec<Token>, String)>,
    pool: ThreadPool,
}

impl ServiceManager {
    fn new(threads: usize) -> Self {
        let pool = rayon::ThreadPoolBuilder::new()
            .num_threads(threads)
            .build().unwrap();

        ServiceManager { cache: HashMap::new(), pool }
    }

    fn manage_service_and_generate_ir(&mut self, path: &str, config: JsonValue) -> Result<(), String> {
        // Validate file path and extension
        if !Path::new(path).exists() || Path::new(path).extension().unwrap() != "service" {
            return Err("File does not exist or has incorrect extension".to_string());
        }

        // Load the service file asynchronously using non-blocking I/O operations.
        let mut file = match File::open(path) {
            Ok(file) => file,
            Err(e) => return Err(format![I/O error: {}", e]),
        };

        // Modify the file extension to prevent buffer overflow vulnerabilities using snprintf.
        let mut new_extension = "ir";
        let mut buffer: [u8; 50] = [0; 50];
        unsafe {
            snprintf::snprintf(buffer.as_mut_ptr() as *mut i8, buffer.len(), ".%s", new_extension);
        }

