Please note that this is not a complete solution, but a simplified starting point. The design of the data structures and their interactions are complex tasks in themselves and may require a lot more work depending on the actual requirements. It's recommended to use mature libraries or platforms designed specifically for such tasks.

```c
#include <pthread.h>
#include <stdlib.h>
#include <unistd.h>

typedef struct RANEntity {
    int id;
} RANEntity;

typedef struct MacMetrics {
    double throughput;
    double latency;
} MacMetrics;

typedef struct NodeContext {
    pthread_mutex_t lock;
    int nodeID;
    RANEntity* RANs[]; // dynamically allocated array
    int numRANS;
    MacMetrics metrics;
} NodeContext;

NodeContext** nodes; // dynamic array of pointers to NodeContext structures
int nodeCount;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;
double updateFrequency = 1.0; // in seconds

void* updateMetrics(void* arg) {
    while (1) {
        sleep(updateFrequency);

        pthread_mutex_lock(&globalLock);
        for (int i = 0; i < nodeCount; ++i) {
            // Calculate new metrics based on traffic patterns
            NodeContext* node = nodes[i];

            // Simplified example, replace with actual traffic pattern calculation.
            pthread_mutex_lock(&node->lock);
            node->metrics.throughput += 10;
            node->metrics.latency -= 2;
            pthread_mutex_unlock(&node->lock);
        }
        pthread_mutex_unlock(&globalLock);
    }

    return NULL;
}

void addNode(int id) {
    NodeContext* node = malloc(sizeof(NodeContext));
    if (node == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }

    node->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    node->numRANS = 0;
    node->nodeID = id;
    pthread_mutex_init(&node->lock, NULL);

    pthread_mutex_lock(&globalLock);
    nodes[nodeCount++] = node; // add to the array
    pthread_mutex_unlock(&globalLock);
}

void removeNode(int id) {
    pthread_mutex_lock(&globalLock);

    for (int i = 0; i < nodeCount; ++i) {
        if (nodes[i]->nodeID == id) {
            // Free resources and remove from array
            free(nodes[i]);

            // Move the last element to fill the gap.
            nodes[i] = nodes[--nodeCount];
            break;
        }
    }

    pthread_mutex_unlock(&globalLock);
}

void addRANEntity(int id, RANEntity* entity) {
    for (int i = 0; i < nodeCount; ++i) {
        if (nodes[i]->nodeID == id) {
            pthread_mutex_lock(&nodes[i]->lock);

            // Add to the array of RAN entities.
            nodes[i]->RANs[nodes[i]->numRANS++] = entity;

            pthread_mutex_unlock(&nodes[i]->lock);
        }
    }
}
```
