    unsigned char c[MD5_DIGEST_LENGTH];
    MD5_CTX mdContext;
    int bytes;

    // Initialize context 
    MD5_Init(&mdContext);

    // Open file 
    std::ifstream in(filename, std::ios::binary);

    // Read data and update hash
    char buffer[1024];
    while (in.read(buffer, sizeof(buffer)), in.gcount() > 0) {
        MD5_Update(&mdContext, buffer, in.gcount());
