void addEntity(UE_Context* ue, MAC_Entity entity) {
    pthread_mutex_lock(&ue->entityMutex);
    if (ue->numMacEntities == atomic_load(&ue->maxNumMacEntities)) {
        // Increase the size of macEntities dynamically based on network traffic patterns
        ue->macEntities = realloc(ue->macEntities, ++ue->maxNumMacEntities * sizeof(MAC_Entity));
    }
    ue->macEntities[ue->numMacEntities++] = entity;
    pthread_mutex_unlock(&ue->entityMutex);
}

void updateStats(UE_Context* ue, PDCP_Statistics stats) {
    // Critical section for updating statistics
    pthread_mutex_lock(&ue->entityMutex);
    // Update your stats here
    pthread_mutex_unlock(&ue->entityMutex);
}

void addContext(UE_Context* context) {
    pthread_mutex_lock(&contextMutex);
    contexts = realloc(contexts, ++numContexts * sizeof(UE_Context*));
    contexts[numContexts - 1] = context;
    pthread_mutex_unlock(&contextMutex);
}

void cleanUp() {
    for (size_t i = 0; i < numContexts; ++i) {
        // Free memory allocated for each UE Context and its MAC entities here
        free(contexts[i]->macEntities);
        pthread_mutex_destroy(&contexts[i]->entityMutex);
        free(contexts[i]);
    }
    free(contexts); // Free the contexts array itself.
}
```
