        pthread_mutex_init(&(aps[num_aps].lock), NULL);  // Initialize each AP's lock.
        num_aps++;
    } else {
        printf("Maximum number of AP configurations reached!\n");
    }
    pthread_mutex_unlock(&global_lock);

    return NULL;
}

void cleanup() {
    for (int i = 0; i < num_aps; ++i) {
        pthread_mutex_destroy(&(aps[i].lock));  // Destroy each AP's lock.
    }

    pthread_mutex_destroy(&global_lock);  // Destroy the global lock.
}
```
This code manages an array of `AP_config` structures, each containing a unique AP identifier and a mutex for thread safety. When adding a new AP configuration, it locks the global mutex to ensure that only one thread can modify the array at a time. The function cleanup() should be called when the program terminates to destroy all mutexes to avoid memory leaks.
']

