    DeviceContext *newDev = malloc(sizeof(DeviceContext));
    if (newDev == NULL) return NULL;

    pthread_mutex_init(&newDev->lock, NULL);
    newDev->Dev_ID = id;
    newDev->numInterfaces = 0;
    newDev->NetworkInterfaces = NULL;
