void AddNewInterface(DeviceContext *devCtx, const char *newIntf) {
    pthread_mutex_lock(&devCtx->lock);

    devCtx->numInterfaces++;
    // Reallocate memory for interfaces and add the new interface
    devCtx->NetworkInterfaces = realloc(devCtx->NetworkInterfaces, sizeof(char *) * devCtx->numInterfaces);
    if (newIntf != NULL) {
        devCtx->NetworkInterfaces[devCtx->numInterfaces - 1] = strdup(newIntf);
    } else {
        devCtx->NetworkInterfaces[devCtx->numInterfaces - 1] = NULL;
    }

    pthread_mutex_unlock(&devCtx->lock);
}

void UpdatePerformanceMetrics(DeviceContext *devCtx, double newMetrics[5]) {
    pthread_mutex_lock(&devCtx->lock);

    // Copy the new metrics to the device context
    memcpy(devCtx->PerformanceMetrics, newMetrics, 5 * sizeof(double));

    pthread_mutex_unlock(&devCtx->lock);
}

void DestroyDeviceContext(DeviceContext *devCtx) {
    // Free memory for all allocated resources
    for (size_t i = 0; i < devCtx->numInterfaces; ++i) {
        free(devCtx->NetworkInterfaces[i]);
    }

    pthread_mutex_destroy(&devCtx->lock);
    free(devCtx->NetworkInterfaces);
    free(devCtx->PerformanceMetrics);
    free(devCtx);
}
