    pthread_mutex_lock(&list->lock);  // acquire lock before modifying the list
    if (list->head == NULL) {
        list->head = node;
    } else {
        Node *temp = list->head;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = node;
        node->prev = temp;
    }
    pthread_mutex_unlock(&list->lock);  // release lock after modifying the list
}
```

