['Here's a basic implementation for such a class in Java:

```java
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.locks.ReentrantLock;

public class SensorNodeManager {
    private final Map<String, Node> nodes = new ConcurrentHashMap<>();

    public void addReading(String nodeId, Reading reading) {
        Node node = nodes.get(nodeId);

        if (node == null) {
            throw new IllegalArgumentException("No such node: " + nodeId);
        }

        synchronized (node.readingsLock) {
            node.addReading(reading);
        }
    }

    public void updateMetrics(String nodeId, Metrics metrics) {
        Node node = nodes.get(nodeId);

        if (node == null) {
            throw new IllegalArgumentException("No such node: " + nodeId);
        }

        synchronized (node.metricsLock) {
            node.updateMetrics(metrics);
        }
    }

    public Metrics getCurrentMetrics(String nodeId) {
        Node node = nodes.get(nodeId);

        if (node == null) {
            throw new IllegalArgumentException("No such node: " + nodeId);
        }

        return node.getCurrentMetrics();
    }

    public List<Reading> getReadings(String nodeId) {
        Node node = nodes.get(nodeId);

        if (node == null) {
            throw new IllegalArgumentException("No such node: " + nodeId);
        }

        synchronized (node.readingsLock) {
            return Collections.unmodifiableList(new ArrayList<>(node.getReadings()));
        }
    }

    private static class Node {
        private final ReentrantLock readingsLock = new ReentrantLock();
        private final ReentrantLock metricsLock = new ReentrantLock();

        private final List<Reading> readings = new CopyOnWriteArrayList<>();
        private Metrics metrics;

        void addReading(Reading reading) {
            readings.add(reading);

            if (readings.size() > 10_000) {
                readings.remove(0);
            }
        }

        List<Reading> getReadings() {
            return Collections.unmodifiableList(readings);
        }

        void updateMetrics(Metrics metrics) {
            this.metrics = metrics;
        }

        Metrics getCurrentMetrics() {
            return metrics;
        }
    }

    private static class Reading {}
    private static class Metrics {}
}
```
