    // Null encryption case
    if (!strcmp(mode, "NULL")) {
        *num_ciphers = 1;
        EVP_CIPHER** null_enc = malloc(*num_ciphers * sizeof(EVP_CIPHER*));

        for (int i = 0; i < 4; ++i) {
            if (!strcmp("NULL", mode_strings[i])) {
                *null_enc = modes[i];
            }
        }

        return null_enc;
