typedef struct {
    int UE_ID;
    // Assuming DL_CCCH_MSG1_T is a large structure with random data, it will be omitted here for brevity
} LTE_DL_FRAME_MSG;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static LTE_DL_FRAME_MSG *messages = NULL;
static size_t messagesSize = 0;  // Current allocated size
static size_t messagesCount = 0;  // Number of valid elements in array

void addMessage(LTE_DL_FRAME_MSG msg) {
    pthread_mutex_lock(&mutex);

    if (messagesCount == messagesSize) {
        // Double the allocated size on each reallocation to minimize overhead
        messages = realloc(messages, 2 * messagesSize * sizeof(*messages));

        if (!messages) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        printf("Array resized to %zu\n", messagesSize);

        // Update the new size
        messagesSize *= 2;
    }

    // Add the message and increment counter
    messages[messagesCount++] = msg;

    pthread_mutex_unlock(&mutex);
}
```

As for the Python function, here's a basic start which handles file hashing:

```python
import hashlib
import os
from typing import List

def compute_hash(file_path: str) -> str:
    # Set buffer size to 4096 bytes (or 4 KB) for memory efficiency
    BUF_SIZE = 4096

    md5 = hashlib.md5()

    try:
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(BUF_SIZE)

                if not data:
                    break

                md5.update(data)
    except FileNotFoundError:
        print(f'File {file_path} does not exist')
        return None
    except Exception as e:
        print(f'An error occurred while reading file {file_path}:', str(e))
        return None

    return md5.hexdigest()
```
This function reads the file in chunks to avoid excessive memory usage. It also catches and handles exceptions that may occur during file access or hashing, such as a missing file and any unexpected error.
