class ConfigurationManager {
private:
    // map from UE id to its associated context
    std::map<std::string, UeContext*> ueContexts_;
    pthread_mutex_t mutex_;  

public:
    void addUeContext(const std::string& ueId) {
        pthread_mutex_lock(&mutex_);
        if (ueContexts_.find(ueId) == ueContexts_.end()) {
            UeContext* ctx = new UeContext();
            ctx->ueId = ueId;
            ueContexts_[ueId] = ctx;
        }
        pthread_mutex_unlock(&mutex_);
    }

    void updateUeContext(const std::string& ueId, const UeContext& newCtx) {
        pthread_mutex_lock(&mutex_);
        if (ueContexts_.find(ueId) != ueContexts_.end()) {
            *ueContexts_[ueId] = newCtx; // replace the old context
        } else {
            addUeContext(newCtx.ueId);
        }
        pthread_mutex_unlock(&mutex_);
    }

    void removeUeContext(const std::string& ueId) {
        pthread_mutex_lock(&mutex_);
        if (ueContexts_.find(ueId) != ueContexts_.end()) {
            delete ueContexts_[ueId]; // free the memory
            ueContexts_.erase(ueId);  // remove from map
        }
        pthread_mutex_unlock(&mutex_);
    }
};
