    public VehicleStateManager() {
        this.vehicleStates = new ConcurrentHashMap<>();
    }

    // Adds a new vehicle state to the map
    public void addVehicle(String id, GeoCoordinate coordinate) {
        VehicleState vehicleState = new VehicleState(id, coordinate);
        this.vehicleStates.putIfAbsent(id, vehicleState);
