Here's a simple example of a dynamic array in C that is thread-safe (using pthread mutex):
```c
#include <pthread.h>
#define INIT_SIZE 10
typedef struct {
    pthread_mutex_t lock;
    void **array;
    int size;
    int capacity;
} DynamicArray;

DynamicArray *create_dynamic_array() {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    da->array = malloc(sizeof(void *) * INIT_SIZE);
    da->size = 0;
    da->capacity = INIT_SIZE;
    return da;
}

void add_element(DynamicArray *da, void *elem) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        da->capacity *= 2;
        da->array = realloc(da->array, sizeof(void *) * da->capacity);
    }
    da->array[da->size++] = elem;
    pthread_mutex_unlock(&da->lock);
}
```
