["Here is an example solution in C language. It involves structs for UE context, MAC entities and PDCP statistics with functions to manage these data structures efficiently. Note that this is just a basic template and needs more detailed implementation as per your actual requirements.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Add fields for MAC entities here
} MacEntity;

typedef struct {
    // Add fields for PDCP statistics here
} PdcpStatistics;

typedef struct {
    int UE_ID;
    pthread_mutex_t mutex;  // Mutex to handle thread-safe operations
    MacEntity* entities;   // Dynamic array of MAC entities
    int entityCount;       // Number of currently allocated MAC entities
    PdcpStatistics stats;  // PDCP statistics for this UE context
} UeContext;

// Global dynamic array of UE contexts
UeContext** ueContexts = NULL;
int ueContextCount = 0;
pthread_mutex_t globalMutex = PTHREAD_MUTEX_INITIALIZER;

void addEntityToUeContext(UeContext* context, MacEntity entity) {
    pthread_mutex_lock(&context->mutex);  // Lock to handle thread-safe operations

    context->entities = realloc(context->entities, (context->entityCount + 1) * sizeof(MacEntity));
    if (!context->entities) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&context->mutex);  // Unlock mutex before returning
        return;
    }

    context->entities[context->entityCount++] = entity;  // Add new MAC entity to array

    pthread_mutex_unlock(&context->mutex);  // Unlock mutex after operation
}

void addUeContext(int UE_ID) {
    pthread_mutex_lock(&globalMutex);  // Lock global mutex before modifying the array of UE contexts

    ueContexts = realloc(ueContexts, (ueContextCount + 1) * sizeof(UeContext*));
    if (!ueContexts) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&globalMutex);  // Unlock global mutex before returning
        return;
    }

    UeContext* context = malloc(sizeof(UeContext));
    if (!context) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&globalMutex);  // Unlock global mutex before returning
        return;
    }

    context->UE_ID = UE_ID;
    context->entityCount = 0;
    context->entities = NULL;
    pthread_mutex_init(&context->mutex, NULL);  // Initialize mutex for thread safety

    ueContexts[ueContextCount++] = context;  // Add new UE context to array

    pthread_mutex_unlock(&globalMutex);  // Unlock global mutex after operation
}

void cleanup() {
    for (int i = 0; i < ueContextCount; ++i) {
        UeContext* context = ueContexts[i];

        pthread_mutex_destroy(&context->mutex);  // Destroy mutex
        free(context->entities);  // Free memory allocated for MAC entities
    }

    free(ueContexts);  // Free memory allocated for UE contexts array
}
```
This code provides the basic structure for managing a dynamic array of LTE UE context structures. It includes functions to add new UE contexts and add new MAC entities to existing UE contexts, ensuring thread-safe operations by locking mutexes before performing operations. Also included are error handling measures to handle memory allocation failures. 

