```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int Dev_ID;
    double* readings;
    size_t num_readings;
    int connectivity_metrics[3]; // Example: [latency, jitter, packet loss]
} DeviceContext;

DeviceContext** devices = NULL;
size_t num_devices = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_reading(int Dev_ID, double reading) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_devices; ++i) {
        if (devices[i]->Dev_ID == Dev_ID) {
            devices[i]->readings = realloc(devices[i]->readings, sizeof(double) * (devices[i]->num_readings + 1));
            if (!devices[i]->readings) {
                pthread_mutex_unlock(&lock);
                perror("Failed to allocate memory for readings");
                exit(EXIT_FAILURE);
            }
            devices[i]->readings[devices[i]->num_readings] = reading;
            ++devices[i]->num_readings;
            pthread_mutex_unlock(&lock);
            return;
        }
    }
    // Handle case where Dev_ID is not found in devices array.
}

void add_device(int Dev_ID) {
    pthread_mutex_lock(&lock);
    DeviceContext** new_devices = realloc(devices, sizeof(DeviceContext*) * (num_devices + 1));
    if (!new_devices) {
        pthread_mutex_unlock(&lock);
        perror("Failed to allocate memory for devices");
        exit(EXIT_FAILURE);
    }
    DeviceContext* new_device = malloc(sizeof(DeviceContext));
    if (!new_device) {
        pthread_mutex_unlock(&lock);
        perror("Failed to allocate memory for a device");
        exit(EXIT_FAILURE);
    }
    new_device->Dev_ID = Dev_ID;
    new_device->readings = NULL;
    new_device->num_readings = 0;
    for (size_t i = 0; i < 3; ++i) {
        new_device->connectivity_metrics[i] = 0; // Initialize connectivity metrics to 0.
    }
    devices = new_devices;
    devices[num_devices++] = new_device;
    pthread_mutex_unlock(&lock);
}

void update_network_connectivity(int Dev_ID, int latency, int jitter, int packet_loss) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_devices; ++i) {
        if (devices[i]->Dev_ID == Dev_ID) {
            devices[i]->connectivity_metrics[0] = latency;
            devices[i]->connectivity_metrics[1] = jitter;
            devices[i]->connectivity_metrics[2] = packet_loss;
            pthread_mutex_unlock(&lock);
            return;
        }
    }
    // Handle case where Dev_ID is not found in devices array.
}

void cleanup() {
    for (size_t i = 0; i < num_devices; ++i) {
        free(devices[i]->readings);
        free(devices[i]);
    }
    free(devices);
}
```

This basic implementation only adds a single device and a single reading, but it should give you an idea of how to structure your data and handle thread-safety with pthread_mutex_lock() and pthread_mutex_unlock(). 

