int compare(const void * a, const void * b) 
{
   return ( ((NFAPI_CRC_INDICATION_PDU_T*)a)->RNTI - ((NFAPI_CRC_INDICATION_PDU_T*)b)->RNTI );
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(int N, int* outSize) 
{
    if (N > 1024){
        printf("Error: List size exceeds maximum limit!\n");
        *outSize = 0;
        return NULL;
    }

    srand((unsigned int)time(NULL)); // seed the random number generator
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduList == NULL) {
        printf("Error: Unable to allocate memory!\n");
        *outSize = 0;
        return NULL;
    }

    for (int i = 0; i < N; ++i){
        pduList[i].RNTI = rand(); // generate a random number for RNTI

        if(i > 0 && pduList[i-1].RNTI == pduList[i].RNTI) {
            i--; // to ensure no two consecutive structures have the same RNTI value
        }
    }

    qsort(pduList, N, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare); // sorting the list by RNTI

    *outSize = N;
    return pduList;
}
```

