    private Queue<Connection> availableConnections = new LinkedList<>();
    private List<Connection> usedConnections = new ArrayList<>();
    private int maxSize;

    public DatabasePool(int initialSize, int maxSize) {
        this.maxSize = maxSize;

        for (int i = 0; i < initialSize; i++) {
            // create connections...
            availableConnections.add(connection);
        }
    }

    public Connection getConnection() throws Exception {
        synchronized (availableConnections) {
            if (availableConnections.isEmpty()) {
                if (usedConnections.size() < maxSize) {
                    // create connections...
                    usedConnections.add(connection);
                    return connection;
                } else {
                    throw new Exception("No available connections");
                }
            } else {
                Connection connection = availableConnections.remove();
                usedConnections.add(connection);
                return connection;
            }
        }
    }

    public void releaseConnection(Connection connection) {
        synchronized (usedConnections) {
            if (usedConnections.contains(connection)) {
                usedConnections.remove(connection);
                availableConnections.add(connection);
            } else {
                throw new IllegalArgumentException("Connection not in use");
            }
        }
    }
