#include <stdio.h>
#include <json-c/json.h>

void parseConfigFile(char* inputFileName, char* outputFileName) {
    FILE *fp;
    struct json_object *parsed_json;
    size_t fileSize;
    char *fileContents;

    fp = fopen(inputFileName, "rb"); // 'b' needed to prevent Windows from replacing \n with \r\n
    if (!fp) {
        printf("Failed to open %s for reading", inputFileName);
        return;
    }

    fseek(fp, 0, SEEK_END);
    fileSize = ftell(fp);
    rewind(fp);

    if (fileSize > 0) {
        fileContents = malloc(fileSize + 1);

        if (!fileContents) {
            printf("Failed to allocate memory for %s", inputFileName);
            return;
        }

        fread(fileContents, fileSize, 1, fp);
        fileContents[fileSize] = 0; // null-terminator needed for json_tokener_parse()

        parsed_json = json_tokener_parse(fileContents);
        if (parsed_json == NULL) {
            printf("Failed to parse %s", inputFileName);
            free(fileContents);
            return;
        }

        // Now you can process the JSON object parsed_json and write it to output file.
    } else {
        printf("%s is empty", inputFileName);
    }

    fclose(fp);
}
``` 

