                }
            } catch (Exception $e) {
                // Handle exceptions, like logging them or providing user-friendly error messages
                return $response->withStatus(500);
            }
        }
        $request = $request->withAttribute('access_token', $session['access_token']);
        return $next($request, $response);
    });

    // Define route to handle file uploads
    $app->post('/upload', function (Request $request, Response $response) use ($fileUploadDir) {
        $files = $request->getUploadedFiles();
        if (empty($files['userFile'])) {
            return $response->withStatus(400);
        }
        $originalFilename = pathinfo($files['userFile']->getClientFilename(), PATHINFO_FILENAME); // Get original filename without extension
        $extension = pathinfo($files['userFile']->getClientFilename(), PATHINFO_EXTENSION); // Get file extension
        $uniqueId = Uuid::uuid4()->toString(); // Generate a unique identifier for the session
        $newFileName = $originalFilename . '.' . $extension . '.' . $uniqueId; // Append unique identifier to filename
        try {
            $files['userFile']->moveTo($fileUploadDir . DIRECTORY_SEPARATOR . $newFileName);
            return $response->withJson(['success' => true]);
        } catch (Exception $e) {
            // Handle exceptions, like logging them or providing user-friendly error messages
            return $response->withStatus(500);
        }
    });

    $app->run();
}
```
