```cpp
#include <boost/asio.hpp>
#include <string>
#include <unordered_map>
#include <chrono>
#include <thread>
#include <mutex>
#include <iostream>
#include <memory>

// Simple cache entry, with data and expiration time.
struct CacheEntry {
  std::string data;
  std::chrono::system_clock::time_point expireTime;
};

class CacheManager {
public:
    // Constructor to initialize the manager.
    CacheManager() : ioService(), work(new boost::asio::io_service::work(ioService)) {}

    // Destructor to stop all threads.
    ~CacheManager() { 
        ioService.stop(); 
        for (auto& thread : workerThreads) {
            if (thread->joinable()) {
                thread->join();
            }
        }
    }

    // Start a specified number of worker threads.
    void start(int numWorkers = 1) {
        for (int i=0; i < numWorkers; ++i) {
            std::unique_ptr<std::thread> newThread(new std::thread([this](){ ioService.run(); }));
            workerThreads.push_back(std::move(newThread));
        }
    }

    // Asynchronously set a key-value pair with an expiration time.
    void asyncSet(const std::string& key, const std::string& value, int secondsToExpire) {
        auto expireTime = std::chrono::system_clock::now() + std::chrono::seconds(secondsToExpire);

        // Use a lock_guard to ensure thread safety.
        std::lock_guard<std::mutex> guard(cacheMutex);

        CacheEntry entry {value, expireTime};
        cache[key] = entry;
    }

    // Asynchronously get the value associated with a key. Returns an empty string if not found or expired.
    std::string asyncGet(const std::string& key) {
        std::lock_guard<std::mutex> guard(cacheMutex);

        auto it = cache.find(key);
        if (it != cache.end() && it->second.expireTime > std::chrono::system_clock::now()) {
            return it->second.data;
        } else {
            // If not found or expired, remove the entry from the cache.
            cache.erase(it);
            return "";
        }
    }
private:
  boost::asio::io_service ioService;
  std::unique_ptr<boost::asio::io_service::work> work;
  std::vector<std::unique_ptr<std::thread>> workerThreads;

  std::unordered_map<std::string, CacheEntry> cache;
  std::mutex cacheMutex;
};
```
