#include "lte_dl_frame_msg.h"  // assuming you have a LTE_DL_FRAME_MSG structure defined here
class DynamicArrayManager {
private:
    std::vector<LTE_DL_FRAME_MSG> buffer;
    size_t capacity;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> ready{false};
public:
    DynamicArrayManager(size_t capacity) : capacity(capacity), buffer() {}

    void initAndReallocate(LTE_DL_FRAME_MSG &msg) {
        std::unique_lock<std::mutex> lock(mtx);
        if (buffer.size() == capacity) return;
        buffer.push_back(msg);
        cv.notify_all();
    }

    void waitForReady(){
        std::unique_lock<std::mutex> lock(mtx);
        while(!ready){
            cv.wait(lock);
        }
    }
};
