    hash = sha256()
    for chunk in iter(lambda: audio_stream.read(4096), b""):
        hash.update(chunk)

    # Check if the file exceeds 128 characters without extension
    filename, ext = os.path.splitext(audio_stream.name)
    if len(filename + ext) > 128:
        logging.error("Filename is too long")
        return {"Error": "Invalid filename"}

    try:
        # Metadata and streaming data processing with cloud service
        analysis = requests.post('https://audio-processing-service.com/analyze', json={
            'codec': codec,
            'bitrate': bitrate,
            'hash': hash.hexdigest()
        }, headers=headers)
    except Exception as e:
        logging.error(f"Error during cloud processing: {str(e)}")
        return {"Error": "Cloud service error"}

    if analysis.status_code != 200:
        logging.error("Unexpected response from cloud service")
        return {"Error": "Cloud service error"}

    # Lock to avoid race conditions
    with lock:
        result = {
            'metadata': analysis.json()['metadata'], 
            'sample_rates': analysis.json()['sample_rates'],
            'compression_ratios': analysis.json()['compression_ratios']}

    return result
```
