public class DirectoryFileProcessor {
    private static Log log = LogFactory.getLog(DirectoryFileProcessor.class);

    public Map<String, Long> processDirectoriesAsync(List<Path> paths) {
        ConcurrentMap<String, AtomicLong> directorySizes = new ConcurrentHashMap<>();

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (Path path : paths) {
            executor.execute(() -> {
                String dirName = path.getParent().toString();

                directorySizes.putIfAbsent(dirName, new AtomicLong());
                directorySizes.get(dirName).addAndGet(path.toFile().length());
            });
        }

        executor.shutdown();

        try {
            while (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                // Wait for termination of tasks or retry after 10 seconds if some are still running
            }
        } catch (InterruptedException e) {
            log.error("Async directory processing interrupted", e);
        }

        Map<String, Long> summary = new HashMap<>();

        for (Map.Entry<String, AtomicLong> entry : directorySizes.entrySet()) {
            summary.put(entry.getKey(), entry.getValue().longValue());
        }

        return summary;
    }

