UserProfile* memPool[10000];
int freeIndex = 0;

void* allocateFromMemPool() {
    pthread_mutex_lock(&mutex);
    if (freeIndex < 10000) {
        return &memPool[freeIndex++];
    } else {
        printf("Memory Pool is full!\n");
        exit(EXIT_FAILURE);  // Returns a special error indicator
    }
    pthread_mutex_unlock(&mutex);
}

void deallocateFromMemPool(UserProfile* profile) {
    // Implement deallocation in memPool using binary search, ensuring the array remains sorted for efficient allocation and deallocation.
    int i = 0;
    pthread_mutex_lock(&mutex);
    while (i < freeIndex && memPool[i] != profile) {
        i++;
    }
    if (i == freeIndex) {
        printf("Invalid deallocation!\n");
        exit(EXIT_FAILURE);  // Returns a special error indicator
    } else {
        for (; i < freeIndex - 1; i++) {
            memPool[i] = memPool[i + 1];
        }
        freeIndex--;
    }
    pthread_mutex_unlock(&mutex);
