void addFlow(NetworkInterface* ni, char *flow) {
    pthread_mutex_lock(&ni->mutex);

    if (ni->flowCount < MAX_FLOWS) {
        ni->flows[ni->flowCount++] = strdup(flow);
    } else {
        // Handle error, array is full
    }

    pthread_mutex_unlock(&ni->mutex);
}

void removeFlow(NetworkInterface* ni, char *flow) {
    pthread_mutex_lock(&ni->mutex);

    for (int i = 0; i < ni->flowCount; ++i) {
        if (strcmp(ni->flows[i], flow) == 0) {
            free(ni->flows[i]);
            ni->flows[i] = ni->flows[--ni->flowCount];
            break;
        }
    }

    pthread_mutex_unlock(&ni->mutex);
}

void destroyInterface(NetworkInterface* ni) {
    for (int i = 0; i < ni->flowCount; ++i) {
        free(ni->flows[i]);
    }

    pthread_mutex_destroy(&ni->mutex);
    free(ni);
}
