    if (arr->size == arr->capacity) {
        start = clock();
        arr->capacity *= 2;
        arr->contexts = resize(arr->contexts, sizeof(ue_context) * arr->size, 
                               sizeof(ue_context) * arr->capacity);
        end = clock();
        cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    }
    arr->contexts[arr->size++] = context;
    pthread_mutex_unlock(&lock);
}
