    if (!ue) return NULL;

    ue->UE_ID = strdup(UE_ID);
    ue->maxMacEntities = initialCapacity;
    ue->numMacEntities = 0;
    ue->macEntities = malloc(sizeof(MACEntity*) * initialCapacity);

    if (!ue->UE_ID || !ue->macEntities) {
        freeUEContext(ue);
        return NULL;
    }

    // Initialize other fields...

    return ue;
}

void freeUEContext(UEContext* ue) {
    if (!ue) return;

    for (size_t i = 0; i < ue->numMacEntities; ++i) {
        free(ue->macEntities[i]);
    }

    free(ue->UE_ID);
    free(ue->macEntities);
    free(ue);
}

int addMACEntity(UEContext* ue, MACEntity* entity) {
    if (ue->numMacEntities >= ue->maxMacEntities) {
        size_t newCapacity = ue->maxMacEntities * 2; // Double the capacity on overflow
        MACEntity** newArray = realloc(ue->macEntities, sizeof(MACEntity*) * newCapacity);

        if (!newArray) return -1; // Reallocation failed

        ue->maxMacEntities = newCapacity;
        ue->macEntities = newArray;
    }

    ue->macEntities[ue->numMacEntities++] = entity;

    return 0; // Success
}
