// Function to add an element at the end of a linked list. 
void append(Node** head, int value) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->value  = value;
    new_node->next = NULL;

    if (*head == NULL) {
       *head = new_node;
       return;
    } 

    Node *last = *head;
    while (last->next != NULL) {
        last = last->next;
    }

    last->next = new_node;
}

int main() {
    // Assume we receive data from network in the following format
    int receivedData[5] = {1, 2, 3, 4, 5};

    Node *head = NULL;
    for (int i = 0; i < 5; i++) {
        append(&head, receivedData[i]);
    }

    processData(&head);

    // Free the list after use
    while(head != NULL){ 
       Node* temp = head;
       head = head->next;
       free(temp);
    }

    return 0;
}
```

