["```c
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_CONTEXTS 500
#define MIN_CONTEXTS 50
#define POOL_SIZE 1024*1024 // 1 MB memory pool

typedef struct BLEPeripheral {
    int id;
} BLEPeripheral;

typedef struct ConnectionStatistics {
    double avgLatency;
    int numConnections;
} ConnectionStatistics;

typedef struct DeviceContext {
    pthread_mutex_t lock;
    char Dev_ID[32];
    BLEPeripheral peripherals[1024]; // assuming max 1k devices per context
    int numDevices;
    ConnectionStatistics stats;
} DeviceContext;

DeviceContext contexts[MAX_CONTEXTS];
char memoryPool[POOL_SIZE];
int currentMemory = 0;
pthread_mutex_t poolLock = PTHREAD_MUTEX_INITIALIZER;

void* allocate(size_t size) {
    pthread_mutex_lock(&poolLock);
    if (currentMemory + size > POOL_SIZE) {
        pthread_mutex_unlock(&poolLock);
        return NULL; // Out of memory
    }
    void* block = &memoryPool[currentMemory];
    currentMemory += size;
    pthread_mutex_unlock(&poolLock);
    return block;
}

void deallocate(size_t size) {
    pthread_mutex_lock(&poolLock);
    if (currentMemory < size) {
        pthread_mutex_unlock(&poolLock);
        return; // Nothing to deallocate
    }
    currentMemory -= size;
    pthread_mutex_unlock(&poolLock);
}

int addDeviceContext(char* Dev_ID, int numDevices) {
    static int contextCount = 0;
    if (contextCount >= MAX_CONTEXTS) return -1; // Max contexts reached

    size_t contextSize = sizeof(DeviceContext);
    void* block = allocate(contextSize);
    if (!block) return -2; // Out of memory

    DeviceContext* context = (DeviceContext*)block;
    pthread_mutex_init(&context->lock, NULL);
    strncpy(context->Dev_ID, Dev_ID, sizeof(context->Dev_ID) - 1);
    context->numDevices = numDevices;

    contexts[contextCount++] = *context;
    return contextCount - 1; // Return new context ID
}

int addBLEPeripheral(int contextId, BLEPeripheral* peripheral) {
    if (contextId >= MAX_CONTEXTS || contextId < 0) return -1; // Invalid context

    DeviceContext* context = &contexts[contextId];
    pthread_mutex_lock(&context->lock);
    if (context->numDevices >= 1024) {
        pthread_mutex_unlock(&context->lock);
        return -2; // Max devices reached
    }

    context->peripherals[context->numDevices++] = *peripheral;
    pthread_mutex_unlock(&context->lock);
    return 0; // Success
}

// Similar approach to addBLEPeripheral for updateStats and logging functions.
