            std::cout << "Buffer already initialized, skipping initialization\n";
        }

        cv.notify_all(); // Notify all waiting threads that buffer is ready
    }

    void addMessage(const LTE_DL_FRAME_MSG& msg) {
        std::unique_lock<std::mutex> lock(mtx);

        if (!initialized) {
