```python
import hashlib
import os
import requests
from time import sleep
import threading
import yaml
import functools

lock = threading.Lock()
cache = {}  # Basic cache to store api responses

def read_in_chunks(file, chunk_size=1024*50):
    while True:
        data = file.read(chunk_size)
        if not data:
            break
        yield data

def get_from_api():
    # Simulated API call with exponential backoff
    retry = 0
    resp = None
    while retry < 5:
        try:
            sleep(2**retry)  # Exponential backoff
            resp = requests.get('https://some-external-api.com')
            if resp.status_code == 200:
                return resp.json()
        except requests.exceptions.RequestException as e:
            print(e)
            retry += 1
    raise ValueError("API failed after multiple attempts")

def get_metadata():
    with lock:  # Thread-safe access to the cache
        if 'api_resp' not in cache:
            cache['api_resp'] = get_from_api()
        return cache['api_resp']

@functools.lru_cache(maxsize=10)
def fetch_metadata():
    # Implement caching strategy here, LRU cache used as example
    return get_metadata()

# Load yaml config file and reload on changes
with open("config.yaml", 'r') as stream:
    try:
        config = yaml.safe_load(stream)
    except yaml.YAMLError as exc:
        print(exc)

def calculate_hash(filepath):
    hasher = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for data in read_in_chunks(f):
            hasher.update(data)
    return hasher.hexdigest()
```

