sem_t sem;  // Semaphore to control access to shared resources
int fd = -1;  // File descriptor for the file
off_t fileSize = 0;  // Size of the file
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex to control access to shared resources
int chunkSize = 4096;  // Default chunk size for reading file in chunks
unsigned int numThreads = 4;  // Number of worker threads, can be adjusted according to system configuration
char* logService = NULL;  // External logging service URL
int logLevel = 2;  // Logging level (0-3) for different verbosity levels
char* logFormat = "JSON";  // Log format (plain text or JSON)

