NFAPI_CRC_INDICATION_PDU_T createPDUTemplate();
RX_UE_INFORMATION_TAG createUEInfoTemplate();
CRC_INDICATION_REL8_TAG createCRCTagTemplate();
void logEvent(char* event, int level);
int openFileAndGetSize(char* filename);
void closeFile();

void* workerThread(void *arg) {
    off_t start = (off_t) arg;
    off_t end = start + chunkSize > fileSize ? fileSize : start + chunkSize;

    processChunk(start, end);
    return NULL;
}

void processChunk(off_t start, off_t end) {
    int retries = 0;
    while (retries < 3) {  // Set the maximum number of retries as per requirement
        pthread_mutex_lock(&mutex);
        lseek(fd, start, SEEK_SET);
        char* buffer = malloc(end - start + 1);  // Allocate memory for chunk

        if (read(fd, buffer, end - start) != end - start) {  // Check if read operation was successful
            pthread_mutex_unlock(&mutex);
            free(buffer);
            retries++;
            logEvent("I/O error occurred while reading the file", 0);
        } else {
            // Process the chunk here, creating and populating NFAPI_CRC_INDICATION_PDU_T structures from the buffer
            pthread_mutex_unlock(&mutex);
            free(buffer);
            retries = 3;  // Break the loop on successful read operation
        }
    }

    if (retries == 3) {
        logEvent("Failed to process chunk after maximum retries", 0);
    } else {
        sem_post(&sem);  // Signal that a chunk has been processed successfully
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: ./a.out filename\n");
        return 1;
    }

    if (!openFileAndGetSize(argv[1])) {
        logEvent("Failed to open the file", 0);
        return 1;
    }

    sem_init(&sem, 0, numThreads);  // Initialize semaphore with value equal to number of threads
    pthread_t threads[numThreads];
    for (int i = 0; i < fileSize; i += chunkSize) {
        sem_wait(&sem);  // Wait until a thread becomes available

        off_t start = i;
        if (pthread_create(&threads[i % numThreads], NULL, workerThread, (void*)start)) {
            logEvent("Failed to create a new thread", 0);
            return 1;
        }
    }

    for (int i = 0; i < fileSize; i += chunkSize) {
        pthread_join(threads[i % numThreads], NULL);  // Wait for all threads to finish
    }

    closeFile();
    sem_destroy(&sem);
    return 0;
}
```
