```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Transaction {
    char date[11]; // assuming dates in the format DD/MM/YYYY
    int amount;
} Transaction;

int findMax(Transaction *transactions, int size) {
    int max = 0;
    for (int i = 0; i < size; ++i) {
        if (transactions[i].amount > max) {
            max = transactions[i].amount;
        }
    }
    return max;
}

void processCSV(char *filename) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    char line[1024];
    Transaction *transactions = NULL;
    int count = 0;
    while (fgets(line, 1024, file)) {
        // Assume each line contains a date and an amount.
        Transaction t;
        sscanf(line, "%[^,],%d", &t.date, &t.amount);

        transactions = realloc(transactions, (count + 1) * sizeof(Transaction));

        if (transactions == NULL) {
            printf("Error allocating memory.\n");
            return;
        }

        transactions[count++] = t;
    }

    fclose(file);

    int total = 0;
    for (int i = 0; i < count; ++i) {
        total += transactions[i].amount;
    }
    printf("Total transaction volume: %d\n", total);

    int max = findMax(transactions, count);
    printf("Maximum transaction amount: %d\n", max);

    free(transactions);
}
```
In the `processCSV` function, we read each line of the CSV file and store it in a dynamically allocated array. We also calculate the total transaction volume as we go along. If there's any error opening the file or allocating memory, we print an error message and return early. After processing all lines, we find the maximum transaction amount by calling the `findMax` helper function and print it out. Finally, we free the dynamically allocated array of transactions to prevent a memory leak.
