['```csharp
public List<Dictionary<string, object>> ValidateAndFetchOAuthTokenData(string connectionString, string schemaName, string json)
{
    var token = JsonConvert.DeserializeObject<dynamic>(json);

    if (token == null || !ValidateToken(token)) 
        return false;

    using (var connection = new SqlConnection(connectionString))
    {
        connection.Open();
        var command = new SqlCommand("SELECT * FROM " + schemaName, connection);
        var reader = command.ExecuteReader();

        var results = new List<Dictionary<string, object>>();

        while (reader.Read())
        {
            var row = new Dictionary<string, object>();

            for(var i=0; i < reader.FieldCount; i++) 
                row[reader.GetName(i)]  = reader.IsDBNull(i) ? null : reader[i];

            results.Add(row);
        }

        return results;
    }
}

private bool ValidateToken(dynamic token)
{
    if (token == null || token["access_token"] == null || token["expires_in"] == null || token["token_type"] == null)
        return false;

    var accessToken = token.access_token as string;
    var expiresIn = int.TryParse(token.expires_in, out var expiresInValue);

    if (string.IsNullOrEmpty(accessToken) || !expiresIn || expiresInValue < 0 || token.token_type?.ToString() != "Bearer") 
        return false;

    return true;
}
```
