    UEState** ueStates = (UEState**)calloc(numUEs, sizeof(UEState*));

    if (!ueStates) {
        fprintf(stderr, "Memory allocation failed!\n");
        return NULL;
    }

    for (size_t i = 0; i < numUEs; ++i) {
        ueStates[i] = (UEState*)malloc(sizeof(UEState));

        if (!ueStates[i]) {
            fprintf(stderr, "Memory allocation failed for UE %zu!\n", i);
            // Free any previously allocated memory before returning NULL.
            for (; i > 0; --i) free(ueStates[i - 1]);
            free(ueStates);
            return NULL;
        }
    }

    pthread_mutex_unlock(&ueListLock); // Unlock the mutex to allow other threads to access UEList.
    return ueStates;
}
