['Here's an outline of how you could structure your code to implement this task in Java:

```java
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.locks.*;

public class LogFileProcessor {
    private static final int CHUNK_SIZE = 50 * 1024 * 1024; // 50 MB in bytes

    private ReadWriteLock lock = new ReentrantReadWriteLock();
    private MessageDigest md;

    public LogFileProcessor() {
        try {
            this.md = MessageDigest.getInstance("SHA-256");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    // Stream and process a large log file in chunks to calculate its SHA-256 hash
    public String calculateHash(String path) throws Exception {
        try (InputStream is = Files.newInputStream(Paths.get(path))) {
            byte[] buffer = new byte[CHUNK_SIZE];
            int bytesRead;

            lock.writeLock().lock();
            try {
                while ((bytesRead = is.read(buffer)) != -1) {
                    md.update(Arrays.copyOfRange(buffer, 0, bytesRead));

                    // Progress indicator every 50 MB processed
                    if (is.available() % CHUNK_SIZE == 0) {
                        System.out.println("Processed " + (CHUNK_SIZE - is.available()) / 1024 / 1024 + "MB");
                    }
                }
            } finally {
                lock.writeLock().unlock();
            }

            return bytesToHex(md.digest()); // Return hexadecimal representation of the hash
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }
}
```
