typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    time_t timestamp;
    int sequenceNumber;
    char latencyFlag;
} Node;

// List structure
typedef struct List {
    Node *head, *tail;
    pthread_mutex_t mutex;
    size_t maxSize;
    size_t currSize;
    // ...
} List;

List* createList(size_t maxSize) {
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL;  // allocation error handling

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);  // thread safety
    list->maxSize = maxSize;
    list->currSize = 0;
    // ...
    return list;
}

int addToList(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list == NULL || &data == NULL) return -1;  // null pointer check

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) return -2;  // allocation error handling

    pthread_mutex_lock(&list->mutex);  // thread safety

    if (list->currSize >= list->maxSize) {
        pthread_mutex_unlock(&list->mutex);  // thread safety
        return -3;  // size limit exceeded error handling
    }

    newNode->data = data;
    newNode->next = NULL;
    newNode->timestamp = time(NULL);
    newNode->sequenceNumber = 0;  // replace this with your sequence number logic
    newNode->latencyFlag = 1;  // replace this with your latency flag logic

    if (list->tail == NULL) {
        list->head = list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->currSize++;  // increment size count

    pthread_mutex_unlock(&list->mutex);  // thread safety

    return 0;
}
```

In this code, the `createList` function initializes a new list with a given maximum size limit. The `addToList` function adds a new item to the end of the list after validating inputs and checking if the maximum size is not exceeded, while ensuring thread safety. It also computes the timestamp for each node.

Please replace placeholder fields like `RX_UE_INFORMATION_TAG` with your actual structure field data. The latency flag can be computed based on your requirements. You may need to integrate the logging framework and implement periodic compression of the list according to your requirements as well. Please note that this is a basic implementation. Actual code will depend on your specific use case, error handling strategy, thread safety needs, etc.
