    UE_context* newNode = (UE_context*) malloc(sizeof(UE_context));
    newNode->UE_ID = UE_ID;
    newNode->MAC_entities = MAC_entities;
    newNode->PDCP_statistics = NULL; // Initialize PDCP statistics as NULL, replace with actual initialization if needed

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

// Function to cleanup all UE contexts when the program ends
void cleanUpUEContexts() {
    pthread_mutex_lock(&lock);

    UE_context *current = head, *next;
    while (current != NULL) {
        next = current->next;

        // Clean up each UE context here...
        free(current);

        current = next;
    }

    pthread_mutex_unlock(&lock);
}

int main() {
