```python
import os
import time
import yaml
from hashlib import sha256
import requests

# Load external dependencies
vendor_autoloader = __import__('vendor_module')

def load_config(filepath):
    with open(filepath, 'r') as stream:
        try:
            return yaml.safe_load(stream)
        except yaml.YAMLError as exc:
            print(exc)

# Load and update configuration dynamically
CONFIG = load_config('config.yaml')

def api_call_with_retry(url, max_retries=5):
    for i in range(max_retries):
        try:
            response = requests.get(url)
            if response.status_code == 200:
                return response.json()
            else:
                print('API call failed with status code:', response.status_code)
        except Exception as e:
            print("Exception occurred: ", str(e))

        # Exponential backoff
        time.sleep((2 ** i) + 0.5)
    return None

# API endpoint
metadata_url = CONFIG['api']['metadata']

def get_metadata():
    metadata = api_call_with_retry(metadata_url)
    if metadata:
        # Do something with the metadata
        pass

def calculate_sha256(filepath, chunk_size=1024*1024):
    h  = sha256()

    with open(filepath, 'rb') as file:
        processed = 0

        while True:
            data = file.read(chunk_size)

            if not data:
                break

            h.update(data)
            processed += len(data)

            if processed % (50 * 1024*1024) == 0: # Update every 50 MB
                print('Processed:', str(processed), 'bytes')

    return h.hexdigest()
```
