from threading import Thread
from random import randint
import logging

class ApplicationLifecycleManager:
    def __init__(self, file_paths, params, virtual_character):
        self.file_paths = file_paths
        self.params = json.loads(params)
        self.virtual_character = virtual_character
        self.logger = logging.getLogger(__name__)

    def start(self):
        for path in self.file_paths:
            if not os.path.isfile(path):
                self.logger.error("Invalid file path: %s", path)
                continue

            thread = Thread(target=self._process_file, args=(path,))
            thread.start()

        service_delay = randint(10, 60)
        self.logger.info("Service will start in %d seconds", service_delay)
        time.sleep(service_delay)
        self._start_stop_service()

    def _process_file(self, path):
        md5 = hashlib.md5()

        with open(path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                md5.update(chunk)

        self.logger.info("MD5 hash of file %s is %s", path, md5.hexdigest())

    def _start_stop_service(self):
        service_running = True

        while service_running:  # Simulate a service that runs for at least 10 seconds
            time.sleep(1)

            if randint(1, 60) == 1:  # Randomly decide to stop the service
                service_running = False

        self._send_message("Service stopped")

    def _send_message(self, message):
        self.logger.info("Simulated sending message: %s", message)
