#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Node* generatePDUs(int N, int verbosity) {
    srand(time(NULL));  // initialize random seed
    Node *head = NULL;
    Node *tail = NULL;

    for (int i = 0; i < N; ++i) {
        Node *newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            // log error and free all previously allocated memory
            fprintf(stderr, "Memory allocation failed\n");
            while (head != NULL) {
                Node *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        newNode->data.RNTI = rand();
        newNode->data.RX_UE_INFORMATION_TAG = rand();
        newNode->data.CRC_INDICATION_REL8_TAG = rand() % 2;

        pthread_mutex_lock(&lock);
        if (head == NULL) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
        pthread_mutex_unlock(&lock);

        if (verbosity > 0)  // log successful creation of a structure
            printf("Successfully created structure: RNTI=%d, RX_UE_INFORMATION_TAG=%d, CRC_INDICATION_REL8_TAG=%d\n", 
                    newNode->data.RNTI, newNode->data.RX_UE_INFORMATION_TAG, newNode->data.CRC_INDICATION_REL8_TAG);
    }

    return head;
}
```
