#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>

typedef struct {
    int UE_ID;
    pthread_mutex_t mutex;
    atomic_int num_macs;
    int* macs;
} UEContext;

atomic_int num_ues = 0;
pthread_mutex_t ueMutex = PTHREAD_MUTEX_INITIALIZER;
UEContext** contexts = NULL;

void addUE(int id) {
    pthread_mutex_lock(&ueMutex);
    UEContext* newUE = malloc(sizeof(UEContext));
    if (newUE == NULL) exit(1); // Handle memory allocation failure
    newUE->UE_ID = id;
    atomic_init(&newUE->num_macs, 0);
    contexts = realloc(contexts, sizeof(UEContext*) * (atomic_fetch_add(&num_ues, 1) + 1));
    if (contexts == NULL) exit(1); // Handle memory allocation failure
    pthread_mutex_init(&newUE->mutex, NULL);
    contexts[id] = newUE;
    pthread_mutex_unlock(&ueMutex);
}

void addMACToUE(int ueID, int mac) {
    UEContext* context = contexts[ueID];
    pthread_mutex_lock(&context->mutex);
    context->macs = realloc(context->macs, sizeof(int) * (atomic_fetch_add(&context->num_macs, 1) + 1));
    if (context->macs == NULL) exit(1); // Handle memory allocation failure
    context->macs[atomic_load(&context->num_macs) - 1] = mac;
    pthread_mutex_unlock(&context->mutex);
}

// Similar functions can be written for updating PDCP statistics, temporarily suspending a UE etc.
