void addLinkLayerEntity(DeviceContext* device, int entityId) {
    pthread_mutex_lock(&device->lock);

    LinkLayerEntity* newEntity = malloc(sizeof(LinkLayerEntity));
    newEntity->entity_id = entityId;
    newEntity->next = NULL;

    if (device->entities == NULL) {
        device->entities = newEntity;
    } else {
        LinkLayerEntity* current = device->entities;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEntity;
    }

    pthread_mutex_unlock(&device->lock);
}

void updateMetrics(DeviceContext* device, TransportLayerMetrics metrics) {
