}

void periodicUpdate(DeviceContext* devices[], size_t count) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    long currentTime = ts.tv_sec;
    static long lastUpdated = 0;

    if (currentTime - lastUpdated >= 10) { // Update every 10 seconds
        for (size_t i = 0; i < count; ++i) {
            TransportLayerMetrics metrics = computeMetrics(devices[i]->Dev_ID); // Implement this function based on your needs
            updateMetrics(devices[i], metrics);
        }

        lastUpdated = currentTime;
    }
}

void cleanupDeviceContext(DeviceContext* device) {
    pthread_mutex_destroy(&device->lock);

    LinkLayerEntity* entity = device->entities;
    while (entity != NULL) {
        LinkLayerEntity* next = entity->next;
        free(entity);
        entity = next;
    }

    free(device);
}
