#include <stdlib.h>
#include <pthread.h>

typedef struct Sensor {
    int id;
    // other data members...
} Sensor;

typedef struct Model {
    int id;
    // other model-related data...
} Model;

typedef struct Node {
    int nodeId;
    pthread_mutex_t mutex;
    Sensor* sensorList;
    Model* models;
} Node;

Node** nodes = NULL;
int nodeCount = 0;
pthread_mutex_t nodeMutex = PTHREAD_MUTEX_INITIALIZER;

void addSensor(int nodeId, Sensor* sensor) {
    pthread_mutex_lock(&nodeMutex);

    Node* node = NULL;
    for (int i = 0; i < nodeCount; ++i) {
        if (nodes[i]->nodeId == nodeId) {
            node = nodes[i];
            break;
        }
    }

    if (!node) {
        // Allocate new node and add to list
        node = malloc(sizeof(Node));
        node->nodeId = nodeId;
        pthread_mutex_init(&node->mutex, NULL);
        ++nodeCount;
        nodes = realloc(nodes, sizeof(Node*) * nodeCount);
        nodes[nodeCount - 1] = node;
    }

    pthread_mutex_unlock(&nodeMutex);

    // Lock per-node mutex before adding sensor
    pthread_mutex_lock(&node->mutex);
    // Add new sensor to the list of sensors here (ensure thread safety)
    // Unsafe direct modification is avoided by using separate mutexes for each node

    pthread_mutex_unlock(&node->mutex);
}

void cleanup() {
    pthread_mutex_lock(&nodeMutex);
    for (int i = 0; i < nodeCount; ++i) {
        Node* node = nodes[i];
        // Free sensor list and models here

        pthread_mutex_destroy(&node->mutex);
        free(node);
    }
    nodeCount = 0;
    free(nodes);
    nodes = NULL;

    pthread_mutex_unlock(&nodeMutex);
}
