typedef struct {
    unsigned char iv[AES_BLOCK_SIZE];
    EVP_CIPHER_CTX ctx;
} Aes256CbcContext;

// Initialize an AES-256-CBC cipher with a given password and salt, using PBKDF2 to derive the encryption key
int initializeAes256Cbc(const unsigned char* password, int passwordLength, const unsigned char* salt, int saltLength, Aes256CbcContext* context) {
    // Generate a random IV for each cipher session
    if (RAND_bytes(context->iv, sizeof(context->iv)) != 1) {
        return 0;
    }

    unsigned char key[32];  // AES-256 uses a 256 bit key = 32 bytes
    if (!PKCS5_PBKDF2_HMAC(password, passwordLength, salt, saltLength, 1000, EVP_sha256(), sizeof(key), key)) {
        return 0;
    }

    // Initialize the cipher context with the key and IV
    if (!EVP_EncryptInit_ex(&context->ctx, EVP_aes_256_cbc(), NULL, key, context->iv)) {
        return 0;
    }

    return 1;
}

// Encryption and decryption operations use the same logic as they are symmetric ciphers
int performAesOperation(unsigned char* inData, int inLength, unsigned char** outData, Aes256CbcContext* context) {
    // Assume that the length of the output is equal to or greater than the input

    if (!EVP_EncryptUpdate(&context->ctx, *outData, &outLength, inData, inLength)) {
        return 0;
    }

    unsigned char final[16];  // AES uses a block size of 128 bits = 16 bytes
    int finalLength;
    if (!EVP_EncryptFinal_ex(&context->ctx, final, &finalLength)) {
        return 0;
    }

    *outData = realloc(*outData, outLength + finalLength);
    memcpy(*outData + outLength, final, finalLength);

    // If the operation was a decryption, you would also need to clean up the cipher context
    EVP_CIPHER_CTX_cleanup(&context->ctx);

    return 1;
}
