typedef struct BS_Array {
    pthread_mutex_t lock;
    int size;
    BS_Entity **entities;
} BS_Array;

// Initialize the array of base stations
BS_Array *init_base_stations() {
    BS_Array *arr = malloc(sizeof(BS_Array));
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Add a new base station to the array
void add_base_station(BS_Array *array, int BS_ID) {
    pthread_mutex_lock(&array->lock);  // Lock for thread safety

    // Increase size of entities array and allocate memory for new entity
    array->size++;
    array->entities = realloc(array->entities, sizeof(BS_Entity*) * array->size);
    BS_Entity *entity = malloc(sizeof(BS_Entity));
    entity->BS_ID = BS_ID;
    entity->num_sectors = 0;
    array->entities[array->size - 1] = entity;

    pthread_mutex_unlock(&array->lock);  // Unlock after operation
}

// Add a new cell sector to the base station
void add_cell_sector(BS_Array *array, int BS_ID, int sector) {
    pthread_mutex_lock(&array->lock);  // Lock for thread safety

    // Find the right entity and add the sector
    for (int i = 0; i < array->size; ++i) {
        if(array->entities[i]->BS_ID == BS_ID){
            array->entities[i]->num_sectors++;
            array->entities[i]->cell_sectors = realloc(array->entities[i]->cell_sectors, sizeof(int) * array->entities[i]->num_sectors);
            array->entities[i]->cell_sectors[array->entities[i]->num_sectors - 1] = sector;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);  // Unlock after operation
}

// Function to handle cleanup
void cleanup(BS_Array *array) {
    for (int i = 0; i < array->size; ++i) {
        free(array->entities[i]->cell_sectors);  // Free memory allocated for cell sectors
        free(array->entities[i]);                 // Free memory allocated for BS entity
    }
    free(array->entities);                         // Free memory allocated for entities array
    pthread_mutex_destroy(&array->lock);           // Destroy the mutex
}
```
