    double timestamp;
    PacketStatistics *stats;
    struct UEStats *next;
} UEStats;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

UEStats *find(int ue_id) {
    static UEStats *head = NULL;

    pthread_mutex_lock(&lock);
    for (UEStats *p = head; p != NULL; p = p->next) {
        if (p->ue_id == ue_id) {
            pthread_mutex_unlock(&lock);
            return p;
        }
    }

    UEStats *new_entry = malloc(sizeof(*new_entry));
    new_entry->ue_id = ue_id;
    new_entry->next = head;
    new_entry->stats = NULL;

    head = new_entry;
    pthread_mutex_unlock(&lock);

    return new_entry;
}

void add(int ue_id, double timestamp, PacketStatistics *stats) {
    UEStats *entry = find(ue_id);

    pthread_mutex_lock(&lock);
    if (entry->timestamp < timestamp) {
        entry->timestamp = timestamp;

        // Replace old statistics
        free(entry->stats);
        entry->stats = stats;
    } else {
        free(stats);
    }

    pthread_mutex_unlock(&lock);
}

PacketStatistics *get_latest_packet_statistics(int ue_id) {
    UEStats *entry = find(ue_id);
    return entry->stats;
}
