typedef struct {
    int UE_ID;
    // ... Other fields here...
} UEContext;

UEContext* UEContextArray[10];
int arraySize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addUEContext(UEContext *ue) {
    pthread_mutex_lock(&mutex);

    UEContextArray[arraySize] = ue;
    arraySize++;

    printf("Added UE Context with ID %d\n", ue->UE_ID);

    pthread_mutex_unlock(&mutex);
}

void removeUEContext(int id) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < arraySize; i++) {
        if (UEContextArray[i]->UE_ID == id) {
            UEContext *temp = UEContextArray[i];

            // Shift all elements to fill the gap.
            for(int j=i; j<arraySize-1; j++) {
                UEContextArray[j] = UEContextArray[j+1];
            }

            arraySize--;
            printf("Removed UE Context with ID %d\n", temp->UE_ID);
            free(temp); // This is important as we are using dynamic memory allocation.
        }
    }

    pthread_mutex_unlock(&mutex);
}
```
This example uses POSIX threads for thread safety, but it can be easily modified to use other threading libraries or synchronization primitives based on the specific requirements of your system and environment. For more complex scenarios, consider using higher-level concurrency constructs provided by libraries like OpenMP or Intel's Threading Building Blocks. 

