u_char* resolveHost(const char *hostname) {
    int i;
    for (i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            return cache[i].ip;
        }
    }

    // If not in cache, resolve using DNS API
    u_char *resolvedIP = dnsResolveAPI(hostname);
    if (resolvedIP == NULL) {
        printf("Error resolving host %s\n", hostname);
        return NULL;
    }

    // Store in cache
    strcpy(cache[cache_size].hostname, hostname);
    memcpy(cache[cache_size].ip, resolvedIP, 4);
    cache_size++;

    return resolvedIP;
}
