    SensorNode *node = malloc(sizeof(SensorNode));
    if (node == NULL) exit(-1);  // Handle memory exhaustion
    node->id = id;
    return node;
}

// Function to initialize a new device context
DeviceContext* DeviceContextInit(int Dev_ID, int numNodes) {
    DeviceContext *device = malloc(sizeof(DeviceContext));
    if (device == NULL) exit(-1);  // Handle memory exhaustion
    pthread_mutex_init(&device->lock, NULL);  // Initialize the mutex
    device->Dev_ID = Dev_ID;
    device->sensorNodes = malloc(sizeof(SensorNode) * numNodes);
    if (device->sensorNodes == NULL) exit(-1);  // Handle memory exhaustion
    return device;
}

// Function to add a sensor node to a device context
void AddSensorNode(DeviceContext* device, SensorNode* node) {
    pthread_mutex_lock(&device->lock);  // Acquire the lock
    for (int i = 0; i < device->numNodes; i++) {
        if (device->sensorNodes[i].id == 0) {  // Find an empty slot in the list
            device->sensorNodes[i] = *node;  // Add the sensor node to that slot
            break;
        }
    }
    pthread_mutex_unlock(&device->lock);  // Release the lock
}

// Function to update edge computing resource metrics
void UpdateMetrics(DeviceContext* device, Metrics newMetrics) {
    pthread_mutex_lock(&device->lock);  // Acquire the lock
    device->metrics = newMetrics;  // Update the metrics
    pthread_mutex_unlock(&device->lock);  // Release the lock
}

// Function to cleanup a device context
void DeviceContextCleanup(DeviceContext* device) {
    free(device->sensorNodes);  // Free the sensor node list
    pthread_mutex_destroy(&device->lock);  // Destroy the mutex
    free(device);  // Free the device context
}
```
