```csharp
private async Task<List<Dictionary<string, object>>> ExecuteAndMapToDictionary(SqlCommand command, int batchSize)
{
    var result = new List<Dictionary<string, object>>();

    using (var reader = await command.ExecuteReaderAsync())
    {
        while (await reader.ReadAsync())
        {
            var rowValues = new Dictionary<string, object>(reader.FieldCount);

            for (int i = 0; i < batchSize && reader.HasRows; ++i)
                rowValues[reader.GetName(i)] = await reader.GetValueAsync(i);

            result.Add(rowValues);
        }
    }

    return result;
}
```

