            printf("Insigificant data point: %d\n", args->data[i]);
        }
    }

    free(args->data);
    free(arg);
    return NULL;
}

void processFile(char *inputFileName, char *outputFileName, char *rules, double threshold, int compressFlag) {
    FILE *file = fopen(inputFileName, "rb");

    if(!file) {
        perror("Error opening file");
        return;
    }

    // Get file size
    fseek(file, 0L, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    int *data = malloc(fileSize);

    if(!fread(data, sizeof(int), fileSize/sizeof(int), file)) {
        perror("Error reading file");
        free(data);
        fclose(file);
        return;
    }

    fclose(file);

    // Assuming one data point takes up sizeof(int) bytes and that we can use all available memory
    size_t dataSize = fileSize / sizeof(int); 

    pthread_t thread;
    threadArgs *args = malloc(sizeof(threadArgs));

    args->data = data;
    args->dataSize = dataSize;
    args->rules = strdup(rules);
    args->threshold = threshold;
    args->compressFlag = compressFlag;

    if(pthread_create(&thread, NULL, processData, (void*)args)) {
        perror("Error creating thread");
        free(data);
        return;
    }

    pthread_join(thread, NULL);
}
```
