    DynamicArrayManager(int size) : buffer(size), maxSize(size) {}

    void initializeArray(const std::vector<LTE_DL_FRAME_MSG>& msgs) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& msg : msgs) {
