public class DirectoryFileProcessor {

    private static final Logger LOGGER = Logger.getLogger(DirectoryFileProcessor.class.getName());
    private static FileHandler fileTxt;
    private static SimpleFormatter formatterTxt;

    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private ConcurrentHashMap<String, Long> directoryToSizeMap = new ConcurrentHashMap<>();

    public void processFilePaths(List<String> filePaths) {
        long startTime = System.nanoTime();

        for (String path : filePaths) {
            executorService.submit(() -> {
                try {
                    Path p = Paths.get(path);
                    if (!Files.exists(p)) return;

                    directoryToSizeMap.merge(p.getParent().toString(), Files.size(p), Long::sum);
                } catch (IOException e) {
                    LOGGER.log(Level.SEVERE, "Error processing file: " + path, e);
                }
            });
        }

        executorService.shutdown();
        try {
            executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

            long endTime = System.nanoTime();
            LOGGER.info("Total execution time: " + (endTime - startTime) / 1000000 + "ms");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            LOGGER.log(Level.SEVERE, "Task interrupted", e);
        }
    }

    public Map<String, Long> getDirectoryToSizeMap() {
        return Collections.unmodifiableMap(directoryToSizeMap);
    }

    // add other methods and fields as necessary...
}
```
