    size_t numMetrics;
    NMSMetric* metrics;
} MNONode;

MNONode* createNode(int nodeId) {
    MNONode* newNode = malloc(sizeof(*newNode));
    if (newNode == NULL) {
        return NULL;  // Handle memory allocation failure
    }
    newNode->Node_ID = nodeId;
    pthread_mutex_init(&newNode->lock, NULL);
    newNode->numBaseStations = 0;
    newNode->baseStations = NULL;
    newNode->numMetrics = 0;
    newNode->metrics = NULL;
}

void addBaseStation(MNONode* node, BaseStation bs) {
    pthread_mutex_lock(&node->lock);

    // Resize the array and add the BS
    node->baseStations = realloc(node->baseStations, (node->numBaseStations + 1) * sizeof(*node->baseStations));
    if (node->baseStations == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&node->lock);
        return;
    }

    node->baseStations[node->numBaseStations] = bs;
    node->numBaseStations++;

    pthread_mutex_unlock(&node->lock);
}

void updateNMSMetrics(MNONode* node, NMSMetric metric) {
    pthread_mutex_lock(&node->lock);

    // Resize the array and add the new metric
    node->metrics = realloc(node->metrics, (node->numMetrics + 1) * sizeof(*node->metrics));
    if (node->metrics == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&node->lock);
        return;
    }

    node->metrics[node->numMetrics] = metric;
    node->numMetrics++;

    pthread_mutex_unlock(&node->lock);
}
