// Implement custom memory pool for reuse
struct MemoryPool {
    atomic_int size;
    void *blocks[50000];
};

void MemoryPoolInit(struct MemoryPool* pool) {
    atomic_init(&pool->size, 0);
}

void* MemoryPoolAlloc(struct MemoryPool* pool) {
    int index = atomic_fetch_add(&pool->size, 1) % 50000;
    return pool->blocks[index];
}

// Implement concurrent queue for thread safety
typedef struct ConcurrentQueueNode {
    NFAPI_CRC_INDICATION_PDU_T *value;
    atomic_int next;
} ConcurrentQueueNode;

struct ConcurrentQueue {
    atomic_int head, tail;
    ConcurrentQueueNode nodes[10000];
};

void ConcurrentQueueInit(struct ConcurrentQueue* q) {
    atomic_init(&q->head, 0);
    atomic_init(&q->tail, 0);
}

void ConcurrentQueueEnqueue(struct ConcurrentQueue* q, NFAPI_CRC_INDICATION_PDU_T *value) {
    int tail = atomic_fetch_add(&q->tail, 1) % 10000;
    q->nodes[tail].value = value;
    atomic_store(&q->nodes[tail].next, -1);
}

// Your function implementation
