    bool CRC_INDICATION_REL15_TAG;
};

std::mutex mtx;
std::queue<LTE_PHY_RX_UE_INFO_TAG*> queue;

void enqueue(LTE_PHY_RX_UE_INFO_TAG* tag) {
    std::lock_guard<std::mutex> lock(mtx);
    queue.push(tag);
}

LTE_PHY_RX_UE_INFO_TAG* dequeue() {
    std::lock_guard<std::mutex> lock(mtx);
    if (queue.empty()) return nullptr;

    LTE_PHY_RX_UE_INFO_TAG* tag = queue.front();
    queue.pop();
    return tag;
}

uint8_t* resolveHostname(std::string hostname) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname.c_str(), NULL, &hints, &res) != 0) {
        std::cerr << "Failed to resolve hostname: " << gai_strerror(errno) << std::endl;
        return nullptr;
    }

    uint8_t* ip = (uint8_t*)&((struct sockaddr_in*)res->ai_addr)->sin_addr.s_addr;
    freeaddrinfo(res);
    return ip;
}

