```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UE_ID;
    // other fields for RRC and PDCP stats...
} UEContext;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t size;
    UEContext *contexts;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initialCapacity) {
    DynamicArray *arr = malloc(sizeof(*arr));
    if (!arr) return NULL;

    arr->capacity = initialCapacity;
    arr->size = 0;
    arr->contexts = calloc(initialCapacity, sizeof(*arr->contexts));
    if(!arr->contexts) {
        free(arr);
        return NULL;
    }

    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

int add_ue_to_array(DynamicArray *arr, UEContext context) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->size >= arr->capacity) {
        size_t newCapacity = arr->capacity ? arr->capacity*2 : 1;
        UEContext *newArray = realloc(arr->contexts, newCapacity * sizeof(*newArray));
        if(!newArray) {
            pthread_mutex_unlock(&arr->mutex);
            return -1; // Failed to allocate memory.
        }

        arr->capacity = newCapacity;
        arr->contexts = newArray;
    }

    arr->contexts[arr->size++] = context;

    pthread_mutex_unlock(&arr->mutex);
    return 0; // Success.
}

void destroy_dynamic_array(DynamicArray *arr) {
    pthread_mutex_destroy(&arr->mutex);
    free(arr->contexts);
    free(arr);
}
```
This code provides a simple dynamic array structure that can manage UE contexts. It uses a mutex for thread safety when adding new UE contexts, and automatically resizes the array as needed to ensure efficient memory usage. Note that this is just a starting point and does not include all the features you requested such as communication with an NMS, logging or error handling. You would need to expand on this code to implement these additional features.
