} Transaction;

double max_transaction(Transaction *transactions, size_t num_transactions) {
  double max = 0.0;
  for (size_t i = 0; i < num_transactions; ++i) {
    if (transactions[i].amount > max) {
      max = transactions[i].amount;
    }
  }
  return max;
}

double process_transaction(const char *dirpath) {
  DIR *dir = opendir(dirpath);
  if (dir == NULL) {
    perror("Failed to open directory");
    exit(EXIT_FAILURE);
  }

  struct dirent *entry;
  size_t num_transactions = 0;
  Transaction *all_transactions = NULL;
  while ((entry = readdir(dir)) != NULL) {
    if (entry->d_type == DT_REG && strstr(entry->d_name, ".csv") != NULL) {
      FILE *file = fopen(entry->d_name, "r");
      if (file == NULL) {
        perror("Failed to open file");
        continue;
      }

      size_t num_lines = 0;
      char line[128]; /* Adjust the buffer size as needed */
      while (fgets(line, sizeof(line), file) != NULL) {
        ++num_lines;
        all_transactions = realloc(all_transactions, num_transactions * sizeof(*all_transactions));
        if (sscanf(line, "%lf", &all_transactions[num_transactions].amount) != 1) {
          /* If we fail to read a transaction amount then skip this line */
          continue;
        }
        ++num_transactions;
      }

      fclose(file);
    }
  }

  double total = 0.0;
  for (size_t i = 0; i < num_transactions; ++i) {
    total += all_transactions[i].amount;
  }

  printf("Maximum transaction amount: %.2f\n", max_transaction(all_transactions, num_transactions));

  free(all_transactions);
  closedir(dir);

  return total;
}
```
