['The problem you are asking is rather complex and involves many different aspects of programming, networking, and system design. Writing code to implement all these features in a single function will be quite extensive. However, I can provide a simplified example of how such a resolver might look like:

```c
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <netdb.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct {
    u_char ipv4[4];
    u_char ipv6[16];
} IPAddr;

IPAddr resolveHostname(const char *hostname) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[100];
    void *ptr;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo(hostname, NULL, &hints, &res);
    if (errcode != 0) {
        perror("getaddrinfo");
        return;
    }

    printf("\nIP addresses for %s:\n\n", hostname);
    while (res) {
        inet_ntop(res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *)res->ai_addr)->sin_addr;
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *)res->ai_addr)->sin6_addr;
                inet_ntop(res->ai_family, ptr, addrstr, 100);
                break;
            default:
                return; // Unknown address type.
        }
        printf("\t%s\n", addrstr);
        res = res->ai_next;
    }
}
```
This code provides the basic functionality for resolving a hostname to an IP address, but it does not include any of the advanced features you requested such as distributed caching or integration with monitoring framework. Implementing these features would require a more comprehensive system design and possibly leveraging existing libraries and frameworks. 

