    if (currentIndex < MAX_UE) {
        pthread_mutex_lock(&arrayMutex);
            UE[currentIndex] = *ue;
            pthread_mutex_init(&(UE[currentIndex].mutex), NULL);
            currentIndex++;
        pthread_mutex_unlock(&arrayMutex);
