    async fn process_service_and_count_lines(&self) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let path = Path::new(&self.file_path);

        // Validate file exists and has correct extension
        if !path.exists() || path.extension().unwrap_or_else(|| "") != "service" {
            return Err("Invalid file path or extension".into());
        }

        let mut file = match fs::File::open(&self.file_path) {
            Ok(f) => f,
            Err(e) => return Err(formatErr(io::ErrorKind::Other, e)),
        };

        // Read the file asynchronously line by line
        let mut reader = io::BufReader::new(file);
        let mut count = 0;

        loop {
            match reader.read_line() {
                Ok(s) if s == "" => break, // end of file

                Ok(s) => {
                    // Skip commented lines
                    if !s.starts_with("//") { 
                        count += 1; 
                    }
                },

                Err(e) => return Err(formatErr(io::ErrorKind::Other, e)),
            }
        }

        printlnMoveCount(count);

        Ok(())
    }
}
