#include <stdlib.h>

typedef struct {
    uint32_t UE_ID;
    // Add other necessary data members like RRC entities list and RLC buffer statistics
} UEContext;

UEContext** ue_contexts = NULL;
size_t num_ues = 0;

void addUE(uint32_t id) {
    num_ues++;
    if (num_ues == 1) {
        ue_contexts = malloc(sizeof(UEContext*));
    } else {
        ue_contexts = realloc(ue_contexts, sizeof(UEContext*) * num_ues);
    }

    if (ue_contexts == NULL) {
        // Handle error case for memory allocation failure
        return;
    }

    ue_contexts[num_ues - 1] = malloc(sizeof(UEContext));
    ue_contexts[num_ues - 1]->UE_ID = id;
}

void removeUE(uint32_t id) {
    for (size_t i = 0; i < num_ues; ++i) {
        if (ue_contexts[i]->UE_ID == id) {
            free(ue_contexts[i]);

            // Move all UE contexts after the deleted one back by 1 to fill the gap.
            for (size_t j = i; j < num_ues - 1; ++j) {
                ue_contexts[j] = ue_contexts[j + 1];
            }

            num_ues--;
            break;
        }
    }
}

void cleanupUEContexts() {
    for (size_t i = 0; i < num_ues; ++i) {
        free(ue_contexts[i]);
    }

    free(ue_contexts);
    ue_contexts = NULL;
    num_ues = 0;
}
```

