typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_LTE_UE_Context_Information;

struct BufferNode {
    double signalStrength;
    struct BufferNode *next;
};
typedef struct BufferNode BufferNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
atomic_int count = 0;
double correctionFactor = 1.0;
BufferNode *head = NULL;

void updateCorrectionFactor() {
    pthread_mutex_lock(&lock);
    double sumSignalStrength = 0, countSignals = 0;
    BufferNode *node = head;
    while (node != NULL) {
        sumSignalStrength += node->signalStrength;
        countSignals += 1.0;
        node = node->next;
    }

    if(countSignals > 0){
        correctionFactor = 1 / ((double)(sumSignalStrength) / (double)(countSignals));
    }
    pthread_mutex_unlock(&lock);
}

void *signalStrengthUpdater() {
    while (1) {
        double signalStrength = getSignalStrengthFromDataSource(); // placeholder for function to retrieve data from external source

        BufferNode *node = malloc(sizeof(BufferNode));
        node->signalStrength = correctionFactor * signalStrength;
        pthread_mutex_lock(&lock);
        node->next = head;
        head = node;
        count++;
        pthread_mutex_unlock(&lock);

        if (count > SOME_THRESHOLD) { // placeholder for threshold variable
            updateCorrectionFactor();
            BufferNode *last = NULL, *current = head;
            for (int i = 0; i < count - SOME_THRESHOLD; ++i) {
                last = current;
                current = current->next;
            }

            if (last != NULL){
                last->next = NULL;
            } else {
                head = NULL;
            }

            while(current != NULL) {
                BufferNode *temp = current;
                current = current->next;
                free(temp);
            }
        }
    }
}
``` 

