['```c
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>

char* generate_filename(const char* original) {
    if (strlen(original) == 0 || strlen(original) > 255 || original[0] == '.') {
        return NULL; // Invalid filename
    }

    const char* dot = strrchr(original, '.');
    if (!dot || dot == original) {
        return NULL; // No file extension or hidden file
    }

    size_t base_len = (size_t)(dot - original);
    size_t ext_len = strlen(dot + 1);

    char* new_filename = malloc(base_len + ext_len + 20); // Timestamp (YYYYMMDDHHMMSS) + 1 for null terminator
    if (!new_filename) {
        return NULL; // Memory allocation failed
    }

    strncpy(new_filename, original, base_len);

    srand((unsigned int)time(NULL));
    char rand_str[base_len + 1];
    for (size_t i = 0; i < base_len; ++i) {
        int randomChar = rand() % (26 + 26 + 10);
        if (randomChar < 26)
            rand_str[i] = 'a' + randomChar;
        else if (randomChar < 52)
            rand_str[i] = 'A' + randomChar - 26;
        else
            rand_str[i] = '0' + randomChar - 52;
    }
    rand_str[base_len] = 0;

    strcat(new_filename, "_");
    strcat(new_filename, rand_str);
    strcat(new_filename, dot);

    time_t now = time(NULL);
    struct tm* timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", timeinfo);
    strcat(new_filename, "_");
    strcat(new_filename, timestamp);

    return new_filename;
}
```
